window.BASAIR_QUESTIONS=window.BASAIR_QUESTIONS.concat([{"id":"s3-7","number":7,"surah":3,"verses":[3],"verseLabel":"آل عمران: 3","question":"لماذا سمّى القرآن هنا ﴿الكتاب﴾ ولم يقل: القرآن؟","answer":"اسم ﴿الكتاب﴾ يبرز معنى الجمع والتدوين والثبوت والمرجعية، وهو الأنسب في سياق مقابلة القرآن بالكتب السابقة وإثبات وحدة مصدرها.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص508.","url":""}]},{"id":"s3-8","number":8,"surah":3,"verses":[3],"verseLabel":"آل عمران: 3","question":"ما سرّ التعبير في قوله تعالى: ﴿مصدقًا لما بين يديه﴾، وكيف يكون للكتاب يدان؟","answer":"هذه كناية مأخوذة من وجود الشيء أمام الإنسان وبين يديه؛ أي إن القرآن يوافق ما سبقه من الوحي الحق ويشهد لأصوله، لا أن للكتاب يدين حقيقة.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص501–512.","url":""}]},{"id":"s3-9","number":9,"surah":3,"verses":[3],"verseLabel":"آل عمران: 3","question":"ما سرّ التعبير في قوله تعالى: ﴿من قبل﴾ بعد ذكر التوراة والإنجيل، مع أن سبقهما معلوم؟","answer":"جيء بـ﴿مِنْ قَبْلُ﴾ لتأكيد سبق التوراة والإنجيل للقرآن في النزول، وأن هدايتهما للناس كانت قبل نزوله؛ فالقيد يحدد زمن الهداية المذكورة.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص501–512.","url":""}]},{"id":"s3-10","number":10,"surah":3,"verses":[4],"verseLabel":"آل عمران: 4","question":"لماذا سُمّيت الكتب السابقة ﴿هدى للناس﴾، ثم أفرد ﴿الفرقان﴾ بالذكر؟","answer":"وُصفت التوراة والإنجيل بأنهما هدى للناس، ثم خُص الفرقان بالذكر لإبراز وظيفة الوحي في الفصل بين الحق والباطل، وهي أنسب بمقام محاجة أهل الكتاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص513–523.","url":""}]},{"id":"s3-11","number":11,"surah":3,"verses":[4],"verseLabel":"آل عمران: 4","question":"ما سرّ التعبير في قوله تعالى في عقوبة المكذبين ﴿لهم عذاب شديد﴾ لا أليم أو عظيم؟","answer":"الشدة وصف لقوة العذاب وصلابته، أما ﴿أليم﴾ فيلحظ الألم و﴿عظيم﴾ يلحظ كبر القدر؛ فناسب ﴿شديد﴾ مقام وعيد المقاومين للبينات بقوة الأخذ.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص513–523.","url":""}]},{"id":"s3-12","number":12,"surah":3,"verses":[4],"verseLabel":"آل عمران: 4","question":"لماذا ختم الآية بـ﴿والله عزيز ذو انتقام﴾؟","answer":"ناسبت ﴿عَزِيزٌ ذُو انْتِقَامٍ﴾ وعيد من كفر بآيات الله: فالعزيز لا يُغلب ولا يفوته معاند، وذو الانتقام يعاقب من استحق العقوبة بعد قيام الحجة.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص523.","url":""}]},{"id":"s3-13","number":13,"surah":3,"verses":[4],"verseLabel":"آل عمران: 4","question":"ما سرّ التعبير في قوله تعالى: ﴿ذو انتقام﴾، دون أن يقال: منتقم؟","answer":"التعبير بـ﴿ذُو انْتِقَامٍ﴾ يجعل الانتقام وصفًا ثابتًا متمكنًا ويدل على القدرة عليه؛ وهو أقوى في مقام الوعيد من مجرد الإخبار بالفعل.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص523.","url":""}]},{"id":"s3-14","number":14,"surah":3,"verses":[5],"verseLabel":"آل عمران: 5","question":"ما سرّ التعبير في قوله تعالى: ﴿لا يخفى عليه شيء في الأرض ولا في السماء﴾، وقدم الأرض على السماء؟","answer":"قُدمت الأرض لأن السياق يتجه إلى أحوال البشر وما يخفونه، ثم عُمم العلم بالسماء؛ فابتدأ بالأقرب إلى المخاطبين وموضع الوقائع المقصودة.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص523–528.","url":""}]},{"id":"s3-15","number":15,"surah":3,"verses":[5],"verseLabel":"آل عمران: 5","question":"لماذا نكّر ﴿شيء﴾ في سياق نفي الخفاء؟","answer":"جاءت ﴿شَيْءٌ﴾ نكرةً في سياق النفي، فتعم كل موجود وكل قدر من الخفاء؛ أي لا يخفى على الله أدنى شيء في الأرض ولا في السماء، ظاهرًا كان أو باطنًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص523–528.","url":""}]},{"id":"s3-16","number":16,"surah":3,"verses":[6],"verseLabel":"آل عمران: 6","question":"ما سرّ التعبير في قوله تعالى: ﴿يصوركم في الأرحام كيف يشاء﴾، دون أن يقال: يخلقكم؟","answer":"التصوير أخص من مطلق الخلق؛ فهو إنشاء كل إنسان على هيئة وصفة متميزة في الرحم، ولذلك ناسب قوله ﴿كَيْفَ يَشَاءُ﴾ الدال على تنوع الصور.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص528–534.","url":""}]},{"id":"s3-17","number":17,"surah":3,"verses":[6],"verseLabel":"آل عمران: 6","question":"لماذا جمع ﴿الأرحام﴾ مع أن كل إنسان يتكوّن في رحم واحدة؟","answer":"جُمعت ﴿الأَرْحَامِ﴾ لتعددها بتعدد الأمهات والأجيال، وليشمل الحكم كل موضع يجري فيه تصوير البشر، وإن كان كل فرد يتكون في رحم واحدة.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص528–534.","url":""}]},{"id":"s3-18","number":18,"surah":3,"verses":[6],"verseLabel":"آل عمران: 6","question":"لماذا ختم آية التصوير بـ﴿لا إله إلا هو العزيز الحكيم﴾؟","answer":"العزة تثبت نفاذ القدرة، والحكمة تثبت أن هذا النفاذ موضوع في موضعه بلا عبث ولا ظلم.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص528–534.","url":""}]},{"id":"s3-19","number":19,"surah":3,"verses":[7],"verseLabel":"آل عمران: 7","question":"لماذا قسّم آيات الكتاب إلى محكمات ومتشابهات؟","answer":"ليكون المحكم أصلًا يُردّ إليه المتشابه، وليمتحن قصد المتلقي: فالراسخ يطلب الجمع والهداية، وصاحب الزيغ يقتطع المتشابه طلبًا للفتنة.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص534–551.","url":""}]},{"id":"s3-20","number":20,"surah":3,"verses":[7],"verseLabel":"آل عمران: 7","question":"ما سرّ التعبير في قوله تعالى عن المحكمات ﴿هن أم الكتاب﴾ بإفراد ﴿أم﴾؟","answer":"الأم هي الأصل الذي يُرجع إليه ويتفرع عنه غيره؛ فالمحكمات مرجع فهم المتشابه وضابطه، والإفراد لأن مجموعها بمنزلة أصل واحد جامع.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص543.","url":""}]},{"id":"s3-21","number":21,"surah":3,"verses":[7],"verseLabel":"آل عمران: 7","question":"ما سرّ التعبير في قوله تعالى: ﴿فأما الذين في قلوبهم زيغ﴾، فجعل الزيغ داخل القلوب؟","answer":"صُوّر الزيغ كأنه مستقر في داخل القلب للدلالة على أنه ميل راسخ في الباطن، لا مجرد خطأ عابر في الفهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص534–551.","url":""}]},{"id":"s3-22","number":22,"surah":3,"verses":[7],"verseLabel":"آل عمران: 7","question":"لماذا قدّم ابتغاء الفتنة على ابتغاء التأويل؟","answer":"لأن إرادة الفتنة هي الدافع أولًا، ثم يُتخذ طلب التأويل وسيلةً لها؛ فرتب النظم الباعث قبل الأداة وكشف فساد القصد قبل فساد المسلك.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص534–551.","url":""}]},{"id":"s3-23","number":23,"surah":3,"verses":[7],"verseLabel":"آل عمران: 7","question":"كيف يوصف القرآن كله بأنه محكم، وكله متشابه، ثم يقال إن منه محكمًا ومتشابهًا؟","answer":"إحكام القرآن كله يعني إتقانه وانتفاء التناقض عنه، وتشابهه كله يعني تصديق بعضه بعضًا وتماثله في الحق والحسن؛ أما التقسيم هنا فبين آيات واضحة الأصل وأخرى تحتمل فتُرد إلى المحكم.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص534–551؛ مسح الويب.","url":""}]},{"id":"s3-24","number":24,"surah":3,"verses":[7],"verseLabel":"آل عمران: 7","question":"ما سرّ التعبير في قوله تعالى: ﴿والراسخون في العلم﴾، دون أن يقال: والعلماء؟","answer":"الرسوخ ثبات وتمكن، فكأن العلم أصل ثابت في نفوسهم؛ وليس كل من عرف مسألة من الراسخين. واللفظ يناسب ثباتهم أمام المتشابه وردّه إلى المحكم.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص534–551.","url":""}]},{"id":"s3-25","number":25,"surah":3,"verses":[7],"verseLabel":"آل عمران: 7","question":"ما دلالة قول الراسخين: ﴿كُلٌّ مِنْ عِنْدِ رَبِّنَا﴾، وعدم اتباعهم المتشابه طلبًا للفتنة؟","answer":"قولهم ﴿كُلٌّ مِنْ عِنْدِ رَبِّنَا﴾ إيمان بالمحكم والمتشابه جميعًا وردّ للمتشابه إلى المحكم؛ فمقصدهم الهداية والتسليم، لا اتباع المتشابه طلبًا للفتنة.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص534–551.","url":""}]},{"id":"s3-26","number":26,"surah":3,"verses":[7],"verseLabel":"آل عمران: 7","question":"لماذا ختمت الآية بـ﴿وما يذكر إلا أولو الألباب﴾؟","answer":"لا ينتفع بمنهج رد المتشابه إلى المحكم إلا أصحاب العقول الخالصة من الهوى؛ لذلك خُتمت الآية بقصر التذكر على ﴿أُولُو الأَلْبَابِ﴾.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص534–551.","url":""}]},{"id":"s3-27","number":27,"surah":3,"verses":[8],"verseLabel":"آل عمران: 8","question":"لماذا دعا الراسخون ﴿ربنا لا تزغ قلوبنا﴾ بعد أن وصف الله أهل الزيغ؟","answer":"لما ذكرت الآية زيغ من اتبعوا المتشابه، قابل الراسخون ذلك بالخوف من زيغ القلب وسؤال الثبات؛ وفي الدعاء اعتراف بأن الهداية فضل من الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص551–558.","url":""}]},{"id":"s3-28","number":28,"surah":3,"verses":[8],"verseLabel":"آل عمران: 8","question":"ما سرّ قول الراسخين: ﴿لَا تُزِغْ قُلُوبَنَا﴾ دون «لا تجعلنا زائغين»؟","answer":"خُصت القلوب لأنها موضع الاعتقاد والقصد، ومنها يبدأ الميل عن الحق؛ فسؤالهم حراسة القلب يطلب سلامة الأصل الذي تتبعه الأقوال والأعمال.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص551–558.","url":""}]},{"id":"s3-29","number":29,"surah":3,"verses":[8],"verseLabel":"آل عمران: 8","question":"ما سرّ قولهم: ﴿هَبْ لَنَا﴾ دون «أعطنا»؟","answer":"الهبة عطاء تفضّل لا يقابله عوض ولا استحقاق؛ فاختيرت اعترافًا بأن الثبات والرحمة محض فضل من الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص555.","url":""}]},{"id":"s3-30","number":30,"surah":3,"verses":[8],"verseLabel":"آل عمران: 8","question":"ما سرّ قولهم: ﴿مِنْ لَدُنْكَ رَحْمَةً﴾ دون «من عندك»؟","answer":"﴿لدن﴾ أخص من ﴿عند﴾، وتوحي بقرب العطاء وخصوصيته وصدوره مباشرة من خزائن الرحمة الإلهية.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص556.","url":""}]},{"id":"s3-31","number":31,"surah":3,"verses":[8],"verseLabel":"آل عمران: 8","question":"لماذا ختم الدعاء بـ﴿إنك أنت الوهاب﴾ مع أنهم طلبوا الثبات والرحمة؟","answer":"طلبوا هبة الرحمة فقالوا ﴿هَبْ لَنَا﴾، فناسب أن يختموا باسم ﴿الْوَهَّابُ﴾؛ و﴿أَنْتَ﴾ تؤكد أن الهبة المطلقة منه وحده.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص551–558.","url":""}]},{"id":"s3-32","number":32,"surah":3,"verses":[9],"verseLabel":"آل عمران: 9","question":"ما سرّ التعبير في قوله تعالى: ﴿جامع الناس ليوم لا ريب فيه﴾، دون أن يقال: في يوم؟","answer":"اللام تجعل الجمع واقعًا لأجل ذلك اليوم ومصيره، فتوجّه النظر إلى غاية الحشر والحساب، لا إلى مجرد وقوع الناس داخل زمنه.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص558–564.","url":""}]},{"id":"s3-33","number":33,"surah":3,"verses":[9],"verseLabel":"آل عمران: 9","question":"لماذا عُلّل الجمع للقيامة بقوله ﴿إن الله لا يخلف الميعاد﴾؟","answer":"الخاتمة تعلل اليقين بما قبلها؛ فالوعد صادر ممن يستحيل في حقه الخلف.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص558–564.","url":""}]},{"id":"s3-34","number":34,"surah":3,"verses":[10],"verseLabel":"آل عمران: 10","question":"ما سرّ التعبير في قوله تعالى: ﴿لن تغني عنهم أموالهم ولا أولادهم من الله شيئًا﴾ فقدم الأموال؟","answer":"قُدمت الأموال لأنها أبرز ما يظن صاحبه أنه يدفع به الضر ويشتري النجاة، ثم ذُكر الأولاد لما فيهم من قوة ونصرة؛ ونُفي نفع الأمرين أمام حكم الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص564–581.","url":""}]},{"id":"s3-35","number":35,"surah":3,"verses":[10],"verseLabel":"آل عمران: 10","question":"لماذا شبّه الكافرين بأنهم ﴿وقود النار﴾ لا أصحاب النار فقط؟","answer":"التعبير أبلغ من مجرد دخول النار؛ إذ يصوّرهم مادة تتقد بها النار، جزاءً لمن أوقدوا أسباب الكفر والفتنة في الدنيا.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص564–581.","url":""}]},{"id":"s3-36","number":36,"surah":3,"verses":[116],"verseLabel":"آل عمران: 10؛ آل عمران: 116","question":"لماذا انتهت الآية 10 بـ﴿وأولئك هم وقود النار﴾، بينما انتهت الآية 116 بعد الصدر نفسه بـ﴿وأولئك أصحاب النار هم فيها خالدون﴾؟","answer":"الآية الأولى في مقام الوعيد القريب بعد ذكر الكفر فصورتهم مادةً تتقد بها النار، أما الثانية فجاءت بعد تفصيل أعمالهم المنفقة فقررت استقرارهم ودوام صحبتهم للنار؛ فاختير لكل مقام ما يتم معناه.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص564–581؛ ج5، ص608–621.","url":""}]},{"id":"s3-37","number":37,"surah":3,"verses":[11],"verseLabel":"آل عمران: 11","question":"لماذا شُبّه حالهم بـ﴿دأب آل فرعون والذين من قبلهم﴾؟","answer":"الدأب هو العادة والحال الملازمة؛ فشُبه شأن هؤلاء في التكذيب وما يعقبه من العقاب بحال آل فرعون ومن قبلهم، تنبيهًا إلى ثبات سنة الجزاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص581–597.","url":""}]},{"id":"s3-38","number":38,"surah":3,"verses":[11],"verseLabel":"آل عمران: 11","question":"ما سرّ التعبير في قوله تعالى: ﴿فأخذهم الله بذنوبهم﴾؟ وما صورة الأخذ هنا؟","answer":"الأخذ يصور العقوبة قوية محيطة لا يستطيع المعاقَب الإفلات منها، والباء في ﴿بِذُنُوبِهِمْ﴾ تبين أن ذنوبهم سبب هذا الأخذ.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص581–597.","url":""}]},{"id":"s3-39","number":39,"surah":3,"verses":[11],"verseLabel":"آل عمران: 11","question":"لماذا ختم بقوله ﴿والله شديد العقاب﴾ بعد ذكر آل فرعون؟","answer":"الخاتمة تحول الخبر إلى وعيد حاضر، وتبين أن الأخذ المذكور أثر من آثار شدة العقاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص581–597.","url":""}]},{"id":"s3-40","number":40,"surah":3,"verses":[11],"verseLabel":"آل عمران: 11","question":"ما سرّ اختلاف التعبير بين قوله تعالى في آل عمران عن آل فرعون ﴿كذبوا بآياتنا﴾، وقوله تعالى في الأنفال مرة ﴿كفروا بآيات الله﴾ ومرة ﴿كذبوا بآيات ربهم﴾؟","answer":"جاء ﴿كَذَّبُوا بِآيَاتِنَا﴾ في سياق عرض دأبهم وتكذيبهم، فناسب ضمير المتكلم عظمة الآيات ومقام الخطاب. وفي الأنفال روعي السياق: فذُكر اسم الله مع الكفر، ولفظ الرب مع التكذيب بآياته.","sources":[{"label":"موسوعة التفسير البلاغي، الموضع العكسي: ج16، ص330–331.","url":""}]},{"id":"s3-41","number":41,"surah":3,"verses":[12],"verseLabel":"آل عمران: 12","question":"ما دلالة الإخبار عن الكافرين بصيغة الاستقبال: ﴿سَتُغْلَبُونَ وَتُحْشَرُونَ إِلَى جَهَنَّمَ﴾؟","answer":"صيغة الاستقبال في ﴿سَتُغْلَبُونَ وَتُحْشَرُونَ﴾ خبر صادق ووعيد قبل وقوعه، وفيها تثبيت للمؤمنين وإنذار للكافرين بأن غلبة الدنيا يعقبها الحشر.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص597–604.","url":""}]},{"id":"s3-42","number":42,"surah":3,"verses":[12],"verseLabel":"آل عمران: 12","question":"ما سرّ التعبير في قوله تعالى: ﴿وبئس المهاد﴾ فوصف جهنم بالمهاد الذي يُوطأ للنوم؟","answer":"سمّى النار مهادًا على سبيل التهكم؛ فالمهاد موضع الراحة، أما هذا المهاد فغاية العذاب، وفي التضاد زيادة تهويل.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص597–604.","url":""}]},{"id":"s3-43","number":43,"surah":3,"verses":[13],"verseLabel":"آل عمران: 13","question":"لماذا جعل لقاء الفئتين ﴿آية﴾ للمشاهدين؟","answer":"كان التفاوت بين الفئتين مع نصر المؤمنين علامة مشاهدة على أن التأييد ليس تابعًا للعدد وحده، ولذلك سميت الواقعة ﴿آيَةً﴾ ودليلًا للاعتبار.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص604–615.","url":""}]},{"id":"s3-44","number":44,"surah":3,"verses":[13],"verseLabel":"آل عمران: 13","question":"ما سرّ التعبير في قوله تعالى: ﴿فئة تقاتل في سبيل الله وأخرى كافرة﴾، فذكر غاية الأولى ووصف الثانية؟","answer":"ذُكرت غاية الفئة المؤمنة لأنها تقاتل ﴿فِي سَبِيلِ اللَّهِ﴾، أما الأخرى فعُرفت بأصل موقفها ﴿كَافِرَةٌ﴾؛ فظهرت المقابلة بين الإيمان والكفر.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص604–615.","url":""}]},{"id":"s3-45","number":45,"surah":3,"verses":[13],"verseLabel":"آل عمران: 13","question":"ما سرّ التعبير في قوله تعالى: ﴿يرونهم مثليهم رأي العين﴾؟ ومن الذي رأى مَن؟","answer":"يحتمل الضمير، بحسب القراءة والتفسير، أن يرى الكافرون المؤمنين مثليهم، أو يرى المؤمنون الكافرين مثلي عدد المؤمنين؛ والمقصود أن الرؤية صارت موضع عبرة، فلا يحصر الجواب في وجه واحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص604–615.","url":""}]},{"id":"s3-46","number":46,"surah":3,"verses":[13],"verseLabel":"آل عمران: 13","question":"لماذا ختم العبرة بـ﴿إن في ذلك لعبرة لأولي الأبصار﴾ لا أولي الألباب؟","answer":"خُص ﴿أُولِي الأَبْصَارِ﴾ لأن الآية تتحدث عن فئتين التقتا وعن رؤية رأي العين؛ فناسبها لفظ الأبصار، مع إرادة البصيرة التي تعبر من المشهد إلى دلالته.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص612.","url":""}]},{"id":"s3-47","number":47,"surah":3,"verses":[14],"verseLabel":"آل عمران: 14","question":"لماذا بُني الفعل للمجهول في ﴿زُيّن للناس حب الشهوات﴾؟","answer":"بُني ﴿زُيِّنَ﴾ للمجهول لتوجيه النظر إلى وقوع التزيين وإلى المزينات، لا إلى تعيين فاعله؛ فيتسع لما جُبلت عليه النفس وما يزينه الشيطان لها، وكل ذلك تحت تقدير الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص615–630.","url":""}]},{"id":"s3-48","number":48,"surah":3,"verses":[14],"verseLabel":"آل عمران: 14","question":"ما سرّ التعبير في قوله تعالى: ﴿حب الشهوات﴾ لا الشهوات نفسها؟","answer":"المذموم ليس وجود الأشياء النافعة في ذاتها، بل تعلق القلب الشهواني بها؛ لذلك عُلّق التزيين بحبها لا بأعيانها.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص615–630.","url":""}]},{"id":"s3-49","number":49,"surah":3,"verses":[14],"verseLabel":"آل عمران: 14","question":"لماذا بدأ تعداد الشهوات بالنساء ثم البنين؟","answer":"بدأ بأشد الشهوات اتصالًا بالنفس واستمرارًا في العمر، ثم بما يتولد عنها من طلب الذرية والعزوة؛ فانتقل من أصل الميل إلى أبرز ثماره الاجتماعية.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص615–630.","url":""}]},{"id":"s3-50","number":50,"surah":3,"verses":[14],"verseLabel":"آل عمران: 14","question":"لماذا ذُكر البنون دون البنات؟","answer":"الآية تصف ما كان محل التفاخر والقوة في عرف المخاطبين، وكان البنون عندهم عنوان العزوة والنصرة؛ فهي تكشف شهوة الواقع ولا تنتقص قدر البنات.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص625.","url":""}]},{"id":"s3-51","number":51,"surah":3,"verses":[14],"verseLabel":"آل عمران: 14","question":"ما سرّ التعبير في قوله تعالى: ﴿القناطير المقنطرة﴾ فكرر المادة؟","answer":"اشتق الوصف من الاسم للمبالغة، كأنه مال بلغ الغاية في التكثير والتكديس، فيجسّم فتنة الثروة في النفس.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص615–630.","url":""}]},{"id":"s3-52","number":52,"surah":3,"verses":[14],"verseLabel":"آل عمران: 14","question":"لماذا خُص الذهب والفضة والخيل والأنعام والحرث في تعداد المتاع؟","answer":"لأنها جمعت أصول الثروة التي عرفها المخاطبون: النقد، ومظهر القوة والزينة، والحيوان، والأرض المنتجة؛ فاستوعب التعداد وجوه التملك والانتفاع.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص615–630.","url":""}]},{"id":"s3-53","number":53,"surah":3,"verses":[14],"verseLabel":"آل عمران: 14","question":"لماذا ختم التعداد بـ﴿ذلك متاع الحياة الدنيا والله عنده حسن المآب﴾؟","answer":"ردّت الخاتمة الأشياء المعدودة إلى حقيقتها: متاع قريب زائل، وقابلته بحسن المرجع عند الله؛ فصححت ميزان المفاضلة بين عاجل محبوب وآجل باق.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص615–630.","url":""}]},{"id":"s3-54","number":54,"surah":3,"verses":[15],"verseLabel":"آل عمران: 15","question":"ما سرّ التعبير في قوله تعالى: ﴿قل أؤنبئكم بخير من ذلكم﴾ على صورة سؤال لا تقرير؟","answer":"جاء الاستفهام للتشويق؛ فبعد عرض شهوات الدنيا يوقظ السامع إلى موازنة ينتظر جوابها، فيكون تلقي نعيم الآخرة أشد أثرًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص630–643.","url":""}]},{"id":"s3-55","number":55,"surah":3,"verses":[15],"verseLabel":"آل عمران: 15","question":"لماذا قابل شهوات الدنيا بـ﴿جنات تجري من تحتها الأنهار﴾ و﴿أزواج مطهرة﴾ و﴿رضوان﴾؟","answer":"قوبلت الشهوات الدنيوية بما هو خير وأبقى: جنات بدل الحرث، وأزواج مطهرة بدل الشهوة العارضة، وفوق ذلك رضوان الله؛ فالمقابلة توجه الميل الفطري إلى غايته الطاهرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص630–643.","url":""}]},{"id":"s3-56","number":56,"surah":3,"verses":[15],"verseLabel":"آل عمران: 15","question":"لماذا ختم بـ﴿والله بصير بالعباد﴾ لا عليم؟","answer":"البصر أنسب بمقام الأعمال والمواقف المشاهدة، وفيه مراقبة ووعد أو وعيد بحسب السياق.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص630–643.","url":""}]},{"id":"s3-57","number":57,"surah":3,"verses":[16],"verseLabel":"آل عمران: 16","question":"ما سرّ وصف المتقين بالموصول في قوله تعالى: ﴿الَّذِينَ يَقُولُونَ رَبَّنَا إِنَّنَا آمَنَّا﴾؟","answer":"جاء وصف المتقين بالموصول ﴿الَّذِينَ يَقُولُونَ﴾ ليجعل دعاءهم وإقرارهم بالإيمان صلة كاشفة عن حالهم، ويبين أن رجاء المغفرة والوقاية من النار من صفاتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص643–648.","url":""}]},{"id":"s3-58","number":58,"surah":3,"verses":[16],"verseLabel":"آل عمران: 16","question":"لماذا قدّموا الإيمان على طلب المغفرة والوقاية من النار؟","answer":"قدموا الإيمان لأنه أصل الاستحقاق والرجاء، ثم بنوا عليه سؤال إزالة الذنب ودفع أثره؛ فالدعاء مرتب من السبب إلى الثمرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص643–648.","url":""}]},{"id":"s3-59","number":59,"surah":3,"verses":[17],"verseLabel":"آل عمران: 17","question":"لماذا جاءت الصفات: ﴿الصابرين والصادقين والقانتين والمنفقين والمستغفرين بالأسحار﴾ بهذا الترتيب؟","answer":"بدأ بالصبر لأنه يحمل على مشاق الطاعة، ثم الصدق المصحح للظاهر والباطن، ثم القنوت وهو دوام الطاعة، فالإنفاق أثر عملي، وخُتم بالاستغفار في السحر جمعًا للعبادة والخضوع.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص648–652.","url":""}]},{"id":"s3-60","number":60,"surah":3,"verses":[17],"verseLabel":"آل عمران: 17","question":"لماذا خُص وقت الأسحار بالاستغفار؟","answer":"لأنه وقت سكون وخلوص، يعقب قيام الليل وتنكسر فيه النفس بعيدًا عن الرياء؛ فكان الاستغفار فيه أمارة صدق العبادة لا مجرد قول باللسان.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص648–652.","url":""}]},{"id":"s3-61","number":61,"surah":3,"verses":[18],"verseLabel":"آل عمران: 18","question":"لماذا بدأ الله الشهادة بنفسه ثم الملائكة ثم أولي العلم؟","answer":"بدأ بأعلى شهادة وأقطعها، ثم ثنّى بشهادة عالم الغيب، ثم أهل العلم من البشر؛ فترتب الشهود بحسب المنزلة وقوة المعرفة.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص652–661.","url":""}]},{"id":"s3-62","number":62,"surah":3,"verses":[18],"verseLabel":"آل عمران: 18","question":"لماذا كرر ﴿لا إله إلا هو﴾ مرتين في آية واحدة؟","answer":"الجملة الأولى مضمون شهادة الله والملائكة وأولي العلم، ثم أعيدت ﴿لَا إِلَهَ إِلَّا هُوَ﴾ نتيجة مستقلة قبل ﴿الْعَزِيزُ الْحَكِيمُ﴾؛ فالثانية تثبيت وخاتمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص652–661.","url":""}]},{"id":"s3-63","number":63,"surah":3,"verses":[18],"verseLabel":"آل عمران: 18","question":"ما سرّ التعبير في قوله تعالى: ﴿قائمًا بالقسط﴾ بالإفراد مع تعدد المذكورين؟","answer":"الحال تبين أن تدبير الله وتشريعه وشهادته بالتوحيد كلها قائمة على العدل؛ فلا تنفصل وحدانيته عن كمال حكمه.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص658.","url":""}]},{"id":"s3-64","number":64,"surah":3,"verses":[18],"verseLabel":"آل عمران: 18","question":"لماذا اختار ﴿القسط﴾ ولم يقل: العدل؟","answer":"القسط هو العدل المستقيم الذي توزن به الحقوق، فناسب مقام قيام الله بتدبير الخلق والحكم بينهم؛ والمراد أنه قائم بالعدل لا يحيف.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص659.","url":""}]},{"id":"s3-65","number":65,"surah":3,"verses":[18],"verseLabel":"آل عمران: 18","question":"لماذا ختمت آية الشهادة بـ﴿العزيز الحكيم﴾؟","answer":"العزة تثبت نفاذ القدرة، والحكمة تثبت أن هذا النفاذ موضوع في موضعه بلا عبث ولا ظلم.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص652–661.","url":""}]},{"id":"s3-66","number":66,"surah":3,"verses":[19],"verseLabel":"آل عمران: 19","question":"ما سرّ التعبير في قوله تعالى: ﴿إن الدين عند الله الإسلام﴾ بالتعريف والقصر؟","answer":"أكدت الجملة بـ﴿إِنَّ﴾، وعُرف الدين والإسلام لبيان الحقيقة الكاملة، وجاء ﴿عِنْدَ اللَّهِ﴾ ليقرر أن الدين المقبول في حكمه هو الاستسلام له واتباع وحيه.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص661–671.","url":""}]},{"id":"s3-67","number":67,"surah":3,"verses":[19],"verseLabel":"آل عمران: 19","question":"ما سرّ التعبير في قوله تعالى: ﴿وما اختلف الذين أوتوا الكتاب إلا من بعد ما جاءهم العلم﴾؟","answer":"أسلوب القصر بـ﴿مَا... إِلَّا﴾ ينفي أن يكون اختلافهم ناشئًا عن غموض الحجة؛ فقد وقع بعد مجيء العلم، وكشف ما بعده أن البغي سبب الانحراف.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص661–671.","url":""}]},{"id":"s3-68","number":68,"surah":3,"verses":[19],"verseLabel":"آل عمران: 19","question":"لماذا علّل اختلافهم بالبغي بينهم؟","answer":"ليبين أن الحجة لم تكن ناقصة، وإنما حملهم الحسد وطلب الرياسة على مخالفة ما علموه؛ فمصدر الفرقة أخلاقي إرادي لا غموض الدليل.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص661–671.","url":""}]},{"id":"s3-69","number":69,"surah":3,"verses":[20],"verseLabel":"آل عمران: 20","question":"ما سرّ التعبير في قوله تعالى: ﴿فإن حاجوك فقل أسلمت وجهي لله﴾ فخص الوجه؟","answer":"الوجه أشرف ما يظهر من الإنسان وبه تتحدد وجهته، فإسلام الوجه كناية عن تسليم الذات والقصد لله كلها؛ وذكره أبلغ من إسلام عمل منفرد.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص671–678.","url":""}]},{"id":"s3-70","number":70,"surah":3,"verses":[20],"verseLabel":"آل عمران: 20","question":"لماذا عبّر بالماضي ﴿أسلمت﴾ لا بالمضارع: أُسلم؟","answer":"صيغة الماضي في ﴿أسلمت﴾ تفيد تحقق الوقوع وثبوته، وقد تستحضر المستقبل في صورة المنجز لزيادة اليقين به.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص676.","url":""}]},{"id":"s3-71","number":71,"surah":3,"verses":[20],"verseLabel":"آل عمران: 20","question":"ما دلالة توجيه السؤال إليهم بقوله تعالى: ﴿أَأَسْلَمْتُمْ﴾؟","answer":"الاستفهام في ﴿أأسلمتم﴾ ليس طلبًا للعلم، بل إنكار وتوبيخ يحمل المخاطب على مواجهة تناقضه وإصدار الحكم على نفسه.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص671–678.","url":""}]},{"id":"s3-72","number":72,"surah":3,"verses":[20],"verseLabel":"آل عمران: 20","question":"لماذا ختم ﴿فإنما عليك البلاغ والله بصير بالعباد﴾؟","answer":"البصر أنسب بمقام الأعمال والمواقف المشاهدة، وفيه مراقبة ووعد أو وعيد بحسب السياق.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص671–678.","url":""}]},{"id":"s3-73","number":73,"surah":3,"verses":[21],"verseLabel":"آل عمران: 21","question":"لماذا جمع بين الكفر بالآيات وقتل الأنبياء وقتل الآمرين بالقسط؟","answer":"جمع فساد الاعتقاد وذروة العدوان على المبلغين ثم على أتباعهم؛ فدل التدرج أن رفض الحق لم يبق فكرةً، بل تحول إلى إسكات كل صوت يقيم العدل.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص678–686.","url":""}]},{"id":"s3-74","number":74,"surah":3,"verses":[21],"verseLabel":"آل عمران: 21","question":"ما سرّ التعبير في قوله تعالى: ﴿يبشرهم بعذاب أليم﴾ فاستعمل البشارة في العذاب؟","answer":"استعملت البشارة في العذاب على سبيل التهكم والمقابلة؛ إذ ينتظر منها الخبر السار، فجاء متعلقها ﴿بِعَذَابٍ أَلِيمٍ﴾ ليزيد الوعيد وقعًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص678–686.","url":""}]},{"id":"s3-75","number":75,"surah":3,"verses":[22],"verseLabel":"آل عمران: 22","question":"ما سرّ التعبير في قوله تعالى: ﴿حبطت أعمالهم في الدنيا والآخرة﴾؟ وكيف تحبط الأعمال في الدنيا؟","answer":"حبوط العمل بطلان أثره وذهاب ثمرته؛ ففي الدنيا لا يثبت لهم به مدح صحيح ولا ثمرة نافعة، وفي الآخرة لا يجدون له ثوابًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص686–690.","url":""}]},{"id":"s3-76","number":76,"surah":3,"verses":[23],"verseLabel":"آل عمران: 23","question":"ما سرّ التعبير في قوله تعالى: ﴿أوتوا نصيبًا من الكتاب﴾ لا: أوتوا الكتاب؟","answer":"﴿نَصِيبًا مِنَ الْكِتَابِ﴾ يدل على ما أُعطوه وعلموه منه، ويلمح إلى أنهم لم يحيطوا بحقه أو لم يعملوا بجميعه؛ فاشتد التوبيخ على إعراضهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص690–699.","url":""}]},{"id":"s3-77","number":77,"surah":3,"verses":[23],"verseLabel":"آل عمران: 23","question":"ما سرّ التعبير في قوله تعالى: ﴿يدعون إلى كتاب الله ليحكم بينهم ثم يتولى فريق منهم﴾؟","answer":"المفارقة أن المدعو إليه كتاب الله الذي يزعمون الانتساب إليه، وغايته الحكم بينهم، ثم تفيد ﴿ثُمَّ﴾ بُعد توليهم واستنكاره بعد قيام مقتضي القبول.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص690–699.","url":""}]},{"id":"s3-78","number":78,"surah":3,"verses":[24],"verseLabel":"آل عمران: 24","question":"لماذا عبّروا عن عذاب النار بقولهم ﴿لن تمسنا النار﴾ لا: لن ندخلها؟","answer":"قولهم ﴿لَنْ تَمَسَّنَا النَّارُ﴾ يهوّن العذاب إلى أدنى إصابة عابرة، ثم يقصرها على أيام قليلة؛ فهو أبلغ في كشف اغترارهم من مجرد قولهم: لن ندخلها.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص699–704.","url":""}]},{"id":"s3-79","number":79,"surah":3,"verses":[24],"verseLabel":"آل عمران: 24","question":"ما سرّ قولهم: ﴿أَيَّامًا مَعْدُودَاتٍ﴾ هنا، وقولهم في البقرة: ﴿أَيَّامًا مَعْدُودَةً﴾؟","answer":"جمع ﴿معدودات﴾ من جموع القلة، فناسب مقام آل عمران الذي يصور شدة اغترارهم بقلة أيام مزعومة، بينما جاء الإفراد في البقرة على الأصل في وصف جمع غير العاقل.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص699–704.","url":""}]},{"id":"s3-80","number":80,"surah":3,"verses":[24],"verseLabel":"آل عمران: 24","question":"ما سرّ التعبير في قوله تعالى: ﴿وغرهم في دينهم ما كانوا يفترون﴾ فجعل الافتراء سبب غرورهم؟","answer":"الافتراء المتكرر صنع لهم اعتقادًا باطلًا فاطمأنوا إليه واغتروا في شأن دينهم؛ فصار الكذب الذي اخترعوه سبب أمنهم من الحساب وإعراضهم عن الحكم.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص699–704.","url":""}]},{"id":"s3-81","number":81,"surah":3,"verses":[25],"verseLabel":"آل عمران: 25","question":"ما سرّ التعبير في قوله تعالى: ﴿فكيف إذا جمعناهم ليوم لا ريب فيه﴾؟ ما الذي تحمله ﴿كيف﴾ هنا؟","answer":"﴿كَيْفَ﴾ للتفخيم والتهويل: كيف يكون حالهم حين يجمعهم الله ليوم لا شك فيه بعد اغترارهم وإعراضهم؟ وجوابها متروك لتذهب النفس في تصور شدته.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص704–709.","url":""}]},{"id":"s3-82","number":82,"surah":3,"verses":[25],"verseLabel":"آل عمران: 25","question":"لماذا عطف ﴿ووفيت كل نفس ما كسبت﴾ بالواو لا بـ﴿ثم﴾؟","answer":"الواو تجمع بين الحشر وتوفية كل نفس عملها بوصفهما من مشاهد اليوم نفسه، من غير قصد إلى بيان مهلة زمنية؛ أما ﴿ثم﴾ فكانت ستبرز التراخي.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص708.","url":""}]},{"id":"s3-83","number":83,"surah":3,"verses":[25],"verseLabel":"آل عمران: 25","question":"ما سرّ التعبير في قوله تعالى: ﴿وهم لا يظلمون﴾ بعد توفية كل نفس؟","answer":"بعد ذكر استيفاء كل نفس ما كسبت، نفت الخاتمة أدنى ظلم في الحساب؛ فلا ينقص ثواب ولا تزاد سيئة، فجمعت كمال الجزاء وكمال العدل.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص709.","url":""}]},{"id":"s3-84","number":84,"surah":3,"verses":[26],"verseLabel":"آل عمران: 26","question":"لماذا افتتح الدعاء بـ﴿قل اللهم مالك الملك﴾؟","answer":"أُمر النبي ﷺ أن يقول هذا الدعاء إعلانًا لعقيدة أن الملك كله لله، وتمهيدًا لتقليب الملك والعز والذل؛ فهو ثناء وتعليم واحتجاج.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص709–717.","url":""}]},{"id":"s3-85","number":85,"surah":3,"verses":[26],"verseLabel":"آل عمران: 26","question":"ما سرّ الجمع بين ﴿تُؤْتِي الْمُلْكَ﴾ و﴿تَنْزِعُ الْمُلْكَ﴾، وبين الإعزاز والإذلال؟","answer":"ليس في الآية تكرار، بل مقابلة بين الإيتاء والنزع، وبين الإعزاز والإذلال؛ فذكر الطرفين يثبت انفراد الله بتقليب أحوال الملك والناس.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص709–717.","url":""}]},{"id":"s3-86","number":86,"surah":3,"verses":[26],"verseLabel":"آل عمران: 26","question":"ما سرّ التعبير في قوله تعالى: ﴿تنزع الملك﴾ فصوّر زواله بالنزع؟","answer":"النزع إخراج بقوة بعد تمكن والتصاق؛ فصوّر زوال الملك على الرغم من رسوخه الظاهر، ليبين أن السلطان عارية بيد الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص709–717.","url":""}]},{"id":"s3-87","number":87,"surah":3,"verses":[26],"verseLabel":"آل عمران: 26","question":"ما سرّ التعبير في قوله تعالى: ﴿وتعز من تشاء وتذل من تشاء﴾، دون أن يقال: ترفع وتخفض؟","answer":"العز والذل أوسع من الرفع والخفض المكانيين؛ فهما يتناولان المنعة والكرامة أو الهوان، ويناسبان الحديث عن الملك وتقلب السلطان.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص709–717.","url":""}]},{"id":"s3-88","number":88,"surah":3,"verses":[26],"verseLabel":"آل عمران: 26","question":"ما سرّ التعبير في قوله تعالى: ﴿بيدك الخير﴾ ولم يذكر الشر؟","answer":"اقتصر على الخير أدبًا في خطاب الله، ولأن المقام مقام ثناء وافتقار؛ والشر ليس إليه استقلالًا بل يقع ضمن حكمته وعدله وتقديره.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص714–717.","url":""}]},{"id":"s3-89","number":89,"surah":3,"verses":[27],"verseLabel":"آل عمران: 27","question":"ما سرّ التعبير في قوله تعالى: ﴿تولج الليل في النهار وتولج النهار في الليل﴾ بفعل الإيلاج؟","answer":"الإيلاج إدخال شيء في شيء تدريجيًا؛ فصوّر امتداد الليل في النهار وامتداد النهار في الليل، وما يطرأ على طولهما من زيادة ونقص.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص717–724.","url":""}]},{"id":"s3-90","number":90,"surah":3,"verses":[27],"verseLabel":"آل عمران: 27","question":"لماذا قدّم إخراج الحي من الميت على إخراج الميت من الحي؟","answer":"لأن المقام مقام إظهار القدرة والرجاء، وإبراز الحياة من موات أعجب وأدل على الإحياء؛ ثم أتبعه بضده ليتم تقليب الأحوال.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص717–724.","url":""}]},{"id":"s3-91","number":91,"surah":3,"verses":[27],"verseLabel":"آل عمران: 27","question":"ما سرّ التعبير في قوله تعالى: ﴿وترزق من تشاء بغير حساب﴾ بعد مشاهد الكون والحياة والموت؟","answer":"بعد تقليب الليل والنهار وإخراج الحي والميت، ختم بالرزق ليبين أن مدبر الكون والحياة يملك أرزاق العباد أيضًا، و﴿بِغَيْرِ حِسَابٍ﴾ تدل على سعة عطائه.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص717–724.","url":""}]},{"id":"s3-92","number":92,"surah":3,"verses":[28],"verseLabel":"آل عمران: 28","question":"لماذا نهى المؤمنين عن اتخاذ الكافرين أولياء ﴿من دون المؤمنين﴾؟","answer":"﴿مِنْ دُونِ الْمُؤْمِنِينَ﴾ أي متجاوزين المؤمنين أو مستبدلين بهم؛ فالنهي عن جعل الولاية والنصرة والبطانة للكافرين على حساب جماعة الإيمان، لا عن العدل وحسن المعاملة اللذين لا يضيعان حق المؤمنين.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص724–732.","url":""}]},{"id":"s3-93","number":93,"surah":3,"verses":[28],"verseLabel":"آل عمران: 28","question":"ما سرّ التعبير في قوله تعالى: ﴿ومن يفعل ذلك فليس من الله في شيء﴾ بهذه الصياغة الشديدة؟","answer":"﴿فَلَيْسَ مِنَ اللَّهِ فِي شَيْءٍ﴾ صيغة براءة شديدة تنفي أن يكون فاعل ذلك في شيء من ولاية الله ونصره ما دام متلبسًا بهذا الولاء المحرم.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص724–732.","url":""}]},{"id":"s3-94","number":94,"surah":3,"verses":[28],"verseLabel":"آل عمران: 28","question":"لماذا استثنى التقية بقوله ﴿إلا أن تتقوا منهم تقاة﴾؟","answer":"الاستثناء رخصة عند خوف الضرر في إظهار ما يدفع الأذى، لا إباحة لمودة القلب أو نصرة الباطل؛ فغاية التقاة الوقاية.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص724–732.","url":""}]},{"id":"s3-95","number":95,"surah":3,"verses":[28],"verseLabel":"آل عمران: 28","question":"لماذا كرر التحذير ﴿ويحذركم الله نفسه﴾؟","answer":"تكرر التحذير في الآيتين 28 و30: جاء أولًا عقب النهي عن الولاء المحرم، ثم عاد بعد ذكر يوم حضور الأعمال؛ فجمع مراقبة الله واستحضار لقائه.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص724–732.","url":""}]},{"id":"s3-96","number":96,"surah":3,"verses":[29],"verseLabel":"آل عمران: 29","question":"ما سرّ التعبير في قوله تعالى: ﴿إن تخفوا ما في صدوركم أو تبدوه يعلمه الله﴾ فقدم الإخفاء؟","answer":"قُدم الإخفاء لأنه موضع توهم الخفاء عن الحساب، ولأن السياق في أعمال القلوب والولاء الباطن؛ ثم عطف الإبداء لإحاطة العلم بالحالين.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص732–738.","url":""}]},{"id":"s3-97","number":97,"surah":3,"verses":[29],"verseLabel":"آل عمران: 29","question":"لماذا عدل من السماء إلى جمع السماوات في ﴿ويعلم ما في السماوات وما في الأرض﴾؟","answer":"جاءت ﴿السَّمَاءِ﴾ مفردة في الآية 5 في مقابلة الأرض ونفي خفاء أي شيء، وجُمعت ﴿السَّمَاوَاتِ﴾ هنا في مقام تفصيل سعة العلم لجميع العوالم.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص737.","url":""}]},{"id":"s3-98","number":98,"surah":3,"verses":[29],"verseLabel":"آل عمران: 29","question":"لماذا أظهر اسم الجلالة في ﴿والله على كل شيء قدير﴾ ولم يضمره؟","answer":"أُظهر اسم الجلالة لتستقل الجملة تقريرًا عامًا للقدرة، ولتجدد المهابة بعد ذكر العلم الشامل، بدل أن تكون مجرد تابع بضمير.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص738.","url":""}]},{"id":"s3-99","number":99,"surah":3,"verses":[30],"verseLabel":"آل عمران: 30","question":"ما سرّ التعبير في قوله تعالى: ﴿تجد كل نفس ما عملت من خير محضرًا﴾ باسم المفعول لا حاضرًا؟","answer":"﴿مُحْضَرًا﴾ يدل على أن العمل يُجعل حاضرًا ويؤتى به لصاحبه يوم القيامة، لا أنه حاضر من تلقاء نفسه؛ ففي صيغة المفعول معنى الإلزام والمواجهة.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص743.","url":""}]},{"id":"s3-100","number":100,"surah":3,"verses":[30],"verseLabel":"آل عمران: 30","question":"لماذا تتمنى النفس ﴿لو أن بينها وبينه أمدًا بعيدًا﴾ بدل أن تتمنى زوال السيئة؟","answer":"صوّر العمل كشيء حاضر تواجهه النفس ولا تستطيع إعدامه بعد وقوعه؛ فلا يبقى لها إلا تمني أبعد مسافة بينها وبينه، وفي ذلك تجسيم لشدة النفرة والندم.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص738–748.","url":""}]},{"id":"s3-101","number":101,"surah":3,"verses":[30],"verseLabel":"آل عمران: 30","question":"لماذا جمع بين ﴿ويحذركم الله نفسه﴾ و﴿والله رؤوف بالعباد﴾؟","answer":"التحذير يمنع الاغترار، والرأفة تبين أن هذا التحذير نفسه رحمة تحمي العباد من أسباب السخط؛ فاجتمع الجلال والجمال بلا تناقض.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص738–748.","url":""}]},{"id":"s3-102","number":102,"surah":3,"verses":[31],"verseLabel":"آل عمران: 31","question":"لماذا جعل الله دليل محبته اتباع الرسول في ﴿إن كنتم تحبون الله فاتبعوني﴾؟","answer":"جعل الاتباع ميزان صدق دعوى المحبة؛ لأن محبة الله لا تثبت بمجرد القول، بل بطاعة رسوله الذي يبلّغ أمره ويبين طريق رضاه.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص748–752.","url":""}]},{"id":"s3-103","number":103,"surah":3,"verses":[31],"verseLabel":"آل عمران: 31","question":"لماذا جاء جواب الاتباع ﴿يحببكم الله ويغفر لكم ذنوبكم﴾؟","answer":"رتّب على اتباع الرسول ثمرتين: محبة الله، وهي الغاية الأعلى، ومغفرة الذنوب، وهي إزالة المانع؛ فجمع حصول الخير ودفع الشر.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص748–752.","url":""}]},{"id":"s3-104","number":104,"surah":3,"verses":[32],"verseLabel":"آل عمران: 32","question":"لماذا أعاد الأمر ﴿قل أطيعوا الله والرسول﴾ بعد آية الاتباع؟","answer":"آية الاتباع تبين علامة المحبة وثمرتها، ثم جاء الأمر الصريح بطاعة الله والرسول وبيان عاقبة التولي؛ فالثاني إلزام بعد إقامة المعيار، لا تكرار مجرد.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص752–756.","url":""}]},{"id":"s3-105","number":105,"surah":3,"verses":[32],"verseLabel":"آل عمران: 32","question":"لماذا ختم الإعراض بـ﴿فإن الله لا يحب الكافرين﴾ ولم يقل: لا يحبهم؟","answer":"أظهر وصف ﴿الْكَافِرِينَ﴾ بدل الضمير ليسجل أن التولي عن طاعة الله ورسوله من شأن الكفر، وليجعل الحكم عامًا في كل من اتصف به.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص752–756.","url":""}]},{"id":"s3-106","number":106,"surah":3,"verses":[33],"verseLabel":"آل عمران: 33","question":"لماذا جمع الله في الاصطفاء آدم ونوحًا وآل إبراهيم وآل عمران؟","answer":"رسم سلسلة واحدة للنبوة والاصطفاء من أبي البشر إلى بيت مريم، تمهيدًا لقصة عيسى وإبطالًا لجعل الرسالات بيوتًا متنازعة.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص756–762.","url":""}]},{"id":"s3-107","number":107,"surah":3,"verses":[34],"verseLabel":"آل عمران: 34","question":"ما سرّ التعبير في قوله تعالى: ﴿ذرية بعضها من بعض﴾ مع اختلاف أزمانهم وأنسابهم؟","answer":"يفيد ﴿بَعْضُهَا مِنْ بَعْضٍ﴾ اتصال هذه السلسلة في النسب والإيمان والطاعة، مع اختلاف الأزمنة؛ فالاصطفاء يجري في بيوت متعاقبة يجمعها أصل التوحيد.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص762–766.","url":""}]},{"id":"s3-108","number":108,"surah":3,"verses":[34],"verseLabel":"آل عمران: 34","question":"لماذا ختم الاصطفاء بـ﴿والله سميع عليم﴾؟","answer":"يسمع أقوال المصطفين ودعاءهم، ويعلم سرائرهم وأهليتهم للرسالة؛ فالاصطفاء قائم على علم محيط لا على نسب مجرد.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص762–766.","url":""}]},{"id":"s3-109","number":109,"surah":3,"verses":[35],"verseLabel":"آل عمران: 35","question":"ما سرّ قول امرأة عمران: ﴿نَذَرْتُ لَكَ مَا فِي بَطْنِي مُحَرَّرًا﴾ دون «نذرت ولدي»؟","answer":"قالت ﴿مَا فِي بَطْنِي﴾ لأنها لم تعلم أذكر هو أم أنثى ولم يتعين بعد اسمه وصفته، فشمل نذرها الجنين على أي حال يولد عليها.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص766–771.","url":""}]},{"id":"s3-110","number":110,"surah":3,"verses":[35],"verseLabel":"آل عمران: 35","question":"ما دلالة قول امرأة عمران: ﴿فَتَقَبَّلْ مِنِّي﴾ قبل أن تعلم ما ستلد؟","answer":"بادرت بسؤال القبول لأنها تعلم أن قيمة النذر في قبول الله لا في مجرد تقديمه، وفيه تواضع العابد قبل ظهور ثمرة عمله.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص766–771.","url":""}]},{"id":"s3-111","number":111,"surah":3,"verses":[36],"verseLabel":"آل عمران: 36","question":"ما دلالة قولها: ﴿رَبِّ إِنِّي وَضَعْتُهَا أُنْثَى﴾ مع أن الله يعلم ما وضعت؟","answer":"لم تقصد إعلام الله، وإنما بثت ما وجدته من مفاجأة لأن خدمة المحرر كانت في عرفهم للذكر، فعرضت حالها على ربها في مقام المناجاة.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص771–782.","url":""}]},{"id":"s3-112","number":112,"surah":3,"verses":[36],"verseLabel":"آل عمران: 36","question":"لماذا جاء الاعتراض ﴿والله أعلم بما وضعت﴾؟","answer":"الجملة من كلام الله أو اعتراض إلهي يبين أن علمه بحقيقة المولودة ومستقبلها فوق علم أمها؛ فما رأته خلاف انتظارها كان في علم الله عطاء ذا شأن.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص771–782.","url":""}]},{"id":"s3-113","number":113,"surah":3,"verses":[36],"verseLabel":"آل عمران: 36","question":"ما سرّ التعبير في قوله تعالى: ﴿وليس الذكر كالأنثى﴾، دون أن يقال: وليست الأنثى كالذكر؟","answer":"قدّم الذكر لأنه المقصود المتوقع للخدمة في تصورها، ثم جاء التشبيه ليقرر أن الأنثى التي وهبها الله ليست كالذكر الذي تمنته؛ بل سيكون لها شأن آخر أعظم.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص771–782.","url":""}]},{"id":"s3-114","number":114,"surah":3,"verses":[36],"verseLabel":"آل عمران: 36","question":"ما سرّ تسميتها ﴿مَرْيَمَ﴾ ثم استعاذتها لها ولذريتها؟","answer":"سمتها مريم، وهو اسم يلائم معنى العبادة والخدمة في لغتهم، ثم ضمّت إلى النذر دعاء الحفظ لها ولذريتها من الشيطان؛ فجمعت حسن التسمية والتحصين.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص771–782.","url":""}]},{"id":"s3-115","number":115,"surah":3,"verses":[37],"verseLabel":"آل عمران: 37","question":"ما سرّ التعبير في قوله تعالى: ﴿فتقبلها ربها بقبول حسن﴾ بالتضعيف، دون أن يقال: قبلها؟","answer":"﴿تَقَبَّلَهَا﴾ تدل على قبول بعناية ورضا، وزاد المصدر ﴿بِقَبُولٍ حَسَنٍ﴾ توكيدًا لحسن القبول وكماله، لا مجرد وقوعه.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص782–791.","url":""}]},{"id":"s3-116","number":116,"surah":3,"verses":[37],"verseLabel":"آل عمران: 37","question":"ما سرّ التعبير في قوله تعالى: ﴿وأنبتها نباتًا حسنًا﴾ فشبّه نشأة مريم بالنبات؟","answer":"شُبهت تربيتها بالنبات الذي ينمو طورًا بعد طور في رعاية حسنة؛ فجمع اللفظ سلامة النشأة الجسدية والخلقية والروحية.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص782–791.","url":""}]},{"id":"s3-117","number":117,"surah":3,"verses":[37],"verseLabel":"آل عمران: 37","question":"ما سرّ التعبير في قوله تعالى: ﴿وكفلها زكريا﴾؟ وما دلالة التشديد في القراءة؟","answer":"في قراءة التخفيف ﴿وَكَفَلَهَا زَكَرِيَّا﴾ تولى زكريا كفالتها، وفي قراءة التشديد ﴿وَكَفَّلَهَا زَكَرِيَّا﴾ جعل الله زكريا كافلها؛ فتتكامل دلالة فعل زكريا وتدبير الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص782–791.","url":""}]},{"id":"s3-118","number":118,"surah":3,"verses":[37],"verseLabel":"آل عمران: 37","question":"لماذا كان زكريا يجد عند مريم رزقًا كلما دخل عليها المحراب؟","answer":"جعل الله الرزق المتجدد كرامةً لمريم ودليلًا لزكريا على أن العطاء لا تحكمه الأسباب المألوفة؛ لذلك انتقل المشهد مباشرة إلى دعائه بالذرية.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص791–799.","url":""}]},{"id":"s3-119","number":119,"surah":3,"verses":[38],"verseLabel":"آل عمران: 38","question":"ما سرّ التعبير في قوله تعالى: ﴿هنالك دعا زكريا ربه﴾؟ ماذا أضاف اسم الإشارة؟","answer":"يشير ﴿هنالك﴾ إلى اللحظة والمقام اللذين شاهد فيهما رزق مريم؛ فحرّك المشهد رجاءه ودعاءه بالذرية على الفور.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص795–799.","url":""}]},{"id":"s3-120","number":120,"surah":3,"verses":[38],"verseLabel":"آل عمران: 38","question":"لماذا طلب زكريا ﴿ذرية طيبة﴾ لا ولدًا فقط؟","answer":"طلب ﴿ذُرِّيَّةً﴾ لا مجرد ولد، لأن اللفظ يستحضر امتداد النسل، وقيدها بالطيب ليكون صلاحها أهم من مجرد حصولها.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص791–799.","url":""}]},{"id":"s3-121","number":121,"surah":3,"verses":[39],"verseLabel":"آل عمران: 39","question":"لماذا نادته الملائكة وهو قائم يصلي في المحراب؟","answer":"جاءت البشارة في موطن الطاعة الذي خرج منه الدعاء، وفي حال قيام بين يدي الله؛ فوافق الجواب مقام التضرع وأشعر بسرعة القبول.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص10–23.","url":""}]},{"id":"s3-122","number":122,"surah":3,"verses":[39],"verseLabel":"آل عمران: 39","question":"لماذا وصف يحيى بأنه ﴿مصدق بكلمة من الله وسيدًا وحصورًا ونبيًا﴾ بهذا الترتيب؟","answer":"بدأ بما يتصل برسالته إلى عيسى: ﴿مُصَدِّقًا بِكَلِمَةٍ مِنَ اللَّهِ﴾، ثم ذكر سيادته وعفته، وختم بالنبوة التي تجمع كمال منزلته ووظيفته.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص10–23.","url":""}]},{"id":"s3-123","number":123,"surah":3,"verses":[39],"verseLabel":"آل عمران: 39","question":"لماذا سمّى عيسى ﴿كلمة من الله﴾؟","answer":"سمي عيسى ﴿كَلِمَةً مِنَ اللَّهِ﴾ لأنه وُجد بأمره وكلمته ﴿كُنْ﴾ من غير أب؛ فاللفظ يبين كيفية الخلق الخارقة، ولا يدل على جزء من الله أو ألوهية.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص10–23.","url":""}]},{"id":"s3-124","number":124,"surah":3,"verses":[45],"verseLabel":"آل عمران: 39؛ آل عمران: 45","question":"ما سرّ التعبير بقوله تعالى: في بشارة يحيى ﴿مصدقًا بكلمة من الله﴾، وقيل في بشارة عيسى ﴿بكلمة منه﴾؟","answer":"ذُكر اسم الله ظاهرًا مع يحيى لأن وصفه تابع لبشارة مستقلة ويؤكد أن عيسى كلمة صادرة بأمر الله، أما في بشارة عيسى فجيء بالضمير ﴿منه﴾ لقرب مرجعه في قوله ﴿إن الله يبشرك﴾، ولتركيز الكلام على خصوص هذه الكلمة الموهوبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص10–23 وص74–83.","url":""}]},{"id":"s3-125","number":125,"surah":3,"verses":[40],"verseLabel":"آل عمران: 40","question":"ما دلالة سؤال زكريا: ﴿أَنَّى يَكُونُ لِي غُلَامٌ﴾ بعد أن دعا بالذرية؟","answer":"سؤاله ليس شكًا في القدرة، بل طلب لمعرفة الكيفية مع اجتماع الكبر والعقر؛ لذلك جاء الجواب بتقرير إطلاق المشيئة.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص23–35.","url":""}]},{"id":"s3-126","number":126,"surah":3,"verses":[40],"verseLabel":"آل عمران: 40","question":"لماذا قدّم في آل عمران ﴿بلغني الكبر﴾ على ﴿وامرأتي عاقر﴾، وعكس الترتيب في مريم؟","answer":"في آل عمران بدأ زكريا بحاله ﴿بَلَغَنِيَ الْكِبَرُ﴾ لأن الكلام موجز في موقف البشارة، ثم ذكر عقر زوجته. وفي مريم فصّل دعاءه من قبل وبدأ في جواب البشارة بحال الزوجة ثم بلغ به وصف كبره غايته؛ فلكل سياق ترتيب عنايته.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص23–35؛ الويب.","url":""}]},{"id":"s3-127","number":127,"surah":3,"verses":[40],"verseLabel":"آل عمران: 40","question":"ما سرّ التعبير بقوله تعالى: لزكريا ﴿الله يفعل ما يشاء﴾، وقيل لمريم ﴿الله يخلق ما يشاء﴾؟","answer":"قصة زكريا تتعلق بردّ القدرة والخصوبة إلى حالهما فناسب عموم ﴿يفعل﴾، أما مريم فالمقام إنشاء ولد بلا أب فناسب التصريح بـ﴿يخلق﴾.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص23–35 وص88–98؛ الويب.","url":""}]},{"id":"s3-128","number":128,"surah":3,"verses":[41],"verseLabel":"آل عمران: 41","question":"لماذا طلب زكريا آية بعد البشارة؟","answer":"لم يطلبها شكًا، بل طلب علامة يعرف بها بدء تحقق الوعد ويزداد بها قلبه طمأنينة؛ كما يسأل المؤمن عن الكيفية مع يقينه بالقدرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص35–49.","url":""}]},{"id":"s3-129","number":129,"surah":3,"verses":[41],"verseLabel":"آل عمران: 41","question":"لماذا كانت آيته ألا يكلم الناس ثلاثة أيام إلا رمزًا؟","answer":"كانت علامة خارقة في آلة الكلام نفسها مع بقاء القدرة على الذكر، لتفصل بين مخاطبة الخلق ومناجاة الخالق وتفرغه لشكر النعمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص35–49.","url":""}]},{"id":"s3-130","number":130,"surah":3,"verses":[41],"verseLabel":"آل عمران: 41","question":"لماذا أُمر بكثرة الذكر والتسبيح بالعشي والإبكار وهو ممنوع من الكلام؟","answer":"ليعلم أن منعه من كلام الناس آية لا عجز مطلق؛ وليقابل البشارة بالشكر، مستغرقًا طرفي النهار في الذكر.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص35–49.","url":""}]},{"id":"s3-131","number":131,"surah":3,"verses":[42],"verseLabel":"آل عمران: 42","question":"ما سرّ تكرار الاصطفاء في قول الملائكة: ﴿إِنَّ اللَّهَ اصْطَفَاكِ وَطَهَّرَكِ وَاصْطَفَاكِ عَلَى نِسَاءِ الْعَالَمِينَ﴾؟","answer":"الاصطفاء الأول اختيار مريم وقبولها وتخصيصها بالطاعة، ثم جاءت الطهارة، أما الاصطفاء الثاني فتمييز لها على نساء العالمين بما خُصت به؛ فمتعلق الاصطفاءين مختلف.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص49–56.","url":""}]},{"id":"s3-132","number":132,"surah":3,"verses":[43],"verseLabel":"آل عمران: 43","question":"ما سرّ تقديم السجود على الركوع في ﴿واسجدي واركعي﴾؟","answer":"قُدم السجود لشرفه وبلوغه غاية الخضوع، ولأنه موضع عناية خاصة في عبادة مريم، ثم عطف الركوع مع الراكعين؛ وليس المقام بيان ترتيب أركان صلاة واحدة.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص59.","url":""}]},{"id":"s3-133","number":133,"surah":3,"verses":[43],"verseLabel":"آل عمران: 43","question":"ما سرّ التعبير في قوله تعالى: ﴿مع الراكعين﴾ لا الراكعات؟","answer":"جاء ﴿الرَّاكِعِينَ﴾ بصيغة جمع المذكر على التغليب؛ ليشمل جماعة العابدين من الرجال والنساء، ويأمرها بالانضمام إلى أهل العبادة لا الانفراد عنها.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص61.","url":""}]},{"id":"s3-134","number":134,"surah":3,"verses":[44],"verseLabel":"آل عمران: 44","question":"لماذا سُمّيت قصة مريم ﴿من أنباء الغيب﴾؟","answer":"هي من أنباء الغيب لأن النبي ﷺ لم يشهد تنازع الكافلين ولا إلقاء أقلامهم، ولم يتلق تفصيله من قومه؛ فإخباره به دليل الوحي.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص64–74.","url":""}]},{"id":"s3-135","number":135,"surah":3,"verses":[44],"verseLabel":"آل عمران: 44","question":"لماذا صُوّر اقتراع الكافلين بإلقاء الأقلام؟","answer":"لأن الأقلام أدوات علمهم وكتابتهم للتوراة، فجعل إلقاؤها في القرعة مشهدًا يجمع شرف الكفالة وشرف العلم، ويظهر أن اختيار زكريا لم يكن محاباة.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص64–74.","url":""}]},{"id":"s3-136","number":136,"surah":3,"verses":[45],"verseLabel":"آل عمران: 45","question":"لماذا بشّرت الملائكة مريم بـ﴿كلمة منه اسمه المسيح عيسى ابن مريم﴾ بهذا التفصيل؟","answer":"جمعت البشارة وصف منشئه ﴿بِكَلِمَةٍ مِنْهُ﴾، وألقابه واسمه ونسبه إلى أمه؛ لتقرر منذ البداية خلقه المعجز وهويته البشرية ومنزلته، وتسد أبواب التحريف في شأنه.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص74–83.","url":""}]},{"id":"s3-137","number":137,"surah":3,"verses":[45],"verseLabel":"آل عمران: 45","question":"لماذا نُسب عيسى إلى أمه في البشارة قبل ولادته؟","answer":"لتقرير نسبه الوحيد من أول البشارة ونفي الأب عنه، مع تشريف مريم؛ وفي ذلك تمهيد للمعجزة ورد على من ألّهه أو بهتها.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص74–83.","url":""}]},{"id":"s3-138","number":138,"surah":3,"verses":[45],"verseLabel":"آل عمران: 45","question":"لماذا جمع له الوجاهة في الدنيا والآخرة والقرب؟","answer":"الوجاهة في الدنيا قبول الرسالة وظهور الآيات، وفي الآخرة كرامة الجزاء، والقرب يبين أصل المنزلة عند الله؛ فاستوعبت البشارة الحالين ومصدر شرفهما.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص74–83.","url":""}]},{"id":"s3-139","number":139,"surah":3,"verses":[45],"verseLabel":"آل عمران: 45","question":"لماذا جاءت البشارة بمريم في آل عمران على لسان ﴿الملائكة﴾ جمعًا، وفي سورة مريم جاءها رسول واحد؟","answer":"ذِكر الملائكة في آل عمران نظر إلى جنس المبشرين أو إلى جماعتهم، أما سورة مريم ففصلت مشهد تمثل جبريل رسولًا واحدًا؛ فالواحد مبلغ عن الملائكة ولا تعارض.","sources":[{"label":"موسوعة التفسير البلاغي، الموضع العكسي: ج31، ص62–63.","url":""}]},{"id":"s3-140","number":140,"surah":3,"verses":[45],"verseLabel":"آل عمران: 45","question":"ما سرّ التعبير بقوله تعالى: في آل عمران ﴿إن الله يبشرك بكلمة منه﴾، وفي مريم ﴿إنما أنا رسول ربك لأهب لك غلامًا زكيًا﴾؟","answer":"آل عمران تعرض البشارة في سياق الاصطفاء والمحاجة فأسندتها إلى الله: ﴿إِنَّ اللَّهَ يُبَشِّرُكِ﴾، وسورة مريم تفصل الحوار المباشر مع الرسول الملكي فقال: ﴿إِنَّمَا أَنَا رَسُولُ رَبِّكِ﴾.","sources":[{"label":"موسوعة التفسير البلاغي، الموضع العكسي: ج31، ص62–63.","url":""}]},{"id":"s3-141","number":141,"surah":3,"verses":[46],"verseLabel":"آل عمران: 46","question":"لماذا ذُكر كلام عيسى في المهد مقرونًا بكلامه كهلًا؟","answer":"كلام المهد معجزة، وذكر كلام الكهولة يقرر استمرار حياته البشرية ورسالته ونضج بيانه؛ فالجمع يمنع حصر شأنه في الخارق وحده.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص83–88.","url":""}]},{"id":"s3-142","number":142,"surah":3,"verses":[47],"verseLabel":"آل عمران: 47","question":"ما سرّ قول مريم: ﴿وَلَمْ يَمْسَسْنِي بَشَرٌ﴾ دون «رجل»؟","answer":"﴿بشر﴾ أعم من الرجل المعيّن ويستحضر الطبيعة البشرية كلها؛ فنفي مسّ أي بشر أبلغ في تقرير خرق العادة.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص92–93.","url":""}]},{"id":"s3-143","number":143,"surah":3,"verses":[47],"verseLabel":"آل عمران: 47","question":"لماذا عبّرت بالمسّ عن العلاقة الزوجية؟","answer":"المس كناية مهذبة تفهم المقصود من غير تصريح بما يستحيا منه، وهي أليق بطهارة مريم ومقام خطاب الملائكة.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص88–98.","url":""}]},{"id":"s3-144","number":144,"surah":3,"verses":[47],"verseLabel":"آل عمران: 47","question":"لماذا جاء جوابها ﴿كذلك الله يخلق ما يشاء﴾ ثم ﴿إذا قضى أمرًا فإنما يقول له كن فيكون﴾؟","answer":"قرر الجواب أولًا أن هذا الخلق داخل مشيئة الله: ﴿يَخْلُقُ مَا يَشَاءُ﴾، ثم بين سهولة إنفاذ المشيئة بأمر ﴿كُنْ﴾؛ فالثاني تعليل وتقرير لقدرة لا تقيدها الأسباب.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص88–98.","url":""}]},{"id":"s3-145","number":145,"surah":3,"verses":[47],"verseLabel":"آل عمران: 47","question":"ما سرّ تصدير سؤال مريم في آل عمران بـ﴿رَبِّ﴾، وعدم تصديره بذلك في سورة مريم؟","answer":"في آل عمران حُكي سؤالها في سياق خطاب الملائكة فصدرته بنداء ربها والتجأت إليه، أما في سورة مريم فالمشهد حوار مباشر مع الرسول الذي تمثل لها، فجاء سؤالها جوابًا له.","sources":[{"label":"موسوعة التفسير البلاغي، الموضع العكسي: ج31، ص70–71.","url":""}]},{"id":"s3-146","number":146,"surah":3,"verses":[47],"verseLabel":"آل عمران: 47","question":"ما سرّ قول مريم في آل عمران ﴿وَلَدٌ﴾، وفي سورة مريم ﴿غُلَامٌ﴾؟","answer":"﴿ولد﴾ يواجه أصل إمكان حصول نسل من غير أب، أما ﴿غلام﴾ في سورة مريم فيصور المولود الموعود وصفته، فلكل مقام زاوية.","sources":[{"label":"موسوعة التفسير البلاغي، الموضع العكسي: ج31، ص71.","url":""}]},{"id":"s3-147","number":147,"surah":3,"verses":[47],"verseLabel":"آل عمران: 47","question":"لماذا زادت مريم في سورتها ﴿ولم أك بغيًا﴾، ولم تذكرها في آل عمران؟","answer":"ذُكرت في سورة مريم لأن الخطاب هناك مباشر والموقف أدعى لدفع تهمة الفاحشة، أما آل عمران فقد سبق فيها تطهير مريم واصطفاؤها فاستغنى السياق عن التصريح.","sources":[{"label":"موسوعة التفسير البلاغي، الموضع العكسي: ج31، ص71.","url":""}]},{"id":"s3-148","number":148,"surah":3,"verses":[47],"verseLabel":"آل عمران: 47","question":"لماذا جاء جواب البشارة في آل عمران باسم الجلالة ﴿الله يخلق ما يشاء﴾، وفي سورة مريم باسم الرب ﴿هو عليّ هين﴾؟","answer":"في آل عمران المقام تقرير القدرة والخلق في محاجة من غلا في عيسى، فظهر اسم الجلالة في ﴿اللَّهُ يَخْلُقُ مَا يَشَاءُ﴾؛ وفي مريم حكى الرسول قول ربها لها: ﴿هُوَ عَلَيَّ هَيِّنٌ﴾، فناسب لفظ الرب مقام الرعاية والتطمين.","sources":[{"label":"موسوعة التفسير البلاغي، الموضع العكسي: ج31، ص76.","url":""}]},{"id":"s3-149","number":149,"surah":3,"verses":[48],"verseLabel":"آل عمران: 48","question":"لماذا جُمعت الكتب في ﴿ويعلمه الكتاب والحكمة والتوراة والإنجيل﴾؟","answer":"ذُكر ﴿الْكِتَابَ﴾ للكتابة أو جنس العلم المنزل، و﴿الْحِكْمَةَ﴾ للفهم ووضع العلم موضعه، ثم خُصت التوراة شريعته التي نشأ عليها والإنجيل وحيه؛ فليست الألفاظ تكرارًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص98–102.","url":""}]},{"id":"s3-150","number":150,"surah":3,"verses":[49],"verseLabel":"آل عمران: 49","question":"لماذا كانت آية عيسى أن يصنع من الطين كهيئة الطير ثم ينفخ فيه؟","answer":"جاءت الآية في صورة محسوسة للخلق من مادة جامدة ثم ظهور الحياة فيها، وهي من جنس ما اشتهر به زمن عيسى من الطب مع تجاوزها قدرة البشر؛ وقيّدها الوحي بـ﴿بِإِذْنِ اللَّهِ﴾ حتى لا تنسب القدرة إليه استقلالًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص102–114.","url":""}]},{"id":"s3-151","number":151,"surah":3,"verses":[49],"verseLabel":"آل عمران: 49","question":"لماذا تكرر قيد ﴿بإذن الله﴾ في معجزات عيسى؟","answer":"كرر القيد مع الخوارق الكبرى لنزع أي توهم في استقلال عيسى بالخلق أو الإحياء؛ فالمعجزة تجري على يده والقدرة لله وحده.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص102–114.","url":""}]},{"id":"s3-152","number":152,"surah":3,"verses":[49],"verseLabel":"آل عمران: 49","question":"لماذا جمع بين شفاء الأكمه والأبرص وإحياء الموتى؟","answer":"جُمعت آيات تتدرج من شفاء مرضين مستعصيين ظاهرين إلى إحياء الموتى، فتصاعدت الدلالة على صدق الرسالة، مع بقاء كل ذلك بإذن الله لا بقدرة مستقلة لعيسى.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص102–114.","url":""}]},{"id":"s3-153","number":153,"surah":3,"verses":[49],"verseLabel":"آل عمران: 49","question":"لماذا عُدَّ إخبارهم بما يأكلون وما يدخرون في بيوتهم آية؟","answer":"لأنه إخبار متكرر بغيب خاص لا تدركه المشاهدة ولا التخمين، فيقيم الحجة لمن عاينه، مع كونه دون الإحياء حتى تتنوع دلائل الرسالة.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص102–114.","url":""}]},{"id":"s3-154","number":154,"surah":3,"verses":[50],"verseLabel":"آل عمران: 50","question":"ما دلالة قول عيسى عليه السلام: ﴿مُصَدِّقًا لِمَا بَيْنَ يَدَيَّ مِنَ التَّوْرَاةِ وَلِأُحِلَّ لَكُمْ بَعْضَ الَّذِي حُرِّمَ عَلَيْكُمْ﴾؟","answer":"جمع عيسى بين تصديق أصل التوراة ونسخ بعض الأحكام الشاقة التي حُرمت عليهم؛ فدعوته امتداد للوحي السابق مع تشريع أذن الله به، لا نقض لأصل الرسالة.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص114–120.","url":""}]},{"id":"s3-155","number":155,"surah":3,"verses":[50],"verseLabel":"آل عمران: 50","question":"ما سرّ التعبير في قوله تعالى: ﴿بعض الذي حرم عليكم﴾ ولم يعيّن المحرمات؟","answer":"أبهمت المحرمات لأن المقصود تقرير أن الإحلال يقع لبعضها لا استقصاء أسمائها في هذا الموضع، ولأن المخاطبين يعرفون ما حُرم عليهم من شريعتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص114–120.","url":""}]},{"id":"s3-156","number":156,"surah":3,"verses":[50],"verseLabel":"آل عمران: 50","question":"لماذا كرر ﴿فاتقوا الله وأطيعون﴾ بعد ذكر الآية والمعجزة؟","answer":"بعد عرض الآيات عاد إلى الغاية منها: تقوى الله وطاعة رسوله؛ فالمعجزة ليست غاية مستقلة، وإنما حجة تستلزم الاستجابة. وتكرار الأمر يثبته بعد تجدد الدليل.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص114–120.","url":""}]},{"id":"s3-157","number":157,"surah":3,"verses":[51],"verseLabel":"آل عمران: 51","question":"ما دلالة قول عيسى عليه السلام: ﴿إِنَّ اللَّهَ رَبِّي وَرَبُّكُمْ فَاعْبُدُوهُ﴾؟","answer":"صرح عيسى بأن الله ربه كما هو رب قومه، ثم فرع عليه الأمر بعبادته؛ فالكلام يبطل تأليهه ويقرر وحدة الرب والمعبود.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص120–123.","url":""}]},{"id":"s3-158","number":158,"surah":3,"verses":[51],"verseLabel":"آل عمران: 51","question":"لماذا سمّى عبادة الله ﴿صراطًا مستقيمًا﴾؟","answer":"شُبهت عبادة الله وحده بطريق مستقيم يوصل إلى الغاية من غير انحراف؛ فالتوحيد منهج سير، لا فكرة مجردة.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص120–123.","url":""}]},{"id":"s3-159","number":159,"surah":3,"verses":[52],"verseLabel":"آل عمران: 52","question":"ما سرّ التعبير في قوله تعالى: ﴿فلما أحس عيسى منهم الكفر﴾، وهل يُحَسّ الكفر بالحواس؟","answer":"الإحساس هنا إدراك قوي ظهرت دلائله في أقوالهم ومواقفهم، فكأن الكفر صار محسوسًا لما استبان أثره؛ وليس المراد إدراك حقيقة معنوية بإحدى الحواس.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص123–130.","url":""}]},{"id":"s3-160","number":160,"surah":3,"verses":[52],"verseLabel":"آل عمران: 52","question":"ما سرّ التعبير في قوله تعالى: ﴿من أنصاري إلى الله﴾، دون أن يقال: من أنصار الله؟","answer":"﴿إلى﴾ تجعل النصرة متجهة إلى الله ودينه؛ أي من يضم نصرته إليّ في الطريق إلى إقامة أمر الله، لا أن الله محتاج إلى ناصر.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص123–130.","url":""}]},{"id":"s3-161","number":161,"surah":3,"verses":[52],"verseLabel":"آل عمران: 52","question":"لماذا أجاب الحواريون ﴿نحن أنصار الله﴾ فغيّروا صيغة سؤال عيسى؟","answer":"سأل عيسى عمن ينصره متجهًا إلى الله، فأجابوا بأصرح من لفظ السؤال: ﴿نَحْنُ أَنْصَارُ اللَّهِ﴾؛ فأعلنوا أن نصرتهم له نصرة لدين الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص123–130.","url":""}]},{"id":"s3-162","number":162,"surah":3,"verses":[52],"verseLabel":"آل عمران: 52","question":"ما دلالة قول الحواريين: ﴿آمَنَّا بِاللَّهِ﴾ ثم طلبهم الشهادة بأنهم مسلمون؟","answer":"بدأوا بالإيمان بالله أصلًا باطنًا، ثم طلبوا من عيسى أن يشهد لهم بالإسلام الذي يظهر في الانقياد والنصرة؛ فجمعوا التصديق والتسليم.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص123–130.","url":""}]},{"id":"s3-163","number":163,"surah":3,"verses":[53],"verseLabel":"آل عمران: 53","question":"لماذا قدّم الحواريون ﴿آمنا بما أنزلت﴾ على ﴿واتبعنا الرسول﴾؟","answer":"الإيمان بما أنزل الله هو الأصل الذي يوجب اتباع الرسول المبلّغ له؛ فرتبوا الاعتقاد بالمصدر قبل العمل بمقتضاه.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص130–139.","url":""}]},{"id":"s3-164","number":164,"surah":3,"verses":[53],"verseLabel":"آل عمران: 53","question":"ما سرّ قولهم: ﴿وَاتَّبَعْنَا الرَّسُولَ﴾ دون ذكر اسم عيسى؟","answer":"قالوا ﴿الرَّسُولَ﴾ لإبراز الصفة التي من أجلها وجب اتباع عيسى، لا لمجرد تعريف شخصه؛ فاتباعهم استجابة لرسالته.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص130–139.","url":""}]},{"id":"s3-165","number":165,"surah":3,"verses":[53],"verseLabel":"آل عمران: 53","question":"لماذا طلبوا ﴿فاكتبنا مع الشاهدين﴾ لا: واجعلنا من المؤمنين؟","answer":"﴿فَاكْتُبْنَا﴾ طلب لإثباتهم وتسجيلهم في زمرة الشاهدين، وهو أبلغ من مجرد جعلهم مؤمنين؛ لأنهم أعلنوا الإيمان والاتباع ثم سألوا منزلة الشهادة للحق.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص130–139.","url":""}]},{"id":"s3-166","number":166,"surah":3,"verses":[53],"verseLabel":"آل عمران: 53","question":"من هم ﴿الشاهدون﴾ الذين رغب الحواريون أن يُكتبوا معهم؟","answer":"الشاهدون هم الذين شهدوا لله بالتوحيد ولرسله بالصدق والبلاغ؛ ويشمل اللفظ الأنبياء والمؤمنين القائمين بهذه الشهادة، من غير حاجة إلى حصره في طائفة واحدة.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص130–139.","url":""}]},{"id":"s3-167","number":167,"surah":3,"verses":[54],"verseLabel":"آل عمران: 54","question":"لماذا عبّر عن تدبير أعداء عيسى وتدبير الله بلفظ واحد: ﴿ومكروا ومكر الله﴾؟","answer":"سُمّي تدبير الجزاء مكرًا مشاكلةً لفعلهم؛ فمكرهم خفي لإبطال الحق، وتدبير الله عدل يقلب كيدهم عليهم، ولا يستويان في الحقيقة.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص139–144.","url":""}]},{"id":"s3-168","number":168,"surah":3,"verses":[54],"verseLabel":"آل عمران: 54","question":"لماذا جاء مكرهم بصيغة الجمع، ومكر الله بإسناده إلى الاسم المفرد؟","answer":"تعدد تدبيرهم بتعدد أصحابه، أما تدبير الله فصادر عن إرادة واحدة غالبة؛ وإظهار الاسم الجليل بدل الضمير يواجه كثرتهم بوحدانية القادر.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص139–144.","url":""}]},{"id":"s3-169","number":169,"surah":3,"verses":[54],"verseLabel":"آل عمران: 54","question":"لماذا ختمت الآية بـ﴿والله خير الماكرين﴾؟","answer":"بعد ذكر مكر الفريقين قررت الخاتمة غلبة تدبير الله وعدله؛ فهو خير من يرد كيد الماكرين عليهم، ولا تعني المماثلة بين مكرهم الظالم وتدبيره العادل.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص139–144.","url":""}]},{"id":"s3-170","number":170,"surah":3,"verses":[54],"verseLabel":"آل عمران: 54","question":"كيف يوصف تدبير الله بالمكر مع أن المكر مذموم في البشر؟","answer":"سمي الجزاء من جنس فعلهم مكرًا للمشاكلة: هم دبروا خفيةً لإبطال الحق ظلمًا، والله أحاط بكيدهم وردّه عليهم عدلًا؛ فالاشتراك في اللفظ لا في الحقيقة والحكم.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص139–144.","url":""}]},{"id":"s3-171","number":171,"surah":3,"verses":[55],"verseLabel":"آل عمران: 55","question":"ما سرّ التعبير في قوله تعالى لعيسى ﴿إني متوفيك ورافعك إليّ﴾، وقدّم التوفي على الرفع؟","answer":"قُدم التوفي لأنه وعد بأخذ عيسى وافيًا وإنجائه من أيديهم، ثم رفعه. ولفظ التوفي يحتمل في التفسير الاستيفاء والقبض، وقيل النوم، وقيل الموت في أجله؛ فلا يصح حصره هنا في موت وقع قبل الرفع.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص144–156.","url":""}]},{"id":"s3-172","number":172,"surah":3,"verses":[55],"verseLabel":"آل عمران: 55","question":"ما سرّ التعبير في قوله تعالى: ﴿ورافعك إليّ﴾ مع تنزّه الله عن المكان؟","answer":"﴿إِلَيَّ﴾ تفيد رفع عيسى إلى جهة التشريف والقرب والموضع الذي اختاره الله له، ولا تقتضي حلول الله في مكان؛ فالله منزه عن المكان والحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص144–156.","url":""}]},{"id":"s3-173","number":173,"surah":3,"verses":[55],"verseLabel":"آل عمران: 55","question":"ما سرّ التعبير في قوله تعالى: ﴿ومطهرك من الذين كفروا﴾، فجعل النجاة منهم تطهيرًا؟","answer":"جعل تخليصه من الذين كفروا وإبعاده عن أذاهم وتهمهم تطهيرًا؛ لأن مخالطتهم وكيدهم مما ينزه الله نبيه عنه.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص144–156.","url":""}]},{"id":"s3-174","number":174,"surah":3,"verses":[55],"verseLabel":"آل عمران: 55","question":"ما سرّ التعبير في قوله تعالى: ﴿وجاعل الذين اتبعوك فوق الذين كفروا﴾، دون أن يقال: غالبين لهم؟","answer":"الفوقية أوسع من مجرد الغلبة في واقعة؛ فتشمل ظهور الحجة وعلو الشأن والنصر الذي يقدره الله لأتباعه الصادقين على مخالفيه.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص144–156.","url":""}]},{"id":"s3-175","number":175,"surah":3,"verses":[55],"verseLabel":"آل عمران: 55","question":"لماذا قيّد الفوقية بـ﴿إلى يوم القيامة﴾؟","answer":"قيدها إلى يوم القيامة لبيان امتداد الوعد وعدم اقتصاره على زمن عيسى أو الجيل الأول، ثم ينتهي الأمر إلى الحكم النهائي بين الفريقين.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص144–156.","url":""}]},{"id":"s3-176","number":176,"surah":3,"verses":[55],"verseLabel":"آل عمران: 55","question":"لماذا انتقل من خطاب عيسى إلى خطاب الفريقين في ﴿ثم إليّ مرجعكم﴾؟","answer":"بدأ الخطاب لعيسى فيما يخص نجاته ورفعه، ثم جمعه مع المختلفين فيه بقوله ﴿مَرْجِعُكُمْ﴾ لأن الفصل يوم القيامة يتعلق بالجميع.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص144–156.","url":""}]},{"id":"s3-177","number":177,"surah":3,"verses":[56],"verseLabel":"آل عمران: 56","question":"ما سرّ التعبير في قوله تعالى: ﴿فأعذبهم عذابًا شديدًا في الدنيا والآخرة﴾، وكيف يكون العذاب في الدنيا؟","answer":"عذاب الدنيا يكون بما يقدره الله من ذلة وهزيمة وعقوبة وآثار للكفر، وعذاب الآخرة بالنار؛ فجمعت الآية العقوبتين ونكرت ﴿عَذَابًا﴾ ووصفته بالشدة للتهويل.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص156–162.","url":""}]},{"id":"s3-178","number":178,"surah":3,"verses":[56],"verseLabel":"آل عمران: 56","question":"لماذا ختم شأن الكافرين بـ﴿وما لهم من ناصرين﴾ بصيغة الجمع؟","answer":"دخلت ﴿مِنْ﴾ على جمع ﴿نَاصِرِينَ﴾ في سياق النفي فاستغرقت كل ناصر محتمل؛ فلا يجدون واحدًا ولا جماعة تدفع عنهم العذاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص156–162.","url":""}]},{"id":"s3-179","number":179,"surah":3,"verses":[56,57],"verseLabel":"آل عمران: 56–57","question":"ما سرّ التعبير في قوله تعالى في الكافرين ﴿فأعذبهم﴾ بضمير المتكلم، ثم قال في المؤمنين ﴿فيوفيهم أجورهم﴾ بضمير الغائب، دون أن يقال: فأوفيهم؟","answer":"أسند العذاب إلى ضمير المتكلم في ﴿فَأُعَذِّبُهُمْ﴾ لإبراز الوعيد والمواجهة، ثم جرى الكلام في جزاء المؤمنين بصيغة الغيبة ﴿فَيُوَفِّيهِمْ﴾ على نسق ذكر الله بعده؛ فالعدول ينوّع الأسلوب ويفرق نبرة الوعيد عن الوعد.","sources":[{"label":"فاضل السامرائي، برنامج «لمسات بيانية»؛ منقول في Quranpedia، ملاحظة 48962، https://quranpedia.net/note/48962.","url":""}]},{"id":"s3-180","number":180,"surah":3,"verses":[57],"verseLabel":"آل عمران: 57","question":"لماذا قابل الكافرين بـ﴿الذين آمنوا وعملوا الصالحات﴾ ولم يكتف بالإيمان؟","answer":"لم يكتف بالإيمان لأن الجزاء المذكور مرتب على تصديق القلب وثمرته العملية؛ وفي ذلك مقابلة لمن ادعى الانتساب إلى الوحي ثم أعرض عن حكمه.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص156–162.","url":""}]},{"id":"s3-181","number":181,"surah":3,"verses":[57],"verseLabel":"آل عمران: 57","question":"ما سرّ التعبير في قوله تعالى: ﴿فيوفيهم أجورهم﴾، فصوّر الثواب أجرًا يُستوفى؟","answer":"التوفية إعطاء الأجر كاملًا من غير نقص، وتسميته أجرًا تشريف وضمان للجزاء على العمل، مع أن الفضل الإلهي هو أصل الاستحقاق والزيادة.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص156–162.","url":""}]},{"id":"s3-182","number":182,"surah":3,"verses":[57],"verseLabel":"آل عمران: 57","question":"لماذا خُتمت الآية بـ﴿والله لا يحب الظالمين﴾ لا: والله يحب المؤمنين؟","answer":"خُتم بنفي محبة الظالمين لأن الكفر والصد عن الحق ظلم، ولأن السياق في الحكم بين الفريقين؛ فالخاتمة تعلل عقوبة الأولين ولا تقتصر على مدح المؤمنين.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص156–162.","url":""}]},{"id":"s3-183","number":183,"surah":3,"verses":[58],"verseLabel":"آل عمران: 58","question":"ما سرّ التعبير في قوله تعالى: ﴿ذلك نتلوه عليك من الآيات والذكر الحكيم﴾ بالإشارة إلى البعيد؟","answer":"أشير بـ﴿ذَلِكَ﴾ إلى ما تقدم من قصة عيسى على سبيل تعظيم شأنه أو لبعده زمنًا، ثم أخبر أن الله يتلوه على رسوله وحيًا حقًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص162–166.","url":""}]},{"id":"s3-184","number":184,"surah":3,"verses":[58],"verseLabel":"آل عمران: 58","question":"لماذا عطف ﴿الذكر الحكيم﴾ على ﴿الآيات﴾، وهما من القرآن نفسه؟","answer":"عُطف الوصفان لاختلاف الجهة: فهو ﴿آيَاتٍ﴾ بما فيه من دلائل وبراهين، وهو ﴿ذِكْرٍ حَكِيمٍ﴾ بما يذكر ويعظ ويحكم القول؛ فاتحد الموصوف وتعدد الاعتبار.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص162–166.","url":""}]},{"id":"s3-185","number":185,"surah":3,"verses":[58],"verseLabel":"آل عمران: 58","question":"لماذا وُصف الذكر بأنه ﴿حكيم﴾، والحكمة وصف للعاقل؟","answer":"وصف الذكر بـ﴿حَكِيمٍ﴾ بمعنى محكم لا خلل فيه، أو مشتمل على الحكمة؛ فإسناد الوصف إلى القرآن صحيح ولا يتوقف على كونه عاقلًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص162–166.","url":""}]},{"id":"s3-186","number":186,"surah":3,"verses":[59],"verseLabel":"آل عمران: 59","question":"لماذا شبّه خلق عيسى بخلق آدم مع أن حال آدم أعجب؟","answer":"لأن الغرض إلزام من جعل عدم الأب دليل ألوهية: فآدم أولى بهذا الوهم إذ خُلق بلا أب ولا أم، ومع ذلك أقروا ببشريته؛ فالأعجب صار حجة على الأدنى.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص166–173.","url":""}]},{"id":"s3-187","number":187,"surah":3,"verses":[59],"verseLabel":"آل عمران: 59","question":"ما سرّ التعبير في قوله تعالى: ﴿خلقه من تراب﴾، دون أن يقال: من طين؟","answer":"التراب هو المادة الأولى التي خلق منها آدم، وهو أبعد عن صورة الإنسان من الطين بعد امتزاجه؛ فذكر الأصل الأبعد يقوي الحجة على إمكان الخلق بغير أب.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص166–171.","url":""}]},{"id":"s3-188","number":188,"surah":3,"verses":[59],"verseLabel":"آل عمران: 59","question":"لماذا جاء ﴿ثم قال له كن فيكون﴾ بـ﴿ثم﴾ مع أن أمر الله لا تراخي فيه؟","answer":"﴿ثُمَّ﴾ هنا لترتيب مراحل الخبر أو للترقي في الحجة، لا لإثبات مهلة في نفاذ أمر الله؛ ذُكر أصل خلقه من تراب ثم الأمر الذي تم به التكوين.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص166–173.","url":""}]},{"id":"s3-189","number":189,"surah":3,"verses":[59],"verseLabel":"آل عمران: 59","question":"ما سرّ التعبير في قوله تعالى: ﴿فيكون﴾ بالمضارع، مع أن خلق آدم قد وقع؟","answer":"جاء ﴿فَيَكُونُ﴾ بالمضارع حكايةً لنتيجة الأمر الإلهي واستحضارًا لسرعة التكوين، كما يقرر سنةً عامة: كلما قضى الله أمرًا قال له كن فيكون؛ فلا يدل على أن خلق آدم ما زال متكررًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص166–173.","url":""}]},{"id":"s3-190","number":190,"surah":3,"verses":[60],"verseLabel":"آل عمران: 60","question":"لماذا جاء ﴿الحق من ربك﴾ جملة قصيرة بعد تفصيل قصة عيسى؟","answer":"بعد تفصيل القصة والحجج جاءت الجملة القصيرة فصلًا حاسمًا: هذا هو الحق الثابت، فلا يبقى بعد البيان موضع لاتباع الشك أو الجدل.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص173–177.","url":""}]},{"id":"s3-191","number":191,"surah":3,"verses":[60],"verseLabel":"آل عمران: 60","question":"ما سرّ التعبير في قوله تعالى: ﴿من ربك﴾، دون أن يقال: من الله؟","answer":"لفظ ﴿رَبِّكَ﴾ يضيف إلى معنى الألوهية معنى التربية والعناية والوحي، ويطمئن النبي ﷺ بأن الحق صادر من ربه الذي يتولاه.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص173–177.","url":""}]},{"id":"s3-192","number":192,"surah":3,"verses":[60],"verseLabel":"آل عمران: 60","question":"ما سرّ التعبير في قوله تعالى: ﴿فلا تكن من الممترين﴾ للنبي ﷺ مع يقينه؟","answer":"النهي موجه إليه والمراد تثبيته وقطع طمع المجادلين، كما يتضمن تعليم الأمة ألا تتردد بعد قيام البرهان.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص173–177.","url":""}]},{"id":"s3-193","number":193,"surah":3,"verses":[94],"verseLabel":"آل عمران: 60؛ البقرة: 147؛ الأنعام: 114؛ يونس: 94","question":"ما سرّ اختلاف التعبير بين قوله تعالى في آل عمران ﴿فلا تكن من الممترين﴾، وقوله تعالى في نظائرها ﴿فلا تكونن من الممترين﴾ بنون التوكيد؟","answer":"سياق آل عمران فرغ لتوه من البرهان المفصل في شأن عيسى فناسبه النهي الأخف تثبيتًا بعد وضوح الحجة، أما المواضع الأخرى فاشتد فيها قطع التردد أو مجادلة المكذبين، فجاءت نون التوكيد لزيادة التقرير.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص485، في مقارنة المواضع بآل عمران: 60.","url":""}]},{"id":"s3-194","number":194,"surah":3,"verses":[61],"verseLabel":"آل عمران: 61","question":"ما سرّ التعبير في قوله تعالى: ﴿فمن حاجّك فيه من بعد ما جاءك من العلم﴾ فسمّى الوحي علمًا؟","answer":"سمّى الوحي ﴿عِلْمًا﴾ لأنه يقين قائم على خبر الله وبرهانه، فالمحاجة بعد مجيئه ليست طلبًا للحق بل مكابرة بعد العلم.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص177–184.","url":""}]},{"id":"s3-195","number":195,"surah":3,"verses":[61],"verseLabel":"آل عمران: 61","question":"لماذا بدأ في المباهلة بـ﴿أبناءنا﴾ ثم ﴿نساءنا﴾ ثم ﴿أنفسنا﴾؟","answer":"قُدم الأبناء لأنهم أعز على النفوس وأشد استدعاء للشفقة، ثم النساء، ثم الأنفس التي تبلغ بها المباهلة غاية الجدية؛ فاستحضار الأهل جميعًا دليل الثقة بالحق.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص177–181.","url":""}]},{"id":"s3-196","number":196,"surah":3,"verses":[61],"verseLabel":"آل عمران: 61","question":"ما سرّ التعبير في قوله تعالى: ﴿وأنفسنا وأنفسكم﴾ مع أن الإنسان لا يدعو نفسه؟","answer":"المراد أن يدعو كل فريق نفسه ومن يمثلها أو أقرب رجاله، فعبّر بـ﴿أَنْفُسَنَا وَأَنْفُسَكُمْ﴾ عن حضور الفريقين بأنفسهم، لا أن الإنسان ينادي ذاته الغائبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص177–184.","url":""}]},{"id":"s3-197","number":197,"surah":3,"verses":[61],"verseLabel":"آل عمران: 61","question":"ما سرّ التعبير في قوله تعالى: ﴿ثم نبتهل﴾ بعد ﴿تعالوا ندع﴾؟","answer":"﴿تَعَالَوْا نَدْعُ﴾ لجمع الفريقين وأهليهما، ثم ﴿نَبْتَهِلْ﴾ للانتقال إلى الدعاء المتضرع وطلب اللعنة على الكاذب؛ فثم للترقي إلى الفعل الأخطر.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص177–184.","url":""}]},{"id":"s3-198","number":198,"surah":3,"verses":[61],"verseLabel":"آل عمران: 61","question":"لماذا جعل المباهلة ﴿لعنة الله على الكاذبين﴾ ولم يعيّن الكاذب من الفريقين؟","answer":"لم يعين الكاذب لفظًا ليجعل المباهلة حكمًا مشتركًا يقبله الفريقان، وليفوض كشفه وعقوبته إلى الله؛ وكل فريق يعلم أن اللعنة ستقع على من كذب.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص177–184.","url":""}]},{"id":"s3-199","number":199,"surah":3,"verses":[62],"verseLabel":"آل عمران: 62","question":"لماذا افتتحت الآية بـ﴿إن هذا لهو القصص الحق﴾ بثلاثة مؤكدات؟","answer":"أكدت الجملة بـ﴿إِنَّ﴾ ولام الابتداء وضمير الفصل ﴿هُوَ﴾ ردًا على الروايات المحرفة والجدال في عيسى؛ فالقصة المذكورة هي الحق دون ما خالفها.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص184–190.","url":""}]},{"id":"s3-200","number":200,"surah":3,"verses":[62],"verseLabel":"آل عمران: 62","question":"لماذا سمّى خبر عيسى ﴿القصص الحق﴾ لا الخبر الحق؟","answer":"القصص خبر تُتبع أحداثه وآثاره في نسق مترابط، لا مجرد معلومة مفردة؛ ووصفه بالحق يقرر صدق قصة عيسى في مقابل الروايات المحرفة.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص184–190.","url":""}]},{"id":"s3-201","number":201,"surah":3,"verses":[62],"verseLabel":"آل عمران: 62","question":"ما سرّ التعبير في قوله تعالى: ﴿وما من إله إلا الله﴾ بزيادة ﴿من﴾؟","answer":"زيادة ﴿مِنْ﴾ بعد النفي تفيد استغراق الجنس: لا يوجد أي إله بحق إلا الله؛ فالنفي نص في إبطال كل فرد يُدعى له ذلك.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص184–190.","url":""}]},{"id":"s3-202","number":202,"surah":3,"verses":[62],"verseLabel":"آل عمران: 62","question":"لماذا خُتمت الحجة بـ﴿وإن الله لهو العزيز الحكيم﴾؟","answer":"العزيز لا يغلبه من جادل في توحيده ولا يحتاج إلى ولد، والحكيم يضع خلق عيسى وتشريعه وحكمه في موضعه؛ فناسب الاسمان ختام الحجة.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص184–190.","url":""}]},{"id":"s3-203","number":203,"surah":3,"verses":[63],"verseLabel":"آل عمران: 63","question":"ما سرّ التعبير في قوله تعالى: ﴿فإن تولوا فإن الله عليم بالمفسدين﴾ فوضع المظهر موضع الضمير؟","answer":"أظهر ﴿الْمُفْسِدِينَ﴾ بدل «بهم» لتسجيل علة الحكم عليهم وتعميمه: من تولى بعد ظهور الحق دخل في وصف الإفساد، والله يعلم حقيقته.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص190–194.","url":""}]},{"id":"s3-204","number":204,"surah":3,"verses":[63],"verseLabel":"آل عمران: 63","question":"لماذا سمّى المتولين عن هذه الحجة ﴿المفسدين﴾؟","answer":"التولي بعد القصة الحق والحجة يفسد الاعتقاد ويصد عن التوحيد، وقد يتعدى أثره إلى إفساد غيره؛ لذلك لم يسمهم مجرد معرضين.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص190–194.","url":""}]},{"id":"s3-205","number":205,"surah":3,"verses":[64],"verseLabel":"آل عمران: 64","question":"لماذا نادى النصارى واليهود بـ﴿يا أهل الكتاب﴾ في مقام الاحتجاج؟","answer":"ناداهم بـ﴿أَهْلَ الْكِتَابِ﴾ استدعاء لما عندهم من أصل الوحي، وإقامة للحجة عليهم من الصفة التي ينتسبون إليها، وتمهيدًا للكلمة المشتركة.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص194–203.","url":""}]},{"id":"s3-206","number":206,"surah":3,"verses":[64],"verseLabel":"آل عمران: 64","question":"ما سرّ التعبير في قوله تعالى: ﴿تعالوا إلى كلمة سواء بيننا وبينكم﴾، وكيف تكون الكلمة مكانًا يُؤتى إليه؟","answer":"صُورت الكلمة السواء كغاية يجتمع الخصمان عندها؛ فـ﴿تَعَالَوْا إِلَى﴾ دعوة إلى الإقبال عليها والالتقاء حولها، لا إتيان مكان حسي.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص194–203.","url":""}]},{"id":"s3-207","number":207,"surah":3,"verses":[64],"verseLabel":"آل عمران: 64","question":"لماذا وصف الكلمة بأنها ﴿سواء﴾، ولم يقل: عادلة؟","answer":"﴿سَوَاءٍ﴾ تفيد كلمة مستوية مشتركة لا يختص بها فريق، قائمة على أصل التوحيد الذي تقر به الرسالات؛ فهي أبلغ هنا من وصفها بالعدل وحده.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص194–203.","url":""}]},{"id":"s3-208","number":208,"surah":3,"verses":[64],"verseLabel":"آل عمران: 64","question":"لماذا فصّل الكلمة السواء في ثلاثة أمور: العبادة، والشرك، واتخاذ الأرباب؟","answer":"لأنها تغلق أبواب الانحراف كلها: إخلاص العبادة، ونفي الشريك، ونفي سلطة البشر الدينية التي تنازع حكم الله؛ فليست دعوة إلى شعار مجمل.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص194–203.","url":""}]},{"id":"s3-209","number":209,"surah":3,"verses":[64],"verseLabel":"آل عمران: 64","question":"ما سرّ التعبير في قوله تعالى: ﴿بعضنا بعضًا أربابًا﴾ مع أن المخاطبين لا يسمّون أحبارهم آلهة؟","answer":"منح البشر حق التحليل والتحريم المخالف لوحي الله وطاعتهم فيه يجعلهم أربابًا من جهة الطاعة والتشريع، وإن لم يسمهم أتباعهم آلهة.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص194–203.","url":""}]},{"id":"s3-210","number":210,"surah":3,"verses":[64],"verseLabel":"آل عمران: 64","question":"لماذا خُتمت الآية بـ﴿فقولوا اشهدوا بأنا مسلمون﴾ لا: فقاتلوهم؟","answer":"المقام مقام دعوة وإقامة حجة؛ فإن تولوا أعلن المسلمون ثباتهم على الإسلام وطلبوا شهادتهم على وضوح الموقف، لا أن ينتقل الخطاب فورًا إلى القتال.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص194–203.","url":""}]},{"id":"s3-211","number":211,"surah":3,"verses":[65],"verseLabel":"آل عمران: 65","question":"ما سرّ التعبير في قوله تعالى: ﴿لم تحاجّون في إبراهيم﴾، دون أن يقال: تختلفون فيه؟","answer":"المحاجة جدال يقيم فيه كل طرف ما يزعم أنه حجة، وهي أخص من مجرد الاختلاف؛ فالآية تبطل حجتهم في نسبة إبراهيم إلى ملة جاءت بعده.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص203–210.","url":""}]},{"id":"s3-212","number":212,"surah":3,"verses":[65],"verseLabel":"آل عمران: 65","question":"لماذا احتجّ بنزول التوراة والإنجيل من بعد إبراهيم؟","answer":"لأن انتساب إبراهيم إلى يهودية أو نصرانية يناقض التاريخ نفسه؛ فالكتابان اللذان نشأ عنهما الاسمان نزلا بعده، فالحجة قريبة لا تحتاج تأويلًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص203–210.","url":""}]},{"id":"s3-213","number":213,"surah":3,"verses":[65],"verseLabel":"آل عمران: 65","question":"لماذا ختم الإنكار بـ﴿أفلا تعقلون﴾؟","answer":"الخاتمة توقظ العقل إلى التناقض الزمني الظاهر: كيف يُنسب إبراهيم إلى اليهودية أو النصرانية والكتابان نزلا من بعده؟ فلا يحتاج بطلان الدعوى إلا تعقل التاريخ.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص203–210.","url":""}]},{"id":"s3-214","number":214,"surah":3,"verses":[66],"verseLabel":"آل عمران: 66","question":"لماذا كرر ﴿ها أنتم هؤلاء﴾ في مقام التوبيخ؟","answer":"﴿هَا أَنْتُمْ هَؤُلَاءِ﴾ تنبيه وتعيين شديدان، كأنهم أُحضروا أمام أنفسهم ليقروا بأنهم جادلوا فيما علموا ثم تجاوزوه إلى ما لا علم لهم به.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص210–215.","url":""}]},{"id":"s3-215","number":215,"surah":3,"verses":[66],"verseLabel":"آل عمران: 66","question":"لماذا فرّق بين المحاجة فيما لهم به علم وما ليس لهم به علم؟","answer":"وبّخهم على انتقالهم من جدل له أصل في كتبهم إلى دعوى لا سند لها في شأن إبراهيم؛ فمن أخطأ مع علمه لا يُعذر إذا جادل فيما يجهله.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص210–215.","url":""}]},{"id":"s3-216","number":216,"surah":3,"verses":[66],"verseLabel":"آل عمران: 66","question":"لماذا خُتمت الآية بـ﴿والله يعلم وأنتم لا تعلمون﴾؟","answer":"بعد كشف جدالهم بغير علم، قررت الخاتمة أن العلم الحق عند الله وأن جهلهم لا يصلح أساسًا للدعوى؛ فهي تفصل بين علمه المحيط ودعواهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص210–215.","url":""}]},{"id":"s3-217","number":217,"surah":3,"verses":[67],"verseLabel":"آل عمران: 67","question":"لماذا نفى عن إبراهيم اليهودية والنصرانية قبل إثبات الحنيفية والإسلام؟","answer":"بدأ بإبطال الدعويين المتنازعتين حتى يخلو الذهن من النسب المحدثة، ثم أثبت الوصف الأصيل الجامع: الميل عن الشرك والاستسلام لله.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص215–222.","url":""}]},{"id":"s3-218","number":218,"surah":3,"verses":[67],"verseLabel":"آل عمران: 67","question":"ما سرّ التعبير في قوله تعالى: ﴿ولكن كان حنيفًا مسلمًا﴾، وما الذي يضيفه ﴿حنيفًا﴾ إلى ﴿مسلمًا﴾؟","answer":"الحنيف يبين الميل عن الشرك والملل المحرفة، والمسلم يثبت الوجهة الإيجابية وهي الاستسلام لله؛ فالأول براءة والثاني ولاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص215–222.","url":""}]},{"id":"s3-219","number":219,"surah":3,"verses":[67],"verseLabel":"آل عمران: 67","question":"لماذا ختم وصف إبراهيم بـ﴿وما كان من المشركين﴾ بعد إثبات إسلامه؟","answer":"بعد نفي اليهودية والنصرانية وإثبات الحنيفية والإسلام، جاء نفي الشرك لقطع كل توهم بأن حنيفيته كانت مجرد انتساب، ولإثبات صفاء توحيده.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص215–222.","url":""}]},{"id":"s3-220","number":220,"surah":3,"verses":[68],"verseLabel":"آل عمران: 68","question":"لماذا عبّر عن أحق الناس بإبراهيم بـ﴿أولى الناس بإبراهيم﴾؟","answer":"﴿أَوْلَى﴾ تدل على شدة القرب والاستحقاق؛ فأحق الناس بالانتساب إلى إبراهيم من وافقه في الاتباع والإيمان، لا من اكتفى بدعوى النسب أو الاسم.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص222–229.","url":""}]},{"id":"s3-221","number":221,"surah":3,"verses":[68],"verseLabel":"آل عمران: 68","question":"لماذا قدّم ﴿الذين اتبعوه﴾ على ﴿هذا النبي والذين آمنوا﴾؟","answer":"قُدم الذين اتبعوا إبراهيم في زمنه لأنهم الأصل التاريخي المحقق لولايته، ثم عطف هذا النبي والذين آمنوا لبيان أنهم الامتداد الموافق له.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص222–229.","url":""}]},{"id":"s3-222","number":222,"surah":3,"verses":[68],"verseLabel":"آل عمران: 68","question":"ما سرّ التعبير في قوله تعالى: ﴿وهذا النبي﴾ باسم الإشارة لا باسمه؟","answer":"اسم الإشارة ﴿هَذَا﴾ يعين النبي محمدًا ﷺ الحاضر في مقام الخطاب ويقربه إلى السامع، وفي وصفه بالنبي بيان سبب أولويته بإبراهيم.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص222–229.","url":""}]},{"id":"s3-223","number":223,"surah":3,"verses":[68],"verseLabel":"آل عمران: 68","question":"لماذا ختمت الآية بـ﴿والله ولي المؤمنين﴾؟","answer":"لما جعلت الولاية الحقيقية لإبراهيم على أساس الإيمان، خُتم بأن الله ولي المؤمنين؛ فولاية الله هي الأصل الذي يصحح كل انتساب وينصر أهله.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص222–229.","url":""}]},{"id":"s3-224","number":224,"surah":3,"verses":[69],"verseLabel":"آل عمران: 69","question":"ما سرّ التعبير في قوله تعالى: ﴿ودّت طائفة من أهل الكتاب لو يضلونكم﴾ فجعل الإضلال أمنية؟","answer":"﴿وَدَّتْ﴾ تكشف أن الإضلال أمنية راسخة في نفوس طائفة منهم قبل أن يكون فعلًا ظاهرًا؛ ففضح القرآن الباعث الداخلي مع تقييد الحكم بطائفة.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص229–236.","url":""}]},{"id":"s3-225","number":225,"surah":3,"verses":[69],"verseLabel":"آل عمران: 69","question":"ما سرّ التعبير في قوله تعالى: ﴿وما يضلون إلا أنفسهم﴾ مع أنهم يحاولون إضلال غيرهم؟","answer":"محاولة إضلال المؤمنين تعود على أصحابها بزيادة الضلال والإثم وافتضاح الحيلة، ولا تضر من عصمه الله؛ لذلك قصر أثر الإضلال الحقيقي على أنفسهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص229–236.","url":""}]},{"id":"s3-226","number":226,"surah":3,"verses":[69],"verseLabel":"آل عمران: 69","question":"لماذا ختم بـ﴿وما يشعرون﴾ لا: وما يعلمون؟","answer":"الشعور إدراك دقيق يشبه الإحساس؛ فنفى عنهم حتى التنبه القريب إلى أن كيدهم يرتد عليهم، وهو أدق في تصوير غفلتهم من نفي العلم العام.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص229–236.","url":""}]},{"id":"s3-227","number":227,"surah":3,"verses":[70],"verseLabel":"آل عمران: 70","question":"ما سرّ التعبير في قوله تعالى: ﴿لم تكفرون بآيات الله وأنتم تشهدون﴾؟","answer":"الاستفهام توبيخي يكشف التناقض بين معرفتهم دلائل الصدق وكفرهم بها؛ وجملة ﴿وأنتم تشهدون﴾ تجعل الجريمة عن علم لا عن خفاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص236–241.","url":""}]},{"id":"s3-228","number":228,"surah":3,"verses":[70],"verseLabel":"آل عمران: 70","question":"لماذا اختير فعل ﴿تشهدون﴾ لا: تعلمون؟","answer":"الشهادة علم مع حضور وإقرار، فقول ﴿تَشْهَدُونَ﴾ يلزمهم بما عرفوه واعترفوا بدلائلِه، ويجعل كفرهم مخالفة لشهادة قائمة لا مجرد معلومة ذهنية.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص236–241.","url":""}]},{"id":"s3-229","number":229,"surah":3,"verses":[98,99],"verseLabel":"آل عمران: 70؛ آل عمران: 98–99","question":"لماذا جاء النداء في الآيتين 70–71 بلا ﴿قل﴾، ثم قيل في الآيتين 98–99 ﴿قل يا أهل الكتاب﴾؟","answer":"الخطاب الأول متصل بمحاجتهم المباشرة فجرى النداء بلا واسطة في نسق المواجهة، أما الثاني فجاء بعد انتقالات تشريعية وحجاجية فأعيد تكليف الرسول بإعلان الإنكار عليهم، فجدّدت ﴿قل﴾ مصدر الخطاب وسلطانه.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص236–252 وص490–502.","url":""}]},{"id":"s3-230","number":230,"surah":3,"verses":[98],"verseLabel":"آل عمران: 70؛ آل عمران: 98","question":"لماذا ختم ﴿لم تكفرون بآيات الله﴾ أولًا بـ﴿وأنتم تشهدون﴾، ثم ختم نظيرها بـ﴿والله شهيد على ما تعملون﴾؟","answer":"الأولى تقيم الحجة من شهادتهم التي يعرفونها في كتبهم، فالتوبيخ ناشئ من تناقضهم الداخلي؛ والثانية تنقلهم إلى مراقبة شهادة الله على أعمالهم، فتصعد من إلزام الضمير إلى التهديد بالمحاسبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص236–241 وص490–495.","url":""}]},{"id":"s3-231","number":231,"surah":3,"verses":[71],"verseLabel":"آل عمران: 71","question":"ما سرّ التعبير في قوله تعالى: ﴿تلبسون الحق بالباطل﴾، وكيف يُلبس الحق؟","answer":"شُبه الحق بثوب يغطى بالباطل أو يخلط به حتى يلتبس على الناظر؛ فالصورة تبين أنهم لم يطرحوا الحق كله، بل ستروا وجهه بما أدخلوا عليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص241–252.","url":""}]},{"id":"s3-232","number":232,"surah":3,"verses":[71],"verseLabel":"آل عمران: 71","question":"لماذا قدّم خلط الحق بالباطل على كتمان الحق؟","answer":"لأن التلبيس يصنع صورة زائفة أولًا، ثم يثبتها بإخفاء ما يكشفها؛ فقدم الفعل المضلل الظاهر على وسيلته الباطنة.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص241–252.","url":""}]},{"id":"s3-233","number":233,"surah":3,"verses":[71],"verseLabel":"آل عمران: 71","question":"لماذا قيّد الكتمان بـ﴿وأنتم تعلمون﴾؟","answer":"قيد الكتمان بالعلم ليخرج الخطأ والجهل ويثبت تعمد إخفاء الحق بعد معرفته؛ فالجناية أخلاقية مقصودة.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص241–252.","url":""}]},{"id":"s3-234","number":234,"surah":3,"verses":[72],"verseLabel":"آل عمران: 72","question":"لماذا اقترحت الطائفة أن يؤمنوا أول النهار ويكفروا آخره؟","answer":"ليوهموا أن رجوعهم السريع نتج عن اكتشاف عيب في الدين بعد تجربته، فيزعزعوا ثقة المؤمنين ويغووا المترددين بالاقتداء بهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص252–263.","url":""}]},{"id":"s3-235","number":235,"surah":3,"verses":[72],"verseLabel":"آل عمران: 72","question":"ما سرّ تعبيرهم بـ﴿الَّذِي أُنْزِلَ عَلَى الَّذِينَ آمَنُوا﴾ دون التصريح باسم القرآن؟","answer":"هذا من كلام المتآمرين، فعبّروا عن القرآن بالموصول ﴿الَّذِي أُنْزِلَ عَلَى الَّذِينَ آمَنُوا﴾ على جهة البعد عنه وعدم الاعتراف باسمه، مع تعيين ما يتظاهرون بالإيمان به.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص252–263.","url":""}]},{"id":"s3-236","number":236,"surah":3,"verses":[72],"verseLabel":"آل عمران: 72","question":"لماذا ختمت حيلتهم بـ﴿لعلهم يرجعون﴾؟","answer":"﴿لَعَلَّهُمْ يَرْجِعُونَ﴾ تكشف غاية الحيلة: إحداث الشك في نفوس المؤمنين ليرتدوا عن دينهم، لا بحث المتآمرين عن الحق.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص252–263.","url":""}]},{"id":"s3-237","number":237,"surah":3,"verses":[73],"verseLabel":"آل عمران: 73","question":"ما دلالة قول بعض أهل الكتاب: ﴿وَلَا تُؤْمِنُوا إِلَّا لِمَنْ تَبِعَ دِينَكُمْ﴾؟","answer":"أوصى بعضهم بعضًا بألا يصدقوا أو يظهروا ما عندهم إلا لمن كان على دينهم؛ فالعبارة تصور عصبية تحجب الحق وتربط الثقة بالانتماء لا بالدليل.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص263–280.","url":""}]},{"id":"s3-238","number":238,"surah":3,"verses":[73],"verseLabel":"آل عمران: 73","question":"لماذا اعترض القرآن قولهم بجملة ﴿قل إن الهدى هدى الله﴾؟","answer":"اعترضت الجملة حيلتهم لتقرر أن الهداية ملك لله وليست حكرًا على جماعتهم، فلا يملكون منع الوحي والفضل عمن يشاء الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص263–280.","url":""}]},{"id":"s3-239","number":239,"surah":3,"verses":[73],"verseLabel":"آل عمران: 73","question":"ما سرّ التعبير في قوله تعالى: ﴿أن يؤتى أحد مثل ما أوتيتم﴾ بالبناء للمجهول؟","answer":"بُني ﴿أَنْ يُؤْتَى أَحَدٌ﴾ للمجهول لأن مانح الوحي معلوم وهو الله، ولأن كلامهم منصبّ على وقوع الإيتاء لغير جماعتهم، وهو الأمر الذي يحسدون عليه ويحاولون كتمانه.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص263–280.","url":""}]},{"id":"s3-240","number":240,"surah":3,"verses":[73],"verseLabel":"آل عمران: 73","question":"لماذا ختمت الآية بـ﴿إن الفضل بيد الله يؤتيه من يشاء﴾؟","answer":"ردت الخاتمة على حسدهم واعتقاد احتكار النبوة: الفضل في ملك الله لا بأيدي طائفة، يمنحه من يشاء ولا يحجره نسب أو جماعة.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص263–280.","url":""}]},{"id":"s3-241","number":241,"surah":3,"verses":[73],"verseLabel":"آل عمران: 73","question":"لماذا جمع بين ﴿واسع﴾ و﴿عليم﴾ في هذا المقام؟","answer":"سعة الفضل تنفي احتكاره في قوم، والعلم يثبت أن منحه واقع في موضعه؛ فالاختيار ليس عجزًا ولا محاباة.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص263–280.","url":""}]},{"id":"s3-242","number":242,"surah":3,"verses":[74],"verseLabel":"آل عمران: 74","question":"ما سرّ التعبير في قوله تعالى: ﴿يختص برحمته من يشاء﴾، دون أن يقال: يعطي رحمته؟","answer":"الاختصاص جعل الرحمة نصيبًا خاصًا يختاره الله بمشيئته، وهو أبلغ من مطلق العطاء؛ إذ يبرز حرية الفضل وعدم خضوعه لاحتكار البشر.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص280–289.","url":""}]},{"id":"s3-243","number":243,"surah":3,"verses":[74],"verseLabel":"آل عمران: 74","question":"لماذا ختم بـ﴿والله ذو الفضل العظيم﴾ لا: والله رحيم؟","answer":"لأن السياق في النبوة والهداية والرحمة التي يختص الله بها من يشاء، ناسب ﴿ذُو الْفَضْلِ الْعَظِيمِ﴾ سعة العطاء وتجاوزه مقاييس الحاسدين.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص280–289.","url":""}]},{"id":"s3-244","number":244,"surah":3,"verses":[75],"verseLabel":"آل عمران: 75","question":"لماذا قابل القرآن بين من يؤتمن بقنطار ومن يؤتمن بدينار؟","answer":"جعل القنطار والدينار طرفي الكثرة والقلة ليبين أن الأمانة والخيانة خُلُقان لا تحددهما قيمة المال؛ فقد يحفظ الأمين الكثير ويجحد الخائن القليل.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص289–302.","url":""}]},{"id":"s3-245","number":245,"surah":3,"verses":[75],"verseLabel":"آل عمران: 75","question":"ما سرّ التعبير في قوله تعالى في حفظ الدينار ﴿إلا ما دمت عليه قائمًا﴾، وما صورة القيام هنا؟","answer":"القيام عليه كناية عن ملازمة المطالبة والمراقبة وعدم ترك المدين؛ فلا يرد الدينار إلا مع دوام الضغط عليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص289–302.","url":""}]},{"id":"s3-246","number":246,"surah":3,"verses":[75],"verseLabel":"آل عمران: 75","question":"ما دلالة قولهم: ﴿لَيْسَ عَلَيْنَا فِي الْأُمِّيِّينَ سَبِيلٌ﴾؟","answer":"السبيل كناية عن الحجة والمؤاخذة؛ أي زعموا أنه لا طريق إلى لومهم في أموال غير اليهود، فكشف القرآن تحريفهم الأخلاقي.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص289–302.","url":""}]},{"id":"s3-247","number":247,"surah":3,"verses":[75],"verseLabel":"آل عمران: 75","question":"لماذا ختم الآية بـ﴿ويقولون على الله الكذب وهم يعلمون﴾؟","answer":"بيّنت الخاتمة أن دعوى سقوط حق الأميين ليست اجتهادًا خاطئًا، بل كذب منسوب إلى الله مع علمهم بكذبه؛ فاجتمع الافتراء والتعمد.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص289–302.","url":""}]},{"id":"s3-248","number":248,"surah":3,"verses":[76],"verseLabel":"آل عمران: 76","question":"لماذا أُجيب عن دعواهم بكلمة ﴿بلى﴾؟","answer":"﴿بَلَى﴾ تبطل النفي السابق مباشرة: عليهم سبيل ومؤاخذة. ثم انتقل الكلام إلى القاعدة الصحيحة في الوفاء والتقوى بدل دعواهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص302–310.","url":""}]},{"id":"s3-249","number":249,"surah":3,"verses":[76],"verseLabel":"آل عمران: 76","question":"لماذا جمع بين الوفاء بالعهد والتقوى؟","answer":"الوفاء هو صورة العمل الظاهرة، والتقوى رقيبه الباطن؛ فمن اتقى الله حفظ العهد ولو قدر على نقضه.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص302–310.","url":""}]},{"id":"s3-250","number":250,"surah":3,"verses":[76],"verseLabel":"آل عمران: 76","question":"ما سرّ التعبير في قوله تعالى: ﴿فإن الله يحب المتقين﴾، دون أن يقال: يحبه؟","answer":"أظهر وصف ﴿الْمُتَّقِينَ﴾ بدل الضمير ليبين أن الوفاء بالعهد ثمرة التقوى، وأن محبة الله ثابتة لكل من تحقق بهذا الوصف، لا لذلك الشخص وحده.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص302–310.","url":""}]},{"id":"s3-251","number":251,"surah":3,"verses":[77],"verseLabel":"آل عمران: 77","question":"لماذا وصف ثمن نقض العهد بأنه ﴿قليل﴾ مهما كان كبيرًا؟","answer":"كل عوض دنيوي قليل إذا قوبل بعهد الله وبنصيب الآخرة، ولو عظم في أعين الناس؛ فالقلة هنا نسبية إلى ما ضيعوه.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص310–321.","url":""}]},{"id":"s3-252","number":252,"surah":3,"verses":[77],"verseLabel":"آل عمران: 77","question":"لماذا تتابعت العقوبات: لا خلاق، ولا كلام، ولا نظر، ولا تزكية؟","answer":"استوعبت الحرمان من نعيم الآخرة ومن وجوه القرب والتكريم: لا نصيب، ولا خطاب رضا، ولا نظر رحمة، ولا تطهير؛ فناسب تعدد الجناية تعدد العقوبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص310–321.","url":""}]},{"id":"s3-253","number":253,"surah":3,"verses":[77],"verseLabel":"آل عمران: 77","question":"ما سرّ التعبير في قوله تعالى: ﴿ولا ينظر إليهم يوم القيامة﴾ مع إحاطة علم الله بهم؟","answer":"نفي النظر كناية عن حرمانهم نظر الرحمة والرضا والتكريم، لا عن خفائهم عن علم الله؛ فالمقام مقام إهانة يوم القيامة.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص310–321.","url":""}]},{"id":"s3-254","number":254,"surah":3,"verses":[77],"verseLabel":"آل عمران: 77","question":"لماذا ختم بـ﴿ولهم عذاب أليم﴾ بعد ذكر الحرمانات السابقة؟","answer":"بعد حرمانهم من النصيب والكلام والنظر والتزكية أضيف العذاب الأليم؛ فجمعوا ألم الحرمان المعنوي وألم العقوبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص310–321.","url":""}]},{"id":"s3-255","number":255,"surah":3,"verses":[174],"verseLabel":"آل عمران: 77؛ البقرة: 174","question":"لماذا زادت آية آل عمران في وعيد المشترين بالثمن القليل: ﴿لا خلاق لهم في الآخرة﴾ و﴿لا ينظر إليهم﴾، ولم تردا في نظير البقرة؟","answer":"آل عمران تتحدث عن نقض عهد الله والأيمان مع العلم، وهو جمع لحرمة الدين والعهد، فناسبه استقصاء ألوان الحرمان والإهانة؛ أما آية البقرة فركزت على كتمان الكتاب وأكل الثمن، فجاء وعيدها ملائمًا لجريمتها دون استيعاب الأوصاف نفسها.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص741؛ ج5، ص310–321.","url":""}]},{"id":"s3-256","number":256,"surah":3,"verses":[78],"verseLabel":"آل عمران: 78","question":"ما سرّ التعبير في قوله تعالى: ﴿يلوون ألسنتهم بالكتاب﴾، وكيف يُلوى اللسان؟","answer":"لَيّ اللسان تحريف لطريقة القراءة والنطق حتى يشبه كلامهم الكتاب المنزل؛ فالصورة تكشف تلاعبًا مقصودًا بالألفاظ لإيهام السامع.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص321–335.","url":""}]},{"id":"s3-257","number":257,"surah":3,"verses":[78],"verseLabel":"آل عمران: 78","question":"ما سرّ التعبير في قوله تعالى: ﴿لتحسبوه من الكتاب﴾، دون أن يقال: لتظنوه؟","answer":"الحسبان حكم ذهني قد ينشأ من التلبيس، فناسب غايتهم أن يحملوا السامع على عد كلامهم من الكتاب؛ وليس المراد مجرد ظن عابر بلا صناعة.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص330–331.","url":""}]},{"id":"s3-258","number":258,"surah":3,"verses":[78],"verseLabel":"آل عمران: 78","question":"لماذا كرر النفي: ﴿وما هو من الكتاب... وما هو من عند الله﴾؟","answer":"النفي الأول يقرر أن الملفوظ المحرّف ليس من نص الكتاب، والثاني ينفي أن يكون وحيًا من عند الله أصلًا؛ فأبطل مصدره الخاص ودعوى مصدره الإلهي عامة.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص321–335.","url":""}]},{"id":"s3-259","number":259,"surah":3,"verses":[78],"verseLabel":"آل عمران: 78","question":"لماذا ختم بـ﴿وهم يعلمون﴾ كما ختمت آية 75؟","answer":"تكرر ﴿وَهُمْ يَعْلَمُونَ﴾ لأن الخيانة في الموضعين متعمدة: علموا بطلان دعوى إسقاط حقوق الأميين، وعلموا أن ما يقولونه ليس من عند الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص321–335.","url":""}]},{"id":"s3-260","number":260,"surah":3,"verses":[79],"verseLabel":"آل عمران: 79","question":"ما سرّ التعبير في قوله تعالى: ﴿ما كان لبشر أن يؤتيه الله الكتاب والحكم والنبوة ثم يقول للناس كونوا عبادًا لي﴾؟","answer":"أسلوب ﴿مَا كَانَ لِبَشَرٍ﴾ ينفي ملاءمة هذا القول واستقامته أصلًا ممن آتاه الله الكتاب والحكم والنبوة؛ فالوحي الذي رباه يمنعه أن يدعو إلى عبادته.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص335–354.","url":""}]},{"id":"s3-261","number":261,"surah":3,"verses":[79],"verseLabel":"آل عمران: 79","question":"لماذا اختير لفظ ﴿بشر﴾ في مقام نفي ادعاء الألوهية؟","answer":"لفظ ﴿بَشَرٍ﴾ يقرر إنسانية النبي الذي لا يملك حق التأله، فيشتد التناقض بين بشريته وبين أن يطلب من الناس عبادته من دون الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص335–354.","url":""}]},{"id":"s3-262","number":262,"surah":3,"verses":[79],"verseLabel":"آل عمران: 79","question":"ما سرّ التعبير في قوله تعالى: ﴿كونوا ربانيين﴾، دون أن يقال: علماء أو صالحين؟","answer":"الرباني من ينتسب إلى الرب علمًا وعملاً وتربيةً للناس؛ فهو أوسع من مجرد العالم الذي قد يحمل المعرفة ولا يزكي بها نفسه وغيره.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص335–354.","url":""}]},{"id":"s3-263","number":263,"surah":3,"verses":[79],"verseLabel":"آل عمران: 79","question":"لماذا قدّم ﴿بما كنتم تعلمون الكتاب﴾ على ﴿وبما كنتم تدرسون﴾؟","answer":"قُدم تعليم الكتاب لأن الربانية تظهر في نشر العلم وتربية الناس به، ثم ذُكرت الدراسة التي تمد هذا التعليم بالفهم والمراجعة؛ فجمع الأثر المتعدي وأصله العلمي.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص335–354.","url":""}]},{"id":"s3-264","number":264,"surah":3,"verses":[80],"verseLabel":"آل عمران: 80","question":"لماذا جمع بين اتخاذ الملائكة والنبيين أربابًا؟","answer":"لأنهما أعلى من قد يغلُو فيه البشر من الخلق؛ فإذا امتنع أن يأمر الرسول بتأليههما فامتناع تأليه من دونهما أولى.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص354–362.","url":""}]},{"id":"s3-265","number":265,"surah":3,"verses":[80],"verseLabel":"آل عمران: 80","question":"ما سرّ التعبير في قوله تعالى: ﴿أيأمركم بالكفر بعد إذ أنتم مسلمون﴾ بالاستفهام لا بالنفي المباشر؟","answer":"الاستفهام في ﴿أيأمركم بالكفر بعد إذ أنتم مسلمون﴾ ليس طلبًا للعلم، بل إنكار وتوبيخ يحمل المخاطب على مواجهة تناقضه وإصدار الحكم على نفسه.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص354–362.","url":""}]},{"id":"s3-266","number":266,"surah":3,"verses":[81],"verseLabel":"آل عمران: 81","question":"لماذا أخذ الله ميثاق النبيين على الإيمان برسول يأتي بعدهم؟","answer":"ليقرر وحدة مصدر الرسالات وأن السابق يمهد للاحق ولا يناقضه؛ فيلزم أتباع الأنبياء بنصرة الرسول المصدق لما معهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص362–381.","url":""}]},{"id":"s3-267","number":267,"surah":3,"verses":[81],"verseLabel":"آل عمران: 81","question":"ما سرّ التعبير في قوله تعالى: ﴿لما آتيتكم من كتاب وحكمة﴾ فجمع الكتاب والحكمة؟","answer":"الكتاب هو الوحي والتشريع المنزل، والحكمة فهمه ووضعه موضعه؛ فالميثاق شمل ما أوتي النبيون من نص ومعنى وهداية.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص362–381.","url":""}]},{"id":"s3-268","number":268,"surah":3,"verses":[81],"verseLabel":"آل عمران: 81","question":"لماذا وصف الرسول الآتي بأنه ﴿مصدق لما معكم﴾؟","answer":"وصف الرسول بأنه مصدق لما معهم يثبت وحدة مصدر الرسالات ويزيل عذر أتباع السابقين؛ فالإيمان به وفاء بكتبهم لا خروج عليها.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص362–381.","url":""}]},{"id":"s3-269","number":269,"surah":3,"verses":[81],"verseLabel":"آل عمران: 81","question":"لماذا كرر الإقرار في قوله ﴿أأقررتم وأخذتم على ذلكم إصري قالوا أقررنا﴾؟","answer":"سؤال ﴿أَأَقْرَرْتُمْ﴾ يستخرج الاعتراف الصريح، وجوابهم ﴿أَقْرَرْنَا﴾ يثبت قبولهم الميثاق على أنفسهم؛ فالتكرار توثيق للسؤال والجواب.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص362–381.","url":""}]},{"id":"s3-270","number":270,"surah":3,"verses":[81],"verseLabel":"آل عمران: 81","question":"لماذا ختم الميثاق بـ﴿فاشهدوا وأنا معكم من الشاهدين﴾؟","answer":"أُمروا أن يشهد بعضهم على بعض بهذا الإقرار، وأعلن الله شهادته معهم؛ فبلغ الميثاق غاية التوثيق ولم يبق مجال لإنكاره.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص362–381.","url":""}]},{"id":"s3-271","number":271,"surah":3,"verses":[187],"verseLabel":"آل عمران: 81؛ آل عمران: 187","question":"ما سرّ اختلاف التعبير بين قوله تعالى في ميثاق النبيين ﴿وإذ أخذ الله ميثاق النبيين﴾، وقوله تعالى في الميثاق الآخر ﴿وإذ أخذ الله ميثاق الذين أوتوا الكتاب﴾؟","answer":"سمّى النبيين باسم مقامهم تشريفًا وبيانًا لوحدة الرسالة، أما أهل الكتاب فوصفهم بصلة الإيتاء لأن الحجة متعلقة بما أوتوه وكُلّفوا ببيانه؛ فكل تسمية تكشف مناط الميثاق.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص362–381؛ ج6، ص432–443.","url":""}]},{"id":"s3-272","number":272,"surah":3,"verses":[82],"verseLabel":"آل عمران: 82","question":"ما سرّ التعبير في قوله تعالى: ﴿فمن تولى بعد ذلك﴾، وما الذي يفيده ﴿بعد ذلك﴾؟","answer":"قيد ﴿بَعْدَ ذَلِكَ﴾ يعظم جرم التولي بعد الميثاق المؤكد والإقرار والشهادة؛ فليس إعراضًا قبل البيان.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص381–386.","url":""}]},{"id":"s3-273","number":273,"surah":3,"verses":[82],"verseLabel":"آل عمران: 82","question":"لماذا حُصر المتولون في قوله ﴿فأولئك هم الفاسقون﴾؟","answer":"اسم الإشارة وضمير الفصل وتعريف الخبر في ﴿فَأُولَئِكَ هُمُ الْفَاسِقُونَ﴾ تؤكد أنهم الكاملون في الخروج عن عهد الله بعد توثيقه.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص381–386.","url":""}]},{"id":"s3-274","number":274,"surah":3,"verses":[83],"verseLabel":"آل عمران: 83","question":"لماذا جاء الإنكار في صورة سؤال: ﴿أفغير دين الله يبغون﴾ بدل النهي المباشر؟","answer":"الاستفهام في ﴿أفغير دين الله يبغون﴾ ليس طلبًا للعلم، بل إنكار وتوبيخ يحمل المخاطب على مواجهة تناقضه وإصدار الحكم على نفسه.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص386–397؛ مسح الويب.","url":""}]},{"id":"s3-275","number":275,"surah":3,"verses":[83],"verseLabel":"آل عمران: 83","question":"ما سرّ التعبير في قوله تعالى: ﴿وله أسلم من في السماوات والأرض﴾، دون أن يقال: وما فيهما؟","answer":"اختير ﴿مَنْ﴾ لأنها الأصل في العقلاء المكلفين الذين وقع منهم الإسلام طوعًا أو خضوعًا، أما «ما» فتغلب في غير العقلاء ولا تلائم موضع المسؤولية.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص386–397.","url":""}]},{"id":"s3-276","number":276,"surah":3,"verses":[83],"verseLabel":"آل عمران: 83","question":"لماذا قابل بين ﴿طوعًا وكرهًا﴾؟","answer":"الطباق بين الطوع والكره يستوعب حال الخلق: منهم من ينقاد لله اختيارًا بالإيمان، وكلهم خاضع لسننه وقدره ولو كره؛ فلا يخرج أحد عن سلطانه.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص386–397.","url":""}]},{"id":"s3-277","number":277,"surah":3,"verses":[83],"verseLabel":"آل عمران: 83","question":"لماذا خُتمت الآية بـ﴿وإليه يرجعون﴾ بعد ذكر إسلام الخلق؟","answer":"الرجوع إلى الله للحساب يبين نهاية هذا الخضوع ويجعل طلب غير دينه مناقضًا للمصير المحتوم؛ فمن أسلم له الكون رجع إليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص386–397.","url":""}]},{"id":"s3-278","number":278,"surah":3,"verses":[84],"verseLabel":"آل عمران: 84","question":"ما سرّ التعبير هنا في قوله تعالى ﴿قل آمنا بالله وما أنزل علينا﴾، وقال في البقرة ﴿قولوا آمنا... وما أنزل إلينا﴾؟","answer":"الخطاب في البقرة للأمة فقال ﴿قولوا﴾ و﴿إلينا﴾، أما هنا فبدأ بالنبي ممثلًا للأمة فقال ﴿قل﴾ و﴿علينا﴾ بما يوحي بعلو الوحي وثقل التكليف.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص397–410؛ مسح عكسي.","url":""}]},{"id":"s3-279","number":279,"surah":3,"verses":[84],"verseLabel":"آل عمران: 84","question":"لماذا قدّم ما أُنزل على المسلمين على ما أُنزل على إبراهيم وسائر النبيين؟","answer":"لأن المتكلم مأمور بإعلان إيمانه من موقع الرسالة الحاضرة، فبدأ بالوحي الذي يخاطبه ويكلفه، ثم وصلَه بأصول الوحي السابقة.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص397–410.","url":""}]},{"id":"s3-280","number":280,"surah":3,"verses":[84],"verseLabel":"آل عمران: 84","question":"لماذا أفرد ﴿وما أوتي موسى وعيسى﴾ ثم عمّم ﴿والنبيون من ربهم﴾؟","answer":"خُص موسى وعيسى لأن اليهود والنصارى موضع الحجاج، ثم عُمم بالنبيين ليدخل جميع رسل الله؛ فجمع إلزام الفريقين وكمال الإيمان.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص397–410.","url":""}]},{"id":"s3-281","number":281,"surah":3,"verses":[84],"verseLabel":"آل عمران: 84","question":"لماذا ختم الإيمان بالرسل بـ﴿لا نفرق بين أحد منهم﴾؟","answer":"خُتم بنفي التفريق لأن الإيمان الحق يقبل جميع رسل الله ولا يؤمن ببعض ويكفر ببعض؛ وهو رد مباشر على العصبية الكتابية.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص397–410.","url":""}]},{"id":"s3-282","number":282,"surah":3,"verses":[84],"verseLabel":"آل عمران: 84","question":"لماذا كرر في البقرة ﴿وما أوتي﴾ قبل النبيين، وحذف التكرار في آل عمران: ﴿وما أوتي موسى وعيسى والنبيون﴾؟","answer":"في البقرة كرر ﴿وَمَا أُوتِيَ﴾ للفصل بين موسى وعيسى وبين سائر النبيين وإبراز كل فريق، أما هنا فعطف النبيين عليهما تحت عامل واحد طلبًا للإيجاز ووحدة ما أوتوه من ربهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص351–353، تحت البقرة: 136، في المقارنة بآل عمران: 84.","url":""}]},{"id":"s3-283","number":283,"surah":3,"verses":[85],"verseLabel":"آل عمران: 85","question":"ما سرّ التعبير في قوله تعالى: ﴿ومن يبتغ غير الإسلام دينًا﴾ بتقديم ﴿غير الإسلام﴾؟","answer":"تقديم ﴿غَيْرَ الْإِسْلَامِ﴾ يسلط النفي على كل بديل من أول الجملة ويجعله موضع الإنكار، ثم جاء ﴿دِينًا﴾ تمييزًا لما يبتغيه.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص410–417.","url":""}]},{"id":"s3-284","number":284,"surah":3,"verses":[85],"verseLabel":"آل عمران: 85","question":"لماذا بُني ﴿فلن يقبل منه﴾ للمجهول؟","answer":"بُني ﴿لَنْ يُقْبَلَ﴾ للمجهول لأن فاعل القبول معلوم من السياق وهو الله، والعناية متجهة إلى القطع بعدم قبول أي دين يخالف الإسلام.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص410–417.","url":""}]},{"id":"s3-285","number":285,"surah":3,"verses":[85],"verseLabel":"آل عمران: 85","question":"لماذا جمع بين عدم القبول والخسران في الآخرة؟","answer":"عدم القبول حكم على العمل في ذاته، والخسران وصف لعاقبة صاحبه بعد ضياع رأس ماله وعمره؛ فجمع بطلان الطريق وسوء المصير.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص410–417.","url":""}]},{"id":"s3-286","number":286,"surah":3,"verses":[86],"verseLabel":"آل عمران: 86","question":"ما سرّ التعبير في قوله تعالى: ﴿كيف يهدي الله قومًا كفروا بعد إيمانهم﴾ بصيغة الاستفهام؟","answer":"الاستفهام للاستبعاد والتوبيخ: كيف يطلبون ثمرة الهداية وقد نقضوا مقتضياتها بعد العلم والشهادة؟ وهو لا يغلق التوبة التي استثنتها الآيات التالية.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص417–437.","url":""}]},{"id":"s3-287","number":287,"surah":3,"verses":[86],"verseLabel":"آل عمران: 86","question":"لماذا عطف ﴿وشهدوا أن الرسول حق﴾ على إيمانهم؟","answer":"عُطفت الشهادة على الإيمان لتبين أن كفرهم جاء بعد معرفة خاصة وإقرار بأن الرسول حق؛ فالجناية ليست جهلًا أوليًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص417–437.","url":""}]},{"id":"s3-288","number":288,"surah":3,"verses":[86],"verseLabel":"آل عمران: 86","question":"ما سرّ التعبير في قوله تعالى: ﴿وجاءهم البينات﴾ بعد الشهادة بأن الرسول حق؟","answer":"زاد ﴿وَجَاءَهُمُ الْبَيِّنَاتُ﴾ قيام الأدلة الواضحة من خارج نفوسهم إلى شهادتهم السابقة، فاجتمع الاعتراف والبرهان ثم وقع الكفر.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص417–437.","url":""}]},{"id":"s3-289","number":289,"surah":3,"verses":[86],"verseLabel":"آل عمران: 86","question":"لماذا ختم بـ﴿والله لا يهدي القوم الظالمين﴾ فوصفهم بالظلم؟","answer":"سماهم ظالمين لأنهم وضعوا الكفر موضع الإيمان بعد العلم، وظلموا أنفسهم برد الحق؛ فعدم الهداية جزاء إصرارهم لا نقص الدليل.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص417–437.","url":""}]},{"id":"s3-290","number":290,"surah":3,"verses":[87],"verseLabel":"آل عمران: 87","question":"لماذا جمعت اللعنة من الله والملائكة والناس أجمعين؟","answer":"لتصوير نبذهم في العوالم كلها: حكم الله بإبعادهم، وموافقة الملائكة، وظهور استحقاقهم عند الناس؛ فلا يبقى لهم موطن كرامة.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص417–437.","url":""}]},{"id":"s3-291","number":291,"surah":3,"verses":[136],"verseLabel":"آل عمران: 87؛ آل عمران: 136","question":"لماذا افتتحت آية اللعنة وآية المغفرة معًا بـ﴿أولئك جزاؤهم﴾ مع تضاد الجزاءين؟","answer":"وُحّد البناء لإقامة مقابلة عادلة واضحة: الثبات على الكفر بعد الإيمان يفضي إلى اللعنة، والرجوع بعد الذنب يفضي إلى المغفرة والجنة؛ فتشابه الصياغة يبرز أن اختلاف العاقبة ناشئ من اختلاف الاختيار.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص410–430 وص764–775.","url":""}]},{"id":"s3-292","number":292,"surah":3,"verses":[88],"verseLabel":"آل عمران: 88","question":"ما سرّ التعبير في قوله تعالى: ﴿خالدين فيها﴾ مع أن المذكور قبلها ﴿لعنة الله﴾؟","answer":"يعود ﴿فِيهَا﴾ إلى اللعنة أو إلى عاقبتها الملازمة من العذاب، فيفيد دوام الإبعاد عن الرحمة وما يترتب عليه، لا لعنة عابرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص417–437.","url":""}]},{"id":"s3-293","number":293,"surah":3,"verses":[88],"verseLabel":"آل عمران: 88","question":"لماذا جمع بين عدم تخفيف العذاب وعدم إنظارهم؟","answer":"نُفي النقص في شدة العذاب ونُفي تأخيره؛ فلا راحة بتخفيف الحاضر ولا أمل بمهلة تنقطع بها العقوبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص417–437.","url":""}]},{"id":"s3-294","number":294,"surah":3,"verses":[89],"verseLabel":"آل عمران: 89","question":"لماذا استثنى ﴿إلا الذين تابوا من بعد ذلك وأصلحوا﴾، ولم يكتف بالتوبة؟","answer":"أضيف الإصلاح إلى التوبة لأن من أفسد بالكفر بعد الإيمان لا يكفيه ادعاء الرجوع؛ بل تظهر صحة توبته بإصلاح الاعتقاد والعمل وما أفسده.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص417–437.","url":""}]},{"id":"s3-295","number":295,"surah":3,"verses":[89],"verseLabel":"آل عمران: 89","question":"لماذا ختمت آية التوبة بـ﴿فإن الله غفور رحيم﴾؟","answer":"الخاتمة تفتح باب الرجاء، وتبين أن المغفرة أثر الرحمة لا مجرد إسقاط العقوبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص417–437.","url":""}]},{"id":"s3-296","number":296,"surah":3,"verses":[90],"verseLabel":"آل عمران: 90","question":"ما سرّ التعبير في قوله تعالى: ﴿ثم ازدادوا كفرًا﴾، وكيف يزداد الكفر؟","answer":"يزداد الكفر بالاستمرار عليه وإضافة صور جديدة من الجحود والصد بعد الكفر الأول؛ فليس رتبة جامدة بل مسار يتفاقم.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص437–445.","url":""}]},{"id":"s3-297","number":297,"surah":3,"verses":[90],"verseLabel":"آل عمران: 90","question":"ما سرّ التعبير في قوله تعالى: ﴿لن تقبل توبتهم﴾ مع أن باب التوبة مفتوح؟","answer":"المراد توبة من استمر في الكفر وازداد فيه حتى حضره الموت، أو توبة غير صادقة؛ أما التوبة النصوح في وقت القبول فقد استثنتها الآية السابقة.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص437–445.","url":""}]},{"id":"s3-298","number":298,"surah":3,"verses":[90],"verseLabel":"آل عمران: 90","question":"لماذا خُتمت الآية بالقصر ﴿وأولئك هم الضالون﴾؟","answer":"اسم الإشارة وضمير الفصل وتعريف ﴿الضَّالُّونَ﴾ تقصر عليهم كمال الضلال في هذا المقام؛ إذ تركوا الهدى بعد معرفته واستمروا في الزيادة.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص437–445.","url":""}]},{"id":"s3-299","number":299,"surah":3,"verses":[91],"verseLabel":"آل عمران: 91","question":"ما سرّ التعبير في قوله تعالى: ﴿فلن يقبل من أحدهم ملء الأرض ذهبًا﴾؟","answer":"ملء الأرض ذهبًا غاية ما يتصوره الإنسان من مال، فنفى قبوله فداءً من كل واحد مات على الكفر؛ ليبين أن الآخرة لا تشترى بعد انقضاء زمن العمل.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص445–454.","url":""}]},{"id":"s3-300","number":300,"surah":3,"verses":[91],"verseLabel":"آل عمران: 91","question":"لماذا خُصّ الذهب في الفداء دون سائر الأموال؟","answer":"لأنه أصل الأثمان وأعلاها قيمة، وملء الأرض منه أقصى ما يتخيله الإنسان من فداء؛ فإذا رُدّ هذا علم أن النجاة ليست بالمال.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص445–454.","url":""}]},{"id":"s3-301","number":301,"surah":3,"verses":[91],"verseLabel":"آل عمران: 91","question":"ما سرّ التعبير في قوله تعالى: ﴿ولو افتدى به﴾ بعد نفي قبول ملء الأرض ذهبًا؟","answer":"بعد نفي قبول الذهب ولو ملء الأرض، زاد ﴿وَلَوِ افْتَدَى بِهِ﴾ ليدفع توهم أن المال لا يقبل صدقةً لكنه قد يقبل فدية؛ فنفى كل طريق مالي للنجاة بعد الموت على الكفر.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص445–454.","url":""}]},{"id":"s3-302","number":302,"surah":3,"verses":[91],"verseLabel":"آل عمران: 91","question":"ما سرّ التعبير في قوله تعالى: ﴿وما لهم من ناصرين﴾ بعد فرض الفداء؟","answer":"لما سقط أعظم فداء محتمل نفى وجود الناصر أيضًا، فجمع انقطاع وسيلة المال ووسيلة الأشخاص؛ و﴿مِنْ﴾ مع الجمع في النفي تستغرق كل ناصر.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص445–454.","url":""}]},{"id":"s3-303","number":303,"surah":3,"verses":[92],"verseLabel":"آل عمران: 92","question":"ما سرّ التعبير في قوله تعالى: ﴿لن تنالوا البر﴾، فجعل البر شيئًا يُنال؟","answer":"صوّر البر منزلةً عالية تُنال بعد سعي، وربطه ببذل المحبوب لأن صدق الإيمان يظهر عند مفارقة ما تتعلق به النفس.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص454–462.","url":""}]},{"id":"s3-304","number":304,"surah":3,"verses":[92],"verseLabel":"آل عمران: 92","question":"لماذا عُلّق نيل البر بالإنفاق ﴿مما تحبون﴾ لا بمجرد الإنفاق؟","answer":"عُلّق البر ببذل المحبوب لأن الإنفاق مما لا تتعلق به النفس قد يقع بلا مجاهدة؛ أما تقديم المحبوب فيكشف صدق الإيمان وتغلب محبة الله على محبة المال.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص454–462.","url":""}]},{"id":"s3-305","number":305,"surah":3,"verses":[92],"verseLabel":"آل عمران: 92","question":"ما سرّ التعبير في قوله تعالى: ﴿وما تنفقوا من شيء فإن الله به عليم﴾ بعد ذكر المحبوب؟","answer":"ليدخل كل إنفاق قليل أو كثير، وليقرر أن الله يعلم قيمة المبذول في قلب صاحبه وصدق نيته؛ فالعبرة ليست بمظهر المال وحده.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص454–462.","url":""}]},{"id":"s3-306","number":306,"surah":3,"verses":[93],"verseLabel":"آل عمران: 93","question":"ما سرّ التعبير في قوله تعالى: ﴿كل الطعام كان حلًا لبني إسرائيل﴾ ثم استثنى ما حرّم إسرائيل على نفسه؟","answer":"الأصل أن الأطعمة كانت حلالًا لبني إسرائيل، والاستثناء خاص بما ألزم إسرائيل نفسه به قبل نزول التوراة؛ فبطل زعم أن التحريم القديم شريعة عامة من الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص462–467.","url":""}]},{"id":"s3-307","number":307,"surah":3,"verses":[93],"verseLabel":"آل عمران: 93","question":"ما سرّ التعبير في قوله تعالى: ﴿إسرائيل﴾، دون أن يقال: يعقوب؟","answer":"جيء باسم ﴿إِسْرَائِيلَ﴾ لأنه الأب الذي ينتسب إليه بنوه المخاطبون، ولأن المقام في بيان ما حرمه على نفسه قبل التوراة؛ فالاسم يربط الحكم بتاريخ بني إسرائيل.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص462–467.","url":""}]},{"id":"s3-308","number":308,"surah":3,"verses":[93],"verseLabel":"آل عمران: 93","question":"لماذا أمرهم أن يأتوا بالتوراة ثم يتلوها إن كانوا صادقين؟","answer":"نقل الخصومة من الدعوى إلى النص الذي يحتجون به، وألزمهم أن يظهروه بأنفسهم؛ فتقوم الحجة من كتابهم وتنكشف جرأة التحريم المكذوب.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص462–467.","url":""}]},{"id":"s3-309","number":309,"surah":3,"verses":[94],"verseLabel":"آل عمران: 94","question":"ما سرّ التعبير في قوله تعالى: ﴿فمن افترى على الله الكذب من بعد ذلك﴾؟","answer":"﴿افْتَرَى﴾ أبلغ من مجرد الكذب، لأنه اختلاق متعمد ينسب إلى الله، و﴿مِنْ بَعْدِ ذَلِكَ﴾ تعظم الجريمة بعد ظهور الحجة من التوراة.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص467–471.","url":""}]},{"id":"s3-310","number":310,"surah":3,"verses":[94],"verseLabel":"آل عمران: 94","question":"لماذا حصر المفترين في ﴿فأولئك هم الظالمون﴾؟","answer":"اسم الإشارة وضمير الفصل وتعريف ﴿الظَّالِمُونَ﴾ تؤكد كمال ظلم من افترى بعد البيان؛ إذ ظلم الحق ونفسه ومن أضله.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص467–471.","url":""}]},{"id":"s3-311","number":311,"surah":3,"verses":[95],"verseLabel":"آل عمران: 95","question":"لماذا جاء الجواب المختصر ﴿قل صدق الله﴾ بعد تحديهم بالتوراة؟","answer":"بعد إلزامهم بالتوراة انقطعت الدعوى، فجاء ﴿قُلْ صَدَقَ اللَّهُ﴾ حكمًا حاسمًا موجزًا يثبت الوحي ويبطل ما نسبوه إلى الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص471–475.","url":""}]},{"id":"s3-312","number":312,"surah":3,"verses":[95],"verseLabel":"آل عمران: 95","question":"ما سرّ التعبير في قوله تعالى: ﴿فاتبعوا ملة إبراهيم﴾، دون أن يقال: دين إبراهيم؟","answer":"الملة هي الطريقة الدينية التي يجتمع عليها قوم وتُنسب إلى صاحبها، فناسب الأمر باتباع طريقة إبراهيم في التوحيد، لا مجرد الانتساب الاسمي إلى دينه.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص471–475.","url":""}]},{"id":"s3-313","number":313,"surah":3,"verses":[95],"verseLabel":"آل عمران: 95","question":"لماذا وصف إبراهيم مرة أخرى بـ﴿حنيفًا﴾ ثم نفى عنه الشرك؟","answer":"تكرر وصف إبراهيم بالحنيفية ونفي الشرك لأن السياق عاد إلى دعوى التحريم والانتساب إليه؛ فأعيد أصل ملته الذي يهدم افتراءهم ويثبت توحيده الخالص.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص471–475.","url":""}]},{"id":"s3-314","number":314,"surah":3,"verses":[96],"verseLabel":"آل عمران: 96","question":"ما سرّ التعبير في قوله تعالى: ﴿إن أول بيت وضع للناس﴾، دون أن يقال: بُني؟","answer":"﴿وُضِعَ﴾ أوسع من «بُني»؛ فهو يدل على تأسيس البيت وتعيينه للناس موضعًا للعبادة والهداية، لا على إنشاء جدرانه فحسب.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص475–480.","url":""}]},{"id":"s3-315","number":315,"surah":3,"verses":[96],"verseLabel":"آل عمران: 96","question":"ما سرّ التعبير في قوله تعالى: ﴿للذي ببكة﴾، دون أن يقال: بمكة؟","answer":"بكة اسم للموضع الذي فيه البيت أو لبطن مكة، وقيل من الازدحام فيه؛ فناسب الحديث عن البيت نفسه، أما مكة فاسم البلد الأوسع.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص480.","url":""}]},{"id":"s3-316","number":316,"surah":3,"verses":[96],"verseLabel":"آل عمران: 96","question":"لماذا وصف البيت بـ﴿مباركًا وهدى للعالمين﴾؟","answer":"البركة تصف كثرة خيره وثباته في العبادة والأمن، والهدى يصف وظيفته في توجيه الناس إلى التوحيد؛ فجمع أثره النافع ودلالته.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص475–480.","url":""}]},{"id":"s3-317","number":317,"surah":3,"verses":[97],"verseLabel":"آل عمران: 97","question":"ما سرّ التعبير في قوله تعالى: ﴿فيه آيات بينات مقام إبراهيم﴾، فذكر المقام بعد جمع الآيات؟","answer":"ذُكر مقام إبراهيم بعد جمع الآيات لأنه آية ظاهرة عظيمة منها، على البيان أو البدل، فانتقل من الإجمال إلى أبرز شاهد محسوس مرتبط ببناء البيت.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص480–490.","url":""}]},{"id":"s3-318","number":318,"surah":3,"verses":[97],"verseLabel":"آل عمران: 97","question":"ما سرّ التعبير في قوله تعالى: ﴿ومن دخله كان آمنًا﴾ بصيغة الخبر؟","answer":"جاء خبرًا يتضمن تشريع حرمة البيت وتذكيرًا بما أودع الله فيه من أمن؛ فصيغة الخبر أثبت وأبلغ من أمر عابر.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص480–490.","url":""}]},{"id":"s3-319","number":319,"surah":3,"verses":[97],"verseLabel":"آل عمران: 97","question":"ما سرّ التعبير في قوله تعالى: ﴿ولله على الناس حج البيت﴾ فجعل الحج حقًا لله على الناس؟","answer":"تقديم ﴿لِلَّهِ﴾ يثبت اختصاص الحق به، و﴿عَلَى النَّاسِ﴾ تفيد الوجوب في ذممهم؛ فالحج عبادة وحق لله لا مجرد زيارة اختيارية.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص480–490.","url":""}]},{"id":"s3-320","number":320,"surah":3,"verses":[97],"verseLabel":"آل عمران: 97","question":"لماذا قيّد وجوب الحج بـ﴿من استطاع إليه سبيلًا﴾؟","answer":"قُيد الوجوب بالاستطاعة رفعًا للحرج وربطًا للتكليف بالقدرة على الوصول؛ فـ﴿سَبِيلًا﴾ تشمل ما تتحقق به إمكانية الحج بحسب حال المكلف.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص480–490.","url":""}]},{"id":"s3-321","number":321,"surah":3,"verses":[97],"verseLabel":"آل عمران: 97","question":"لماذا عُدل من الحج إلى قوله ﴿ومن كفر فإن الله غني عن العالمين﴾؟","answer":"عُدل إلى ﴿وَمَنْ كَفَرَ﴾ لتغليظ شأن من جحد الفريضة أو تركها استهانةً مع القدرة، ثم بيّن أن ضرر امتناعه عليه لأن الله غني.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص488–490.","url":""}]},{"id":"s3-322","number":322,"surah":3,"verses":[97],"verseLabel":"آل عمران: 97","question":"ما سرّ التعبير في قوله تعالى: ﴿غني عن العالمين﴾ لا: غني عنه؟","answer":"لم يقل «عنه» بل ﴿عَنِ الْعَالَمِينَ﴾ ليقرر غناه المطلق عن حج هذا الفرد وعن طاعة الخلق جميعًا؛ فالعبادة لمصلحة العباد.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص480–490.","url":""}]},{"id":"s3-323","number":323,"surah":3,"verses":[98],"verseLabel":"آل عمران: 98","question":"لماذا تكرر النداء ﴿يا أهل الكتاب﴾ بعد الحجج السابقة؟","answer":"تجدد النداء لأن السياق انتقل إلى جريمة أخرى بعد حجج البيت: الكفر بآيات الله والصد عن سبيله؛ فاستدعى وصف أهل الكتاب مرة جديدة لإلزامهم بكتابهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص490–495.","url":""}]},{"id":"s3-324","number":324,"surah":3,"verses":[98],"verseLabel":"آل عمران: 98","question":"ما سرّ التعبير في قوله تعالى: ﴿لم تكفرون بآيات الله والله شهيد على ما تعملون﴾؟","answer":"الاستفهام توبيخ، ثم جاءت الشهادة تهديدًا بأن كفرهم ليس خافيًا ولا دعوى بلا حساب؛ فالله مطلع عليه ومجازٍ به.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص490–495.","url":""}]},{"id":"s3-325","number":325,"surah":3,"verses":[98],"verseLabel":"آل عمران: 98","question":"لماذا اختير ﴿شهيد﴾ هنا لا ﴿عليم﴾؟","answer":"الشهادة علم مع حضور وإقامة حجة، وهي أنسب بمقام محاكمة أعمال أهل الكتاب وتوبيخهم؛ فلا يقتصر المعنى على مجرد الإحاطة.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص490–495.","url":""}]},{"id":"s3-326","number":326,"surah":3,"verses":[99],"verseLabel":"آل عمران: 99","question":"ما سرّ التعبير في قوله تعالى: ﴿لم تصدون عن سبيل الله من آمن﴾ فجعل الدين سبيلًا؟","answer":"شُبه الدين بطريق يوصل إلى الله، والصد عنه بمنع السائرين؛ فالصورة تكشف أنهم لا يكتفون بضلال أنفسهم بل يعوقون من آمن.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص495–502.","url":""}]},{"id":"s3-327","number":327,"surah":3,"verses":[99],"verseLabel":"آل عمران: 99","question":"ما سرّ التعبير في قوله تعالى: ﴿تبغونها عوجًا﴾، وكيف يُطلب الاعوجاج للطريق؟","answer":"صُورت سبيل الله مستقيمةً وهم يطلبون جعلها ذات عوج بالتشويه والتلبيس في أعين الناس؛ فالاعوجاج لما يعرضونه من صورة الطريق لا لحقيقته.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص495–502.","url":""}]},{"id":"s3-328","number":328,"surah":3,"verses":[99],"verseLabel":"آل عمران: 99","question":"لماذا جاء ﴿وأنتم شهداء﴾ هنا، وجاء في آية 70 ﴿وأنتم تشهدون﴾؟","answer":"﴿تَشْهَدُونَ﴾ في الآية 70 فعل يستحضر شهادتهم المتجددة بالحق، و﴿شُهَدَاءُ﴾ هنا اسم يثبت رسوخ صفة المعرفة والشهادة فيهم مع استمرار صدهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص495–502.","url":""}]},{"id":"s3-329","number":329,"surah":3,"verses":[99],"verseLabel":"آل عمران: 99","question":"لماذا ختم بـ﴿وما الله بغافل عما تعملون﴾ بدل ﴿والله شهيد﴾؟","answer":"ناسب نفي الغفلة ما يدبرونه من صد خفي وتحريف؛ فالله لا يفوته عملهم ولا أثره وإن غفل عنه الناس، وفيه وعيد بالمحاسبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص495–502.","url":""}]},{"id":"s3-330","number":330,"surah":3,"verses":[100],"verseLabel":"آل عمران: 100","question":"ما سرّ التعبير في قوله تعالى: ﴿إن تطيعوا فريقًا من الذين أوتوا الكتاب﴾ ولم يعمم أهل الكتاب؟","answer":"قيد التحذير بـ﴿فَرِيقًا﴾ إنصافًا؛ فلم يعمم الذم على جميع أهل الكتاب، وإنما على الطائفة الساعية إلى رد المؤمنين.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص502–507.","url":""}]},{"id":"s3-331","number":331,"surah":3,"verses":[100],"verseLabel":"آل عمران: 100","question":"ما سرّ التعبير في قوله تعالى: ﴿أوتوا الكتاب﴾ لا ﴿آتيناهم الكتاب﴾؟","answer":"﴿أُوتُوا الْكِتَابَ﴾ تركز على حصول الكتاب في أيديهم مع إبهام الفاعل المعلوم من المقام، فتبرز المفارقة بين إيتائهم الوحي ومحاولتهم رد المؤمنين.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص502–507؛ مسح الويب.","url":""}]},{"id":"s3-332","number":332,"surah":3,"verses":[100],"verseLabel":"آل عمران: 100","question":"ما سرّ التعبير في قوله تعالى: ﴿يردوكم بعد إيمانكم كافرين﴾، فعبّر عن الكفر بالرد إلى الوراء؟","answer":"الرد رجوع إلى الحالة السابقة، فصوّر دعوتهم إلى الكفر حركة إلى الوراء بعد التقدم بالإيمان، وجاء ﴿كَافِرِينَ﴾ نتيجة لهذا الرد.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص502–507.","url":""}]},{"id":"s3-333","number":333,"surah":3,"verses":[149],"verseLabel":"آل عمران: 100؛ آل عمران: 149","question":"ما سرّ التعبير بقوله تعالى: في التحذير الأول ﴿يردوكم بعد إيمانكم كافرين﴾، وفي الثاني ﴿يردوكم على أعقابكم فتنقلبوا خاسرين﴾؟","answer":"الأول يصرح بنتيجة طاعة فريق أهل الكتاب وهي الكفر بعد الإيمان، أما الثاني ففي سياق أحد فصوّر طاعة الكافرين ارتدادًا حركيًا على الأعقاب يعقبه الخسران؛ فناسب التصريح مقام العقيدة والصورة الحسية مقام المعركة.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص502–507؛ ج6، ص88–95.","url":""}]},{"id":"s3-334","number":334,"surah":3,"verses":[101],"verseLabel":"آل عمران: 101","question":"ما سرّ التعبير في قوله تعالى: ﴿وكيف تكفرون وأنتم تتلى عليكم آيات الله وفيكم رسوله﴾؟","answer":"الاستفهام يستبعد الكفر مع اجتماع حجتين حاضرتين: الوحي المتلو والرسول المبيّن؛ فليس طريق العصمة غائبًا عنهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص507–513.","url":""}]},{"id":"s3-335","number":335,"surah":3,"verses":[101],"verseLabel":"آل عمران: 101","question":"لماذا قدّم تلاوة الآيات على وجود الرسول بينهم؟","answer":"لأن الآيات هي الحجة المتلوة التي تعصم من الكفر، ثم وجود الرسول هو البيان الحي والتطبيق؛ فبدأ بالوحي وأتبعه بمبلغه.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص507–513.","url":""}]},{"id":"s3-336","number":336,"surah":3,"verses":[101],"verseLabel":"آل عمران: 101","question":"ما سرّ التعبير في قوله تعالى: ﴿ومن يعتصم بالله﴾، وكيف يكون الاعتصام بالله؟","answer":"الاعتصام بالله لزوم هديه والالتجاء إلى حفظه كمن يتمسك بملجأ يمنعه السقوط؛ فالصورة تجمع الأخذ بالوحي والثقة بالناصر.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص507–513.","url":""}]},{"id":"s3-337","number":337,"surah":3,"verses":[101],"verseLabel":"آل عمران: 101","question":"لماذا جاء جواب الشرط ﴿فقد هدي إلى صراط مستقيم﴾ بالبناء للمجهول؟","answer":"بُني ﴿هُدِيَ﴾ للمجهول لأن الهادي معلوم وهو الله المذكور في الشرط، والعناية بالنتيجة المحققة للاعتصام: الوصول إلى الصراط المستقيم.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص507–513.","url":""}]},{"id":"s3-338","number":338,"surah":3,"verses":[102],"verseLabel":"آل عمران: 102","question":"ما سرّ التعبير في قوله تعالى: ﴿اتقوا الله حق تقاته﴾، وما سر إضافة التقوى إلى حقها؟","answer":"﴿حَقَّ تُقَاتِهِ﴾ مصدر مؤكد يطلب تقوى تليق بحق الله: طاعته وذكره وشكره بحسب الاستطاعة، لا تقوى اسمية أو ناقصة متعمدة.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص513–517.","url":""}]},{"id":"s3-339","number":339,"surah":3,"verses":[102],"verseLabel":"آل عمران: 102","question":"لماذا أتبع الأمر بالتقوى بقوله ﴿ولا تموتن إلا وأنتم مسلمون﴾؟","answer":"النهي ليس عن الموت الذي لا يملكه الإنسان، بل عن ملازمة كل حال قد يفجؤه فيها الموت؛ أي اثبتوا على الإسلام حتى النهاية.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص513–517.","url":""}]},{"id":"s3-340","number":340,"surah":3,"verses":[102],"verseLabel":"آل عمران: 102","question":"كيف يُنهى الإنسان عن الموت على غير الإسلام والموت ليس باختياره؟","answer":"النهي متجه إلى الحال التي يملكها الإنسان قبل الموت: الزموا الإسلام دائمًا حتى إذا جاء الموت وجدكم عليه؛ فدوام السبب في الاختيار وإن لم يكن وقت الموت فيه.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص513–517.","url":""}]},{"id":"s3-341","number":341,"surah":3,"verses":[103],"verseLabel":"آل عمران: 103","question":"ما سرّ التعبير في قوله تعالى: ﴿واعتصموا بحبل الله جميعًا﴾، وما صورة الحبل؟","answer":"حبل الله استعارة لما يصل العباد به ويعصمهم من الضلال، من قرآن وعهد ودين؛ وصورة التمسك بحبل واحد تجمع النجاة والوحدة.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص517–526.","url":""}]},{"id":"s3-342","number":342,"surah":3,"verses":[103],"verseLabel":"آل عمران: 103","question":"ما سرّ التعبير في قوله تعالى: ﴿جميعًا﴾ بعد واو الجماعة في ﴿اعتصموا﴾؟","answer":"واو الجماعة تدل على تعدد الفاعلين، أما ﴿جَمِيعًا﴾ فتوجب اجتماعهم كلهم على الحبل نفسه، وتنفي اعتصام جماعات متفرقة كل بطريق.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص517–526.","url":""}]},{"id":"s3-343","number":343,"surah":3,"verses":[103],"verseLabel":"آل عمران: 103","question":"لماذا قابل الاعتصام بقوله ﴿ولا تفرقوا﴾ ولم يقل: واتحدوا؟","answer":"الأمر بالاعتصام يبين الأصل الإيجابي الجامع، والنهي عن التفرق يسد ضده وطرقه؛ فليس المطلوب اتحادًا على أي شيء بل اجتماع على حبل الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص517–526.","url":""}]},{"id":"s3-344","number":344,"surah":3,"verses":[103],"verseLabel":"آل عمران: 103","question":"لماذا ذُكرت نعمة الله في تحويل الأعداء إلى إخوان؟","answer":"لأن الوحدة المطلوبة ليست اتفاقًا سياسيًا مجردًا، بل أثر هداية قلبية لا تصنعها العصبيات؛ وتذكّر العداوة القديمة يعظم نعمة التأليف.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص517–526.","url":""}]},{"id":"s3-345","number":345,"surah":3,"verses":[103],"verseLabel":"آل عمران: 103","question":"ما سرّ التعبير في قوله تعالى: ﴿فألف بين قلوبكم﴾، دون أن يقال: فألف بينكم؟","answer":"خُصت القلوب لأن التأليف الحقيقي إزالة للعداوة من الباطن، وهو أصل اجتماع الأبدان؛ فلو اقتصر على ﴿بينكم﴾ لم يظهر عمق التحول.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص517–526.","url":""}]},{"id":"s3-346","number":346,"surah":3,"verses":[103],"verseLabel":"آل عمران: 103","question":"ما سرّ التعبير في قوله تعالى: ﴿فأصبحتم بنعمته إخوانًا﴾ مع أن التحول لم يقع في صباح واحد؟","answer":"﴿أَصْبَحْتُمْ﴾ هنا بمعنى صرتم وتحولتم من حال إلى حال، ولا يلزم منها وقوع التحول في صباح واحد؛ وتستحضر ظهور النعمة بعد ظلمة العداوة.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص517–526.","url":""}]},{"id":"s3-347","number":347,"surah":3,"verses":[103],"verseLabel":"آل عمران: 103","question":"لماذا صوّر حالهم قبل الإسلام بأنهم ﴿على شفا حفرة من النار﴾؟","answer":"يصوّر حالهم قبل الإسلام واقفين على حافة هلاك لا يفصلهم عنه إلا خطوة، فتصير نعمة الإنقاذ مشهدًا محسوسًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص517–526.","url":""}]},{"id":"s3-348","number":348,"surah":3,"verses":[103],"verseLabel":"آل عمران: 103","question":"ما سرّ التعبير في قوله تعالى: ﴿فأنقذكم منها﴾، دون أن يقال: فأبعدكم عنها؟","answer":"الإنقاذ تخليص من هلاك وشيك بعد الإشراف عليه، وهو أبلغ من مجرد الإبعاد؛ فقد كانوا على شفا الحفرة لا بعيدين عنها.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص517–526.","url":""}]},{"id":"s3-349","number":349,"surah":3,"verses":[13],"verseLabel":"آل عمران: 103؛ الشورى: 13","question":"ما سرّ اختلاف التعبير بين قوله تعالى في آل عمران ﴿ولا تفرقوا﴾، وقوله تعالى في الشورى ﴿ولا تتفرقوا فيه﴾ بزيادة التاء والجار والمجرور؟","answer":"آل عمران تخاطب جماعة كانت مجتمعة وتحذرها من إحداث الفرقة، فجاء الفعل الأخف مطلقًا؛ أما الشورى ففي مقام إقامة الدين الذي تفرقت فيه الأمم، فصيغة ﴿تتفرقوا﴾ تصور التدرج والتكلف في صنع الفرقة، و﴿فيه﴾ تربط النهي بالدين المذكور.","sources":[{"label":"موسوعة التفسير البلاغي، ج35، ص393، في المقارنة بآل عمران: 103.","url":""}]},{"id":"s3-350","number":350,"surah":3,"verses":[78],"verseLabel":"آل عمران: 103؛ الحج: 78","question":"ما الفرق بين ﴿واعتصموا بحبل الله جميعًا﴾ في آل عمران و﴿واعتصموا بالله﴾ في الحج؟","answer":"الاعتصام بالله لجوء مباشر إلى الحافظ والناصر وهو الأعم، أما الاعتصام بحبل الله فتصوير للوسيلة الجامعة من وحي وعهد وجماعة؛ فالأول يبرز الملجأ، والثاني يبرز سبب الوحدة الموصل إليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج35، ص393.","url":""}]},{"id":"s3-351","number":351,"surah":3,"verses":[104],"verseLabel":"آل عمران: 104","question":"ما سرّ التعبير في قوله تعالى: ﴿ولتكن منكم أمة﴾، وهل المطلوب بعض الأمة أم جميعها؟","answer":"تحتمل ﴿مِنْ﴾ التبعيض؛ أي لتقم من الأمة جماعة تتخصص في الدعوة والأمر والنهي، وتحتمل البيان؛ أي لتكونوا أمةً هذه صفتها. وعلى الأول يكون قيام الجماعة فرض كفاية، ولا يسقط عن كل قادر ما وجب عليه بحسب استطاعته.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص526–532.","url":""}]},{"id":"s3-352","number":352,"surah":3,"verses":[104],"verseLabel":"آل عمران: 104","question":"لماذا قدّم الدعوة إلى الخير على الأمر بالمعروف والنهي عن المنكر؟","answer":"الدعوة إلى الخير أصل إيجابي جامع، ثم فُصلت حراسة المجتمع بإقامة المعروف ومنع المنكر؛ فانتقل من البناء العام إلى وظيفتيه العمليتين.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص526–532.","url":""}]},{"id":"s3-353","number":353,"surah":3,"verses":[104],"verseLabel":"آل عمران: 104","question":"لماذا عرّف ﴿الخير﴾ و﴿المعروف﴾ و﴿المنكر﴾؟","answer":"التعريف يجعل ﴿الخير﴾ و﴿المعروف﴾ و﴿المنكر﴾ حقائق معلومة بميزان الشرع، لا أمورًا يحددها الهوى؛ فالمدعو إليه هو الخير المعروف، والمأمور به ما عُرف حسنه، والمنهي عنه ما عُرف قبحه.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص526–532.","url":""}]},{"id":"s3-354","number":354,"surah":3,"verses":[104],"verseLabel":"آل عمران: 104","question":"لماذا حصر الفلاح في قوله ﴿وأولئك هم المفلحون﴾؟","answer":"اسم الإشارة للبعيد يفيد رفعة منزلتهم، وضمير الفصل ﴿هُم﴾ مع تعريف ﴿الْمُفْلِحُونَ﴾ يقوي اختصاصهم بكمال الفلاح؛ لأنهم جمعوا الدعوة إلى الخير والأمر بالمعروف والنهي عن المنكر.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص526–532.","url":""}]},{"id":"s3-355","number":355,"surah":3,"verses":[105],"verseLabel":"آل عمران: 105","question":"ما سرّ التعبير في قوله تعالى: ﴿ولا تكونوا كالذين تفرقوا واختلفوا﴾، وما الفرق بين التفرق والاختلاف؟","answer":"التفرق انفصال الجماعة والروابط، والاختلاف تنازع الآراء والمناهج؛ وقد يبدأ أحدهما سببًا للآخر، فنهى عن فساد البنية وفساد الفكرة معًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص532–536.","url":""}]},{"id":"s3-356","number":356,"surah":3,"verses":[105],"verseLabel":"آل عمران: 105","question":"ما سرّ التعبير في قوله تعالى: ﴿من بعد ما جاءهم البينات﴾؟","answer":"القيد ﴿مِنْ بَعْدِ مَا جَاءَهُمُ الْبَيِّنَاتُ﴾ يغلّظ ذم التفرق والاختلاف؛ لأنه وقع بعد وضوح الحجج، فلا يُعذر أصحابه بخفاء الحق أو التباسه.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص532–536.","url":""}]},{"id":"s3-357","number":357,"surah":3,"verses":[105],"verseLabel":"آل عمران: 105","question":"لماذا وصف العذاب هنا بـ﴿عظيم﴾ لا ﴿أليم﴾ أو ﴿شديد﴾؟","answer":"وصف العذاب بـ﴿عَظِيمٌ﴾ يبرز كِبره وهوله جزاءً لتفريق الجماعة بعد مجيء البينات؛ أما ﴿أليم﴾ فيلحظ الإيلام، و﴿شديد﴾ يلحظ القوة، ولكل وصف جهة.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص532–536.","url":""}]},{"id":"s3-358","number":358,"surah":3,"verses":[106],"verseLabel":"آل عمران: 106","question":"ما سرّ التعبير في قوله تعالى: ﴿يوم تبيض وجوه وتسود وجوه﴾، وما سر تحويل المعنى إلى لون الوجه؟","answer":"جعل الأثر في الوجوه لأن الوجه أظهر موضع تبدو فيه حال الإنسان؛ فالبياض يصور البشر والكرامة، والسواد يصور الكآبة والمهانة، فتحول العاقبة الباطنة إلى علامة مشاهدة.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص536–541.","url":""}]},{"id":"s3-359","number":359,"surah":3,"verses":[106],"verseLabel":"آل عمران: 106","question":"لماذا قدّم بياض الوجوه على سوادها؟","answer":"لأن السياق قبلها في خير الأمة والدعوة إلى الهدى، فبدأ بعاقبة أهل الاستجابة تشريفًا، ثم قابلها بعاقبة التفرق والكفر.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص536–541.","url":""}]},{"id":"s3-360","number":360,"surah":3,"verses":[106],"verseLabel":"آل عمران: 106","question":"لماذا نُكرت ﴿وجوه﴾ في الموضعين؟","answer":"تنكير ﴿وُجُوهٌ﴾ في الفريقين يقسم الجمع إلى صنفين تُعرف حالهما بالصفة لا بالأسماء، ويصور كثرة الوجوه التي يعمها البياض أو السواد في ذلك اليوم.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص536–541.","url":""}]},{"id":"s3-361","number":361,"surah":3,"verses":[106],"verseLabel":"آل عمران: 106","question":"ما سرّ التعبير بقوله تعالى: لأصحاب الوجوه السوداء ﴿أكفرتم بعد إيمانكم﴾ في صورة سؤال؟","answer":"الاستفهام في ﴿أكفرتم بعد إيمانكم﴾ ليس طلبًا للعلم، بل إنكار وتوبيخ يحمل المخاطب على مواجهة تناقضه وإصدار الحكم على نفسه.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص536–541.","url":""}]},{"id":"s3-362","number":362,"surah":3,"verses":[106],"verseLabel":"آل عمران: 106","question":"ما سرّ التعبير في قوله تعالى: ﴿فذوقوا العذاب﴾، وهل العذاب يُذاق؟","answer":"الذوق إحساس مباشر لا واسطة فيه، فاستعير لمباشرة العذاب ومعاناته؛ وفي الأمر ﴿فَذُوقُوا﴾ توبيخ يربط الجزاء بالكفر بعد الإيمان.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص536–541.","url":""}]},{"id":"s3-363","number":363,"surah":3,"verses":[107],"verseLabel":"آل عمران: 107","question":"ما سرّ التعبير في قوله تعالى: ﴿ففي رحمة الله هم فيها خالدون﴾ فجعل الرحمة مكانًا؟","answer":"جعلت الرحمة كالحيز المحيط بهم للدلالة على شمولها واستغراقهم فيها؛ فهم لا ينالون أثرًا عابرًا منها، بل يدخلون في نعيمها ويخلدون فيه.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص541–544.","url":""}]},{"id":"s3-364","number":364,"surah":3,"verses":[107],"verseLabel":"آل عمران: 107","question":"لماذا كرر الضمير في ﴿هم فيها خالدون﴾؟","answer":"إظهار الضمير ﴿هُمْ﴾ بعد تقديم ﴿فَفِي رَحْمَةِ اللَّهِ﴾ يثبت الحكم لأصحاب الوجوه المبيضة ويؤكده، ثم تعيد ﴿فِيهَا﴾ صلتهم بالرحمة وتقرر دوامهم فيها.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص541–544.","url":""}]},{"id":"s3-365","number":365,"surah":3,"verses":[108],"verseLabel":"آل عمران: 108","question":"ما سرّ التعبير في قوله تعالى: ﴿تلك آيات الله نتلوها عليك بالحق﴾ بالإشارة إلى البعيد؟","answer":"الإشارة بالبعيد في ﴿تِلْكَ﴾ ترفع شأن الآيات والأحكام المتقدمة وتستحضرها وحدةً مكتملة، ثم يقرر ﴿نَتْلُوهَا عَلَيْكَ بِالْحَقِّ﴾ صدق خبرها وعدل حكمها.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص544–549.","url":""}]},{"id":"s3-366","number":366,"surah":3,"verses":[108],"verseLabel":"آل عمران: 108","question":"لماذا نفى إرادة الظلم عن الله بقوله ﴿وما الله يريد ظلمًا للعالمين﴾؟","answer":"جاء نفي إرادة الظلم عقب ذكر الجزاءين ليدفع توهم الجور في تبييض وجوه وتسْويد أخرى؛ فالجزاء قائم على الحق، ولا يريد الله ظلم أحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص544–549.","url":""}]},{"id":"s3-367","number":367,"surah":3,"verses":[108],"verseLabel":"آل عمران: 108","question":"ما سرّ التعبير في قوله تعالى: ﴿للعالمين﴾ لا: لأحد؟","answer":"﴿لِلْعَالَمِينَ﴾ أعم من «لأحد» من جهة استحضار أصناف الخلق جميعًا؛ فنفى إرادة الظلم عن كل عالم وكل جماعة، ملائمًا لعموم الملك والحكم في الآية التالية.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص544–549.","url":""}]},{"id":"s3-368","number":368,"surah":3,"verses":[109],"verseLabel":"آل عمران: 109","question":"ما سرّ التعبير في قوله تعالى: ﴿ولله ما في السماوات وما في الأرض﴾ وكرر الموصول؟","answer":"إعادة ﴿مَا﴾ تجعل ما في السماوات وما في الأرض قسمين مستوعبين مستقلين في تقرير الملك، فلا تكون الأرض تابعة في اللفظ للسماوات، بل يشملها الحكم بتمامه.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص549–556.","url":""}]},{"id":"s3-369","number":369,"surah":3,"verses":[109],"verseLabel":"آل عمران: 109","question":"لماذا قدّم السماوات على الأرض هنا، مع تقديم الأرض في آية 5؟","answer":"هنا المقام تقرير الملك الشامل والرجوع إلى الله فبدأ بالأعلى والأعظم، أما آية 5 ففي علم ما يباشره الناس وما يُخفونه فبدأ بالأرض الأقرب إليهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص549–556.","url":""}]},{"id":"s3-370","number":370,"surah":3,"verses":[109],"verseLabel":"آل عمران: 109","question":"لماذا ختم بـ﴿وإلى الله ترجع الأمور﴾ ولم يقل: يرجع الناس؟","answer":"﴿الْأُمُورُ﴾ أعم من الناس؛ فهي تشمل ذواتهم وأعمالهم وأحكامهم وعواقبهم، وبذلك تلائم سبق عموم ملك ما في السماوات وما في الأرض.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص549–556.","url":""}]},{"id":"s3-371","number":371,"surah":3,"verses":[129],"verseLabel":"آل عمران: 109؛ آل عمران: 129","question":"لماذا تكرر ﴿ولله ما في السماوات وما في الأرض﴾، ثم ختمت الأولى بـ﴿وإلى الله ترجع الأمور﴾ والثانية بالمغفرة والعذاب؟","answer":"في الآية 109 جاء الملك عقب تقرير الحكم والعدل يوم القيامة فناسب رجوع الأمور كلها إليه، وفي 129 جاء بعد نفي أن يكون للرسول من الأمر شيء ففُصل تصرف المالك في عباده مغفرةً وتعذيبًا؛ فاتحد دليل الملك واختلفت النتيجة المطلوبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص549–556 وص719–726.","url":""}]},{"id":"s3-372","number":372,"surah":3,"verses":[110],"verseLabel":"آل عمران: 110","question":"ما سرّ التعبير في قوله تعالى: ﴿كنتم خير أمة﴾ بالماضي، دون أن يقال: أنتم خير أمة؟","answer":"الماضي يقرر الخيرية كحقيقة ثابتة في علم الله وكتبه، أو يذكّر بتحققها حين قامت الأمة بشروطها، لا أنه يمنحها امتيازًا بلا عمل.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص556–570؛ مسح الويب.","url":""}]},{"id":"s3-373","number":373,"surah":3,"verses":[110],"verseLabel":"آل عمران: 110","question":"ما سرّ التعبير في قوله تعالى: ﴿أخرجت للناس﴾ بالبناء للمجهول؟","answer":"البناء للمجهول يصرف النظر إلى إخراجها الرباني للقيام برسالة، و﴿للناس﴾ يجعل خيريتها وظيفة نفع وهداية لا تفوقًا ذاتيًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص556–570.","url":""}]},{"id":"s3-374","number":374,"surah":3,"verses":[110],"verseLabel":"آل عمران: 110","question":"لماذا قدّم الأمر بالمعروف والنهي عن المنكر على الإيمان بالله هنا؟","answer":"لأن الخيرية التي امتازت بها الأمة في علاقتها بالناس تظهر بهاتين الوظيفتين، ثم ذُكر الإيمان أصلًا يصححهما؛ وليس الترتيب ترتيب فضل مطلق.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص556–570.","url":""}]},{"id":"s3-375","number":375,"surah":3,"verses":[110],"verseLabel":"آل عمران: 110","question":"لماذا عُلّقت خيرية الأمة بنفع ﴿الناس﴾ لا بنفسها؟","answer":"تعلقت الخيرية بـ﴿لِلنَّاسِ﴾ لأن فضل الأمة وظيفة نفع وهداية للخلق بالأمر بالمعروف والنهي عن المنكر والإيمان، لا مزية ذاتية تستغني عن القيام بهذه الرسالة.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص556–570.","url":""}]},{"id":"s3-376","number":376,"surah":3,"verses":[110],"verseLabel":"آل عمران: 110","question":"ما سرّ التعبير في قوله تعالى: ﴿ولو آمن أهل الكتاب لكان خيرًا لهم﴾ مع أن فيهم مؤمنين؟","answer":"المراد بأهل الكتاب جماعتهم من حيث الغالب؛ ثم أنصف السياق فاستثنى المؤمنين منهم صراحةً بقوله ﴿مِنْهُمُ الْمُؤْمِنُونَ﴾، فلا تعارض بين الحكم العام ووجود أفراد مؤمنين.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص556–570.","url":""}]},{"id":"s3-377","number":377,"surah":3,"verses":[110],"verseLabel":"آل عمران: 110","question":"لماذا خُتمت الآية بـ﴿منهم المؤمنون وأكثرهم الفاسقون﴾؟","answer":"ختمت الآية بالاستثناء المنصف ﴿مِنْهُمُ الْمُؤْمِنُونَ﴾ حتى لا يعم الذم الجميع، ثم بينت أن الفسق هو وصف الأكثر؛ فجمعت دقة الحكم وبيان الغالب.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص556–570.","url":""}]},{"id":"s3-378","number":378,"surah":3,"verses":[111],"verseLabel":"آل عمران: 111","question":"ما سرّ التعبير في قوله تعالى: ﴿لن يضروكم إلا أذى﴾، وكيف استثنى الأذى من الضرر؟","answer":"الأذى ضرر يسير لا يبلغ استئصال الدين أو الجماعة؛ فالاستثناء يطمئن المؤمنين مع عدم إنكار ما يصيبهم من قول أو مشقة.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص570–576.","url":""}]},{"id":"s3-379","number":379,"surah":3,"verses":[111],"verseLabel":"آل عمران: 111","question":"لماذا صوّر هزيمتهم بقوله ﴿يولوكم الأدبار﴾؟","answer":"﴿يُوَلُّوكُمُ الْأَدْبَارَ﴾ يصور فرارهم التام في القتال؛ فبدل الخبر المجرد عن الهزيمة يرسم هيئة المنهزم الذي يجعل ظهره لخصمه.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص570–576.","url":""}]},{"id":"s3-380","number":380,"surah":3,"verses":[111],"verseLabel":"آل عمران: 111","question":"ما مناسبة قوله تعالى بعد ذكر الإدبار: ﴿ثم لا ينصرون﴾؟","answer":"﴿ثُمَّ﴾ تنقل من الهزيمة العاجلة إلى ما هو أبعد منها: استمرار الحرمان من النصرة؛ فلا يجدون بعد الإدبار قوة تستدرك هزيمتهم أو تقلب عاقبتها.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص570–576.","url":""}]},{"id":"s3-381","number":381,"surah":3,"verses":[112],"verseLabel":"آل عمران: 112","question":"ما سرّ التعبير في قوله تعالى: ﴿ضربت عليهم الذلة﴾، وكيف تُضرب الذلة؟","answer":"﴿ضُرِبَتْ عَلَيْهِمُ الذِّلَّةُ﴾ تصور الذلة كخيمة أو غطاء أحيط بهم وأُلزموا إياه؛ فتفيد ثبوتها وشمولها، لا مجرد عارض يمر بهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص576–590.","url":""}]},{"id":"s3-382","number":382,"surah":3,"verses":[112],"verseLabel":"آل عمران: 112","question":"ما سرّ التعبير في قوله تعالى: ﴿أين ما ثقفوا﴾، دون أن يقال: أينما وجدوا؟","answer":"﴿ثقفوا﴾ تفيد الظفر بهم والتمكن منهم، لا مجرد العثور المحايد؛ فهي أنسب بسياق الذلة والحماية التي لا تقوم إلا بعهد.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص576–590.","url":""}]},{"id":"s3-383","number":383,"surah":3,"verses":[112],"verseLabel":"آل عمران: 112","question":"لماذا استثنى ﴿إلا بحبل من الله وحبل من الناس﴾، وما صورة الحبلين؟","answer":"الحبل صورة للعهد والسبب الذي يمنح التمسك به عصمةً وأمانًا؛ فحبل الله ما يكون من عهده وحكمه، وحبل الناس ما يكون من عهدهم وأمانهم، ولا تزول الذلة إلا بسبب حماية معتبرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص576–590.","url":""}]},{"id":"s3-384","number":384,"surah":3,"verses":[112],"verseLabel":"آل عمران: 112","question":"لماذا كرر لفظ ﴿حبل﴾ ولم يقل: بحبل من الله والناس؟","answer":"كرر ﴿حَبْلٍ﴾ لأن المصدرين مختلفان: عهد من الله وعهد من الناس؛ فلكل واحد سبب حماية مستقل، ولو عطف «الناس» وحدها لأوهم أنه حبل واحد مشترك.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص576–590.","url":""}]},{"id":"s3-385","number":385,"surah":3,"verses":[112],"verseLabel":"آل عمران: 112","question":"ما سرّ التعبير في قوله تعالى: ﴿وباءوا بغضب من الله﴾، وكيف يرجع الإنسان بغضب؟","answer":"﴿بَاءُوا﴾ تفيد رجعوا متلبسين بالغضب أو احتملوه واستقر عليهم؛ فليس الغضب شيئًا عادوا به اختيارًا، بل عاقبة لزمتهم بسبب كفرهم واعتدائهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص576–590.","url":""}]},{"id":"s3-386","number":386,"surah":3,"verses":[112],"verseLabel":"آل عمران: 112","question":"لماذا عُطف ضرب المسكنة على ضرب الذلة؟","answer":"الذلة قهر ظاهر وفقد للعزة، والمسكنة فقر وانكسار باطن وحاجة؛ فجمع العقوبة في الحال الخارجية والنفسية.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص576–590.","url":""}]},{"id":"s3-387","number":387,"surah":3,"verses":[112],"verseLabel":"آل عمران: 112","question":"لماذا كرر ﴿ذلك بأنهم﴾ مرتين في تعليل حالهم؟","answer":"التعليل الأول يذكر الجرائم الكبرى: الكفر بالآيات وقتل الأنبياء، والثاني يردها إلى أصل السلوك المتكرر: العصيان وتجاوز الحدود؛ فتكرر التركيب لاختلاف درجتي التعليل.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص576–590.","url":""}]},{"id":"s3-388","number":388,"surah":3,"verses":[112],"verseLabel":"آل عمران: 112","question":"ما سرّ التعبير في قوله تعالى: ﴿ويقتلون الأنبياء بغير حق﴾ مع أن قتل الأنبياء لا يكون بحق أصلًا؟","answer":"﴿بِغَيْرِ حَقٍّ﴾ ليست للاحتراز من قتل جائز، بل لتسجيل بطلان فعلهم ونفي أدنى شبهة يتذرعون بها؛ فهي تشنيع على الجريمة وتوكيد لعدوانها.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص576–590.","url":""}]},{"id":"s3-389","number":389,"surah":3,"verses":[61],"verseLabel":"آل عمران: 112؛ البقرة: 61","question":"ما سرّ التعبير في قوله تعالى في البقرة ﴿ويقتلون النبيين﴾، وفي آل عمران ﴿ويقتلون الأنبياء﴾؟","answer":"نوّع القرآن بين جمعي «نبي»: ﴿النَّبِيِّينَ﴾ و﴿الْأَنْبِيَاءَ﴾، وجاء جمع التكسير في آل عمران ملائمًا لسياق تشنيع الجرائم وتعددها، مع اتحاد المرجع في الموضعين؛ فلا يترتب على اختلاف الصيغة اختلاف في الأنبياء المقصودين.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص526، البقرة: 61 في المقارنة بآل عمران: 112.","url":""}]},{"id":"s3-390","number":390,"surah":3,"verses":[61],"verseLabel":"آل عمران: 112؛ البقرة: 61","question":"ما سرّ التعبير في قوله تعالى في البقرة ﴿بغير الحق﴾ معرفًا، وفي آل عمران ﴿بغير حق﴾ منكرًا؟","answer":"التعريف في البقرة ينفي الحق المعروف الثابت من عند الله، أما التنكير في آل عمران فيعم كل حق متوهم أو مدعى؛ أي لم يكن قتلهم مستندًا إلى أدنى وجه من الحق حتى في دعواهم، وهو أنسب بسياق التغليظ.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص526، البقرة: 61 في المقارنة بآل عمران: 112.","url":""}]},{"id":"s3-391","number":391,"surah":3,"verses":[113],"verseLabel":"آل عمران: 113","question":"ما سرّ التعبير في قوله تعالى: ﴿ليسوا سواء﴾ بعد الأحكام على أهل الكتاب؟","answer":"﴿لَيْسُوا سَوَاءً﴾ استدراك يرفع توهم شمول الأحكام السابقة لكل أهل الكتاب؛ فبعد بيان حال الأكثر، فصلت الآيات طائفة مستقيمة مؤمنة، تحقيقًا للعدل في الحكم.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص590–601.","url":""}]},{"id":"s3-392","number":392,"surah":3,"verses":[113],"verseLabel":"آل عمران: 113","question":"لماذا وصف طائفة منهم بأنها ﴿أمة قائمة﴾؟","answer":"﴿أُمَّةٌ قَائِمَةٌ﴾ أي جماعة مستقيمة ثابتة على الحق والطاعة؛ وفي «قائمة» معنى النهوض بأمر الله والمداومة عليه، لا مجرد القيام الحسي.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص590–601.","url":""}]},{"id":"s3-393","number":393,"surah":3,"verses":[113],"verseLabel":"آل عمران: 113","question":"ما سرّ التعبير في قوله تعالى: ﴿يتلون آيات الله آناء الليل وهم يسجدون﴾، وخصّ الليل؟","answer":"خص الليل لأنه زمن الخلوة والإخلاص وهدوء الشواغل، و﴿آنَاءَ اللَّيْلِ﴾ تفيد ساعاته؛ وجمع التلاوة بالسجود يصور علمًا يثمر عبادة وخضوعًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص590–601.","url":""}]},{"id":"s3-394","number":394,"surah":3,"verses":[113],"verseLabel":"آل عمران: 113","question":"لماذا عطف السجود على تلاوة الآيات بجملة حالية؟","answer":"ليصور اجتماع العلم بالعبادة في الوقت نفسه: يتلون كتاب الله في حال خضوع وسجود، فلا تكون تلاوتهم معرفة مجردة بلا أثر.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص590–601.","url":""}]},{"id":"s3-395","number":395,"surah":3,"verses":[114],"verseLabel":"آل عمران: 114","question":"لماذا أعيد الإيمان بالله واليوم الآخر بعد وصفهم بتلاوة الكتاب؟","answer":"لأن التلاوة وحدها قد تقع بلا تصديق أو عمل، فأثبت لهم الإيمان الذي يميز تلاوتهم من تلاوة المحرفين ويصلها بالجزاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص590–601.","url":""}]},{"id":"s3-396","number":396,"surah":3,"verses":[114],"verseLabel":"آل عمران: 114","question":"ما سرّ التعبير في قوله تعالى: ﴿ويسارعون في الخيرات﴾، دون أن يقال: إلى الخيرات؟","answer":"﴿فِي الْخَيْرَاتِ﴾ تصورهم داخل ميادين الخير متلبسين بأعماله يتنافسون فيها، لا واقفين خارجها يسعون إلى مجرد بلوغها كما قد يوحي «إلى».","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص590–601.","url":""}]},{"id":"s3-397","number":397,"surah":3,"verses":[114],"verseLabel":"آل عمران: 114","question":"لماذا ختم بـ﴿وأولئك من الصالحين﴾ لا: هم الصالحون؟","answer":"﴿مِنَ الصَّالِحِينَ﴾ تدخلهم في جماعة الصالحين الواسعة من الأمم ولا تحصر الصلاح فيهم؛ فهي تزكية عادلة لا دعوى أنهم وحدهم الصالحون.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص590–601.","url":""}]},{"id":"s3-398","number":398,"surah":3,"verses":[115],"verseLabel":"آل عمران: 115","question":"ما سرّ التعبير في قوله تعالى: ﴿وما يفعلوا من خير فلن يكفروه﴾، وكيف يُكفر الخير؟","answer":"الكفر أصله الستر؛ فمعنى ﴿فَلَنْ يُكْفَرُوهُ﴾: لن يُجحدوا ثواب ما يفعلونه من خير ولن يُحرموا جزاءه، مهما قل، ويؤيده قوله بعده ﴿وَاللَّهُ عَلِيمٌ بِالْمُتَّقِينَ﴾.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص601–608.","url":""}]},{"id":"s3-399","number":399,"surah":3,"verses":[115],"verseLabel":"آل عمران: 115","question":"لماذا بُني ﴿فلن يكفروه﴾ للمجهول؟","answer":"بُني ﴿فَلَنْ يُكْفَرُوهُ﴾ للمجهول لتوجيه العناية إلى ضمان حفظ الخير وثوابه، أما الذي لا يجحده ولا يضيعه فمعلوم من السياق وهو الله؛ فالمقصود طمأنة العامل إلى النتيجة.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص601–608.","url":""}]},{"id":"s3-400","number":400,"surah":3,"verses":[115],"verseLabel":"آل عمران: 115","question":"لماذا ختم بـ﴿والله عليم بالمتقين﴾ لا بالمحسنين؟","answer":"لأن قبول العمل مردّه إلى باعث التقوى الخفي الذي يشمل الإحسان المذكور وغيره؛ فختم بالوصف الأعم والأصل الباطن.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص601–608.","url":""}]},{"id":"s3-401","number":401,"surah":3,"verses":[116],"verseLabel":"آل عمران: 116","question":"لماذا قدّم الأموال على الأولاد في نفي الإغناء؟","answer":"المال هو أول ما يُبذل عادة لدفع الضرر والفداء، ثم تأتي قوة الأولاد والنسب؛ فنفى القرآن أقرب وسيلتي الاعتماد عندهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص608–621.","url":""}]},{"id":"s3-402","number":402,"surah":3,"verses":[116],"verseLabel":"آل عمران: 116","question":"ما سرّ التعبير في قوله تعالى: ﴿لن تغني عنهم أموالهم ولا أولادهم من الله شيئًا﴾؟","answer":"أكدت ﴿لَنْ﴾ نفي الإغناء في الاستقبال، و﴿مِنَ اللَّهِ﴾ أي من حكمه أو عذابه، ونُكرت ﴿شَيْئًا﴾ في سياق النفي لاستغراق كل قدر من الدفع؛ فلا المال ولا الولد يدفعان عنهم شيئًا من الجزاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص608–621.","url":""}]},{"id":"s3-403","number":403,"surah":3,"verses":[116],"verseLabel":"آل عمران: 116","question":"ما دلالة الجملة المستقلة في قوله تعالى: ﴿وأولئك أصحاب النار هم فيها خالدون﴾؟","answer":"بعد الحكم بأنهم ﴿أَصْحَابُ النَّارِ﴾ جاءت الجملة الاسمية ﴿هُمْ فِيهَا خَالِدُونَ﴾ لتقرر دوام هذه الصحبة وثباتها، وتجيب عما قد يتوهم من إمكان مفارقتها. وتقديم ﴿فِيهَا﴾ يخص خلودهم بالنار ويزيد الوعيد بيانًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص608–621.","url":""}]},{"id":"s3-404","number":404,"surah":3,"verses":[117],"verseLabel":"آل عمران: 117","question":"لماذا شُبّه إنفاق الكافرين بريح فيها صر أصابت حرثًا؟","answer":"لأن الإنفاق يبدو كحرث يرجى ثمره، لكن الكفر يسلط عليه بردًا مهلكًا فيذهب أصله وثمرته؛ فالصورة تجمع العمل والرجاء ثم الخيبة المفاجئة.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص621–638.","url":""}]},{"id":"s3-405","number":405,"surah":3,"verses":[117],"verseLabel":"آل عمران: 117","question":"لماذا اختيرت ﴿ريح﴾ مفردة لا ﴿رياح﴾؟","answer":"إفراد ﴿رِيحٍ﴾ يجعل عامل الإهلاك قوة واحدة موجهة تصيب الحرث فتستأصله، وهو أنسب بصورة الضربة المفاجئة؛ ولا يراد نفي تعدد هبوبها، بل تصويرها وحدةً مهلكة.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص621–638.","url":""}]},{"id":"s3-406","number":406,"surah":3,"verses":[117],"verseLabel":"آل عمران: 117","question":"ما سرّ التعبير في قوله تعالى: ﴿فيها صر﴾، دون أن يقال: باردة أو شديدة؟","answer":"﴿الصِّرُّ﴾ شدة البرد النافذ، وفي مادته إيحاء بالشدة والصوت؛ فهو أبلغ من «باردة» لأنه يصور ريحًا يجتمع فيها البرد القارس والقوة التي تقبض النبات وتهلكه.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص621–638.","url":""}]},{"id":"s3-407","number":407,"surah":3,"verses":[117],"verseLabel":"آل عمران: 117","question":"ما سرّ التعبير في قوله تعالى: ﴿أصابت حرث قوم ظلموا أنفسهم﴾، وما أثر وصفهم بالظلم؟","answer":"وصف أصحاب الحرث بأنهم ﴿ظَلَمُوا أَنْفُسَهُمْ﴾ يربط الهلاك بسبب من جهتهم، كما أن إنفاق الكافرين أبطله كفرهم؛ فالصورة لا تعرض خسارة بريئة، بل عملًا أفسده صاحبه على نفسه.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص621–638.","url":""}]},{"id":"s3-408","number":408,"surah":3,"verses":[117],"verseLabel":"آل عمران: 117","question":"ما سرّ التعبير في قوله تعالى: ﴿فأهلكته﴾ بعد أن صوّر الإصابة؟","answer":"الفاء تصل الإصابة بنتيجتها السريعة، و﴿أَهْلَكَتْهُ﴾ تدل على ذهاب الحرث كله لا مجرد إصابته بضرر؛ وبذلك تتم صورة بطلان الإنفاق الذي لا يبقى لصاحبه ثمر.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص621–638.","url":""}]},{"id":"s3-409","number":409,"surah":3,"verses":[117],"verseLabel":"آل عمران: 117","question":"لماذا نفى ظلم الله ثم قال ﴿ولكن أنفسهم يظلمون﴾؟","answer":"نُفي الظلم عن الله أولًا، ثم حُصر الظلم في أنفسهم بتقديم ﴿أَنْفُسَهُمْ﴾؛ لأن سبب ضياع أعمالهم قائم بكفرهم وسوء اختيارهم. وجاء المضارع ﴿يَظْلِمُونَ﴾ مصورًا استمرار هذا المسلك وتجددَه.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص621–638.","url":""}]},{"id":"s3-410","number":410,"surah":3,"verses":[118],"verseLabel":"آل عمران: 118","question":"ما سرّ التعبير في قوله تعالى: ﴿لا تتخذوا بطانة من دونكم﴾، وما صورة البطانة؟","answer":"البطانة باطن الثوب الملاصق للجسد؛ فاستعيرت لمن يُدنى إلى الأسرار ويلازم صاحبَه من الداخل. والنهي ليس عن مطلق التعامل مع المخالف، بل عن اتخاذ من لا يؤتمن على جماعة المؤمنين موضعَ سر وثقة.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص638–650.","url":""}]},{"id":"s3-411","number":411,"surah":3,"verses":[118],"verseLabel":"آل عمران: 118","question":"ما سرّ التعبير في قوله تعالى: ﴿لا يألونكم خبالًا﴾، دون أن يقال: لا يقصرون في إفسادكم؟","answer":"﴿لَا يَأْلُونَكُمْ خَبَالًا﴾ أي لا يقصرون في طلب فساد أمركم واضطرابه، بل يبذلون غاية الوسع فيه؛ فالعبارة تجمع نفي التقصير وشدة السعي إلى الخبال في لفظ موجز.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص638–650.","url":""}]},{"id":"s3-412","number":412,"surah":3,"verses":[118],"verseLabel":"آل عمران: 118","question":"ما سرّ التعبير في قوله تعالى: ﴿ودوا ما عنتم﴾، فجعل مشقتهم أمنية؟","answer":"﴿وَدُّوا مَا عَنِتُّمْ﴾ يكشف أن مشقتكم ليست نتيجة عارضة ترضيهم، بل أمر محبوب يتمنونه؛ و﴿عَنِتُّمْ﴾ تدل على ما يلحقكم من شدة وضرر.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص638–650.","url":""}]},{"id":"s3-413","number":413,"surah":3,"verses":[118],"verseLabel":"آل عمران: 118","question":"ما سرّ التعبير في قوله تعالى: ﴿قد بدت البغضاء من أفواههم﴾ لا من ألسنتهم؟","answer":"اختيرت الأفواه لأنها منفذ الكلام كله، فكأن البغضاء امتلأت بها حتى فاضت، وما بقي في الصدور أعظم.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص650.","url":""}]},{"id":"s3-414","number":414,"surah":3,"verses":[118],"verseLabel":"آل عمران: 118","question":"ما سرّ التعبير في قوله تعالى: ﴿وما تخفي صدورهم أكبر﴾، دون أن يقال: قلوبهم؟","answer":"الصدور أوعية القلوب وما يخفى فيها؛ فذكرها يقابل ﴿أَفْوَاهِهِمْ﴾: ما خرج من الظاهر بدا، وما بقي محجوبًا في الباطن أكبر. وهذا التقابل أوضح من ذكر القلوب وحدها.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص638–650.","url":""}]},{"id":"s3-415","number":415,"surah":3,"verses":[118],"verseLabel":"آل عمران: 118","question":"لماذا خُتمت الآية بـ﴿إن كنتم تعقلون﴾؟","answer":"جاء الشرط ﴿إِنْ كُنْتُمْ تَعْقِلُونَ﴾ لاستنهاض العقل إلى الانتفاع بالآيات التي كُشفت لهم، والتمييز بين الولي والعدو؛ فمن عقل دلائل العداوة لم يضع سره وثقته في غير موضعهما.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص638–650.","url":""}]},{"id":"s3-416","number":416,"surah":3,"verses":[119],"verseLabel":"آل عمران: 119","question":"ما سرّ التعبير في قوله تعالى: ﴿ها أنتم أولاء تحبونهم ولا يحبونكم﴾؟","answer":"﴿هَا﴾ للتنبيه و﴿أَنْتُمْ أُولَاءِ﴾ تستحضر المخاطبين كأن حالهم معروضة أمامهم، ثم تأتي المفارقة: أنتم تحبونهم وهم لا يحبونكم؛ فيوقظهم الأسلوب إلى موضع العجب في هذه العلاقة غير المتكافئة.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص650–660.","url":""}]},{"id":"s3-417","number":417,"surah":3,"verses":[119],"verseLabel":"آل عمران: 119","question":"ما سرّ التعبير في قوله تعالى: ﴿وتؤمنون بالكتاب كله﴾ بالإفراد مع تعدد الكتب؟","answer":"أُفرد ﴿الْكِتَابِ﴾ والمراد جنس الكتب المنزلة؛ للدلالة على وحدة مصدرها وتوافق أصولها، فالمؤمنون يؤمنون بها كلها، بخلاف من يقبل بعض الوحي ويرد بعضه.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص650–660.","url":""}]},{"id":"s3-418","number":418,"surah":3,"verses":[119],"verseLabel":"آل عمران: 119","question":"ما سرّ قولهم عند اللقاء ﴿آمَنَّا﴾، ثم عضِّهم الأنامل إذا خلوا؟","answer":"قولهم ﴿آمَنَّا﴾ عند اللقاء نفاق أو تعمية؛ يظهرون للمؤمنين معنى التصديق، فإذا خلوا بأصحابهم انكشف ما فيهم من غيظ. فالتقابل بين اللقاء والخلوة يفضح اختلاف ظاهرهم وباطنهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص650–660.","url":""}]},{"id":"s3-419","number":419,"surah":3,"verses":[119],"verseLabel":"آل عمران: 119","question":"ما سرّ التعبير في قوله تعالى: ﴿عضوا عليكم الأنامل من الغيظ﴾ لا الأصابع؟","answer":"الأنامل أطراف الأصابع، وهي التي يقع عليها العض حقيقة عند اشتداد الغيظ؛ فاختيارها يرسم أدق هيئة للعاجز الذي بلغ به الغيظ مبلغًا لا يملك معه إلا أن يعض أطراف أصابعه.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص650–660.","url":""}]},{"id":"s3-420","number":420,"surah":3,"verses":[119],"verseLabel":"آل عمران: 119","question":"لماذا أُمر النبي أن يقول ﴿موتوا بغيظكم﴾؟","answer":"الأمر في ﴿مُوتُوا بِغَيْظِكُمْ﴾ ليس تكليفًا بالموت، بل دعاء عليهم وتهديد بأن غيظهم سيبقى ملازمًا لهم حتى يموتوا، مع بشارة المؤمنين بأن هذا الغيظ عاجز عن إطفاء قوة الإسلام.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص650–660.","url":""}]},{"id":"s3-421","number":421,"surah":3,"verses":[119],"verseLabel":"آل عمران: 119","question":"لماذا ختم بـ﴿إن الله عليم بذات الصدور﴾؟","answer":"السياق يكشف بغضًا يخفونه وراء الكلام، فناسبه العلم الملازم لما استقر في الصدور قبل أن يظهر على الألسنة.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص650–660.","url":""}]},{"id":"s3-422","number":422,"surah":3,"verses":[120],"verseLabel":"آل عمران: 120","question":"ما سرّ التعبير في قوله تعالى: ﴿إن تمسسكم حسنة تسؤهم﴾، فجعل الحسنة تمس؟","answer":"المس أدنى الإصابة وألطفها؛ فالتعبير يدل على أنهم يساؤون حتى من أقل حسنة تنال المؤمنين، وفيه كشف لشدة بغضهم إذ يضيقون بأيسر خير يصيبهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص660–668.","url":""}]},{"id":"s3-423","number":423,"surah":3,"verses":[120],"verseLabel":"آل عمران: 120","question":"لماذا قابل ﴿حسنة﴾ بـ﴿سيئة﴾ مع أن المراد نعمة ومصيبة؟","answer":"الحسنة والسيئة لفظان عامان لكل ما يسر وما يسوء، ووقوعهما نكرتين في سياق الشرط يعم أنواع النعمة والمصيبة؛ فلا ينحصر المعنى في صورة واحدة منهما.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص660–668.","url":""}]},{"id":"s3-424","number":424,"surah":3,"verses":[120],"verseLabel":"آل عمران: 120","question":"ما سرّ التعبير في قوله تعالى في الحسنة ﴿تسؤهم﴾ وفي السيئة ﴿يفرحوا بها﴾؟","answer":"في جانب الحسنة ذكر أثرها فيهم: ﴿تَسُؤْهُمْ﴾، وفي جانب السيئة كشف فرحهم المتجدد بها: ﴿يَفْرَحُوا بِهَا﴾؛ فجمع بين تألمهم من خير المؤمنين وابتهاجهم بشرهم، وهما علامتان على تمكن العداوة.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص660–668.","url":""}]},{"id":"s3-425","number":425,"surah":3,"verses":[120],"verseLabel":"آل عمران: 120","question":"لماذا جُمع الصبر والتقوى في شرط بطلان كيدهم؟","answer":"الصبر يمنع الانهيار أمام الأذى، والتقوى تمنع مجاوزة الحق في الرد؛ وباجتماعهما تحفظ القوة من الضعف ومن الانحراف.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص660–668.","url":""}]},{"id":"s3-426","number":426,"surah":3,"verses":[120],"verseLabel":"آل عمران: 120","question":"ما سرّ التعبير في قوله تعالى: ﴿لا يضركم كيدهم شيئًا﴾ فنكّر شيئًا؟","answer":"نُكرت ﴿شَيْئًا﴾ في سياق النفي لتعم أقل مقدار من الضرر؛ أي مع الصبر والتقوى لا يبلغ كيدهم ضررًا معتبرًا، وإن وقع أذى يسير سبق أن استثنته الآيات.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص660–668.","url":""}]},{"id":"s3-427","number":427,"surah":3,"verses":[120],"verseLabel":"آل عمران: 120","question":"ما دلالة وصف الله تعالى بأنه ﴿بما يعملون محيط﴾ في ختام الآية؟","answer":"الإحاطة هنا كناية عن شمول علم الله وقدرته لأعمالهم وكيدهم، فلا يفوته منها ظاهر ولا خفي. وخاتمتها تطمئن المؤمنين أن ما أُمروا بالصبر والتقوى في مواجهته واقع تحت علم الله وتدبيره.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص660–668.","url":""}]},{"id":"s3-428","number":428,"surah":3,"verses":[121],"verseLabel":"آل عمران: 121","question":"ما سرّ التعبير في قوله تعالى: ﴿وإذ غدوت من أهلك﴾، دون أن يقال: خرجت؟","answer":"﴿غَدَوْتَ﴾ لا تدل على مجرد الخروج، بل تحدد أنه كان في أول النهار، فتستحضر بداية الحركة من البيت إلى ميدان أُحد وتدخل السامع في زمن الواقعة.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص668–672.","url":""}]},{"id":"s3-429","number":429,"surah":3,"verses":[121],"verseLabel":"آل عمران: 121","question":"ما سرّ التعبير في قوله تعالى: ﴿تبوئ المؤمنين مقاعد للقتال﴾، وما صورة التبوئة والمقاعد؟","answer":"التبوئة تهيئة المكان وإنزال صاحبه فيه على وجه الاستقرار، والمقاعد مواضع الثبات. فالصورة تظهر دقة ترتيب النبي ﷺ للمؤمنين في مواقع القتال، لا مجرد جمعهم في الميدان.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص668–672.","url":""}]},{"id":"s3-430","number":430,"surah":3,"verses":[121],"verseLabel":"آل عمران: 121","question":"لماذا ختمت الآية بـ﴿والله سميع عليم﴾؟","answer":"يسمع ما دار من المشاورة والأقوال عند الخروج، ويعلم النيات والتدبير؛ فخاتمتها إحاطة بما ظهر وما بطن في موقف أحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص668–672.","url":""}]},{"id":"s3-431","number":431,"surah":3,"verses":[122],"verseLabel":"آل عمران: 122","question":"ما سرّ التعبير في قوله تعالى: ﴿إذ همت طائفتان منكم أن تفشلا﴾، دون أن يقال: عزمتا؟","answer":"الهمّ مبدأ توجه النفس إلى الفعل قبل العزم الجازم؛ فالآية تثبت أن الفشل خطر لهما وقاربتاه، لا أنهما عقدتا العزم عليه أو نفذتاه، ولذلك أعقبه تدارك الولاية الإلهية.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص672–681.","url":""}]},{"id":"s3-432","number":432,"surah":3,"verses":[122],"verseLabel":"آل عمران: 122","question":"لماذا ثنّى ﴿طائفتان﴾ ثم قال ﴿والله وليهما﴾ بالمفرد؟","answer":"ثُنِّيت الطائفتان لأنهما جماعتان معلومتان، ثم جُمعتا في الضمير ﴿وَلِيُّهُمَا﴾ تحت ولاية واحدة مصدرها الله؛ فاختلاف الجماعتين لا يفرق جهة الحفظ والنصرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص672–681.","url":""}]},{"id":"s3-433","number":433,"surah":3,"verses":[122],"verseLabel":"آل عمران: 122","question":"لماذا جاء بعد الهمّ بالفشل قوله ﴿والله وليهما﴾؟","answer":"جاء ﴿وَاللَّهُ وَلِيُّهُمَا﴾ لبيان أن الهم بالفشل لم يستقر ولم يتحول إلى انصراف؛ فقد تداركتهما ولاية الله بالتثبيت، وفيه إنصاف للطائفتين بعد ذكر ما خطر لهما.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص672–681.","url":""}]},{"id":"s3-434","number":434,"surah":3,"verses":[122],"verseLabel":"آل عمران: 122","question":"لماذا ختم بـ﴿وعلى الله فليتوكل المؤمنون﴾ بتقديم الجار والمجرور؟","answer":"تقديم ﴿عَلَى اللَّهِ﴾ يفيد قصر اعتماد المؤمنين عليه، والفاء تربط التوكل بما ظهر من تثبيته للطائفتين؛ فولاية الله هي التي تستوجب إفراده بالاعتماد.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص672–681.","url":""}]},{"id":"s3-435","number":435,"surah":3,"verses":[123],"verseLabel":"آل عمران: 123","question":"ما سرّ التعبير في قوله تعالى: ﴿ولقد نصركم الله ببدر وأنتم أذلة﴾؟","answer":"اللام و﴿قَدْ﴾ تؤكدان وقوع النصر في بدر وتستحضران الشاهد التاريخي، وجملة الحال ﴿وَأَنْتُمْ أَذِلَّةٌ﴾ تقابل ضعف أسبابهم بقوة التأييد الإلهي؛ فتكون تذكيرًا يعالج اضطراب أُحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص681–690.","url":""}]},{"id":"s3-436","number":436,"surah":3,"verses":[123],"verseLabel":"آل عمران: 123","question":"لماذا وصف المؤمنين يوم بدر بـ﴿أذلة﴾ لا: قليلين؟","answer":"﴿أَذِلَّةٌ﴾ أوسع من «قليلين»؛ فهي تصور قلة العدد والعدة وضعف المنعة في نظر الناس، من غير أن تعني ذلة الدين أو النفس، وبذلك يعظم ظهور النصر من عند الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص681–690.","url":""}]},{"id":"s3-437","number":437,"surah":3,"verses":[123],"verseLabel":"آل عمران: 123","question":"لماذا أُتبع النصر بالأمر ﴿فاتقوا الله لعلكم تشكرون﴾؟","answer":"رتب على تذكيرهم بنصر بدر قوله ﴿فَاتَّقُوا اللَّهَ﴾ لأن حفظ النعمة يكون بالطاعة، وجعل الشكر غاية مرجوة للتقوى؛ فليس الشكر قولًا فقط بل التزامًا بأمر المنعم.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص681–690.","url":""}]},{"id":"s3-438","number":438,"surah":3,"verses":[124],"verseLabel":"آل عمران: 124","question":"ما دلالة عرض كفاية المدد في صورة السؤال: ﴿ألن يكفيكم﴾؟","answer":"التقرير يحملهم على الإقرار بأن مدد الله كافٍ، فينشأ الاطمئنان من جواب تستحضره نفوسهم لا من خبر يلقى عليهم فقط.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص690–701.","url":""}]},{"id":"s3-439","number":439,"surah":3,"verses":[124],"verseLabel":"آل عمران: 124","question":"ما سرّ التعبير في قوله تعالى: ﴿أن يمدكم ربكم﴾، دون أن يقال: ينصركم؟","answer":"الإمداد إلحاق مدد بعد مدد لتقوية الموجود وتثبيته، أما النصر فهو النتيجة. فاختير ﴿يُمِدَّكُمْ﴾ عند بيان زيادة الملائكة، ثم قرر بعد ذلك أن النصر نفسه لا يكون إلا من عند الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص690–701.","url":""}]},{"id":"s3-440","number":440,"surah":3,"verses":[124],"verseLabel":"آل عمران: 124","question":"لماذا كان الإمداد بـ﴿ثلاثة آلاف من الملائكة منزلين﴾؟","answer":"عُرضت الثلاثة آلاف بوصفها مددًا كثيرًا كافيًا يطمئن المؤمنين، لا لتقرير أن للنصر عددًا لازمًا. ولا يثبت النص تعليلًا مستقلًا لتخصيص هذا العدد، وإنما يبرز وفرة المدد الخاضع لأمر الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص690–701.","url":""}]},{"id":"s3-441","number":441,"surah":3,"verses":[9],"verseLabel":"آل عمران: 124؛ الأنفال: 9","question":"لماذا كان الإمداد في الأنفال بألف من الملائكة، وفي آل عمران بثلاثة آلاف ثم خمسة آلاف؟","answer":"آية الأنفال تحكي أصل الاستجابة يوم بدر فذكرت الألف ابتداءً، أما آل عمران فتستعيد الموقف لتثبيت المؤمنين بعد أحد وتعرض تدرج البشارة بحسب الصبر والتقوى وفور العدو؛ فالأعداد مراحل إمداد وبشارة لا تعارض بينها.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص690–701، مع الأنفال: 9.","url":""}]},{"id":"s3-442","number":442,"surah":3,"verses":[125],"verseLabel":"آل عمران: 125","question":"لماذا ارتفع العدد من ثلاثة آلاف إلى خمسة آلاف؟","answer":"البشارة الثانية معلقة بصبرهم وتقواهم ومجيء العدو من فوره، فزاد العدد مع اشتداد الظرف وثبات المؤمنين؛ وهو تدرج في التطمين لا اضطراب في الخبر.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص690–701.","url":""}]},{"id":"s3-443","number":443,"surah":3,"verses":[125],"verseLabel":"آل عمران: 125","question":"لماذا عُلّق الإمداد بشرطي الصبر والتقوى؟","answer":"ليتعلق القلب بالطاعة لا بالعدد: الصبر ثبات أمام العدو، والتقوى حفظ لأمر الله؛ وهما سبب الأهلية للتأييد.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص690–701.","url":""}]},{"id":"s3-444","number":444,"surah":3,"verses":[125],"verseLabel":"آل عمران: 125","question":"ما سرّ التعبير في قوله تعالى: ﴿ويأتوكم من فورهم هذا﴾؟","answer":"الفور هو الحال العاجلة التي لا إبطاء فيها، و﴿هَذَا﴾ تستحضر سرعتها وقربها؛ فالمعنى: إن يباغتكم العدو آتيًا من ساعته، يأتكم مدد الله في الوقت نفسه.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص690–701.","url":""}]},{"id":"s3-445","number":445,"surah":3,"verses":[125],"verseLabel":"آل عمران: 125","question":"لماذا وُصف الملائكة بـ﴿مسوّمين﴾؟","answer":"﴿مُسَوِّمِينَ﴾ أي معلَّمين بعلامات أو معلِّمين خيلهم، وفي القراءتين صورة جيش منظم ظاهر السِّمة؛ فتزيد البشارة بالمَدَد وضوحًا وهيبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص690–701.","url":""}]},{"id":"s3-446","number":446,"surah":3,"verses":[126],"verseLabel":"آل عمران: 126","question":"ما سرّ التعبير في قوله تعالى: ﴿وما جعله الله إلا بشرى لكم ولتطمئن قلوبكم به﴾، مع أن النصر حاصل؟","answer":"قصر وظيفة المدد على البشارة والطمأنينة حتى لا تتعلق القلوب بالملائكة أو العدد؛ فالنصر في حقيقته من عند الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص701–714.","url":""}]},{"id":"s3-447","number":447,"surah":3,"verses":[126],"verseLabel":"آل عمران: 126","question":"لماذا نُسب الاطمئنان إلى القلوب؟","answer":"لأن القلب موطن الخوف والثبات والنية، والمقصود من المدد تسكين الاضطراب الباطن قبل أثره العسكري؛ أما النصر فمن عند الله لا من العدد.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص701–714.","url":""}]},{"id":"s3-448","number":448,"surah":3,"verses":[126],"verseLabel":"آل عمران: 126","question":"لماذا ختم بـ﴿العزيز الحكيم﴾؟","answer":"العزة تثبت نفاذ القدرة، والحكمة تثبت أن هذا النفاذ موضوع في موضعه بلا عبث ولا ظلم.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص701–714.","url":""}]},{"id":"s3-449","number":449,"surah":3,"verses":[10],"verseLabel":"آل عمران: 126؛ الأنفال: 10","question":"لماذا زادت آل عمران ﴿بشرى لكم﴾، بينما قالت الأنفال ﴿إلا بشرى﴾؟","answer":"آل عمران تحكي بدرًا للمواساة بعد جرح أحد فخصت البشرى بالمؤمنين تصريحًا: ﴿لكم﴾؛ أما الأنفال فنزلت في قلب الحدث وكان كون البشرى لهم معلومًا من الخطاب، فاستغنى السياق عن المتعلق.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص706–708.","url":""}]},{"id":"s3-450","number":450,"surah":3,"verses":[10],"verseLabel":"آل عمران: 126؛ الأنفال: 10","question":"ما سرّ اختلاف الترتيب بين قوله تعالى في آل عمران ﴿ولتطمئن قلوبكم به﴾، وفي الأنفال ﴿ولتطمئن به قلوبكم﴾؟","answer":"مقام آل عمران مقام جبر القلوب بعد أحد، فقدم القلوب لتكون موضع العناية والمواساة؛ أما الأنفال فالمقام مقام الإمداد في بدر، فقدم ﴿به﴾ لربط الطمأنينة بسبب البشرى والإمداد ولإفادة الاختصاص.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص707–708.","url":""}]},{"id":"s3-451","number":451,"surah":3,"verses":[10],"verseLabel":"آل عمران: 126؛ الأنفال: 10","question":"لماذا ختمت آل عمران بـ﴿الله العزيز الحكيم﴾، وختمت الأنفال بـ﴿إن الله عزيز حكيم﴾؟","answer":"الأنفال نزلت وقت المواجهة والوعد لمّا يتحقق بعد، فناسبها توكيد العزة والحكمة بـ﴿إن﴾؛ أما آل عمران فتحكي نصرًا شوهد أثره، فتكفي الصفتان معرفتين بلا توكيد جديد.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص707–708.","url":""}]},{"id":"s3-452","number":452,"surah":3,"verses":[127],"verseLabel":"آل عمران: 127","question":"ما سرّ التعبير في قوله تعالى: ﴿ليقطع طرفًا من الذين كفروا﴾، وما صورة قطع الطرف؟","answer":"صوّر جماعة العدو جسمًا يُقطع طرف منه بالقتل والأسر، فيضعف باقيه؛ والتبعيض يطابق ما وقع من إصابة فريق لا استئصال الجميع.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص701–714.","url":""}]},{"id":"s3-453","number":453,"surah":3,"verses":[127],"verseLabel":"آل عمران: 127","question":"لماذا عطف ﴿أو يكبتهم﴾ على قطع الطرف؟","answer":"قطع الطرف إصابة جزء من قوة العدو بالقتل أو الأسر، أما الكبت فهو إذلاله ورده بالغيظ والخيبة؛ فعطفهما يبين غايتين للنصر: إنقاص القوة أو ردها مهزومة.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص701–714.","url":""}]},{"id":"s3-454","number":454,"surah":3,"verses":[127],"verseLabel":"آل عمران: 127","question":"ما سرّ التعبير في قوله تعالى: ﴿فينقلبوا خائبين﴾، فجعل رجوعهم انقلابًا؟","answer":"الانقلاب رجوع يتحول فيه صاحبه من حال إلى حال؛ فقد خرجوا يرجون الظفر ثم عادوا بخلاف مقصدهم، و﴿خَائِبِينَ﴾ تكشف ضياع الرجاء مع الهزيمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص701–714.","url":""}]},{"id":"s3-455","number":455,"surah":3,"verses":[128],"verseLabel":"آل عمران: 128","question":"لماذا اعترض السياق بقوله ﴿ليس لك من الأمر شيء﴾ مخاطبًا النبي ﷺ؟","answer":"الاعتراض يردّ أمر الهداية والجزاء إلى الله، ويعلّم أن وظيفة الرسول البلاغ والجهاد لا التحكم في مصائر القلوب.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص714–719.","url":""}]},{"id":"s3-456","number":456,"surah":3,"verses":[128],"verseLabel":"آل عمران: 128","question":"لماذا سوّى في الاحتمال بين ﴿يتوب عليهم﴾ و﴿يعذبهم﴾؟","answer":"جُعل أمرهم دائرًا بين أن يتوب الله عليهم أو يعذبهم لأن مصائر القلوب والجزاء ليست للنبي ﷺ؛ فباب التوبة غير مغلق، والعذاب عدل إن استمروا في ظلمهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص714–719.","url":""}]},{"id":"s3-457","number":457,"surah":3,"verses":[128],"verseLabel":"آل عمران: 128","question":"لماذا ختم بـ﴿فإنهم ظالمون﴾ لا: كافرون؟","answer":"﴿ظَالِمُونَ﴾ يبين سبب استحقاق العذاب: وضعوا أنفسهم والحق في غير موضعه بالكفر والعدوان. وهو وصف يشمل ما صدر منهم ويترك مع ذلك إمكان التوبة الذي ذكر قبله.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص714–719.","url":""}]},{"id":"s3-458","number":458,"surah":3,"verses":[129],"verseLabel":"آل عمران: 129","question":"لماذا قدّم المغفرة على العذاب؟","answer":"لأن الآية جاءت بعد فتح باب التوبة والدعاء على الظالمين، فقدم ما يلائم سعة الرحمة وإمكان الرجوع، ثم ذكر العذاب عدلًا لمن أصر.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص719–726.","url":""}]},{"id":"s3-459","number":459,"surah":3,"verses":[129],"verseLabel":"آل عمران: 129","question":"ما سرّ التعبير في قوله تعالى: ﴿يغفر لمن يشاء ويعذب من يشاء﴾ ثم ختم بـ﴿غفور رحيم﴾ دون اسم يدل على العقاب؟","answer":"الخاتمة تفتح باب الرجاء، وتبين أن المغفرة أثر الرحمة لا مجرد إسقاط العقوبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص719–726.","url":""}]},{"id":"s3-460","number":460,"surah":3,"verses":[130],"verseLabel":"آل عمران: 130","question":"ما سرّ التعبير في قوله تعالى: ﴿لا تأكلوا الربا﴾ مع أن التعامل به ليس أكلًا فقط؟","answer":"عُبر عن أخذ الربا بأكله لأن الأكل أبرز وجوه الانتفاع بالمال وغاية الاستيلاء عليه؛ فصار كناية عن تملكه والتصرف فيه، وفي الصورة تقبيح لابتلاع أموال الناس بالباطل.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص726–738.","url":""}]},{"id":"s3-461","number":461,"surah":3,"verses":[130],"verseLabel":"آل عمران: 130","question":"لماذا وصف الربا بـ﴿أضعافًا مضاعفة﴾؟","answer":"﴿أَضْعَافًا﴾ تصور الزيادة التي تجعل رأس المال أمثالًا، و﴿مُضَاعَفَةً﴾ تؤكد تكرر التضعيف مرة بعد مرة. والوصف يكشف الصورة الفادحة الشائعة للربا، ولا يفيد إباحة ما دونها؛ فالنهي عن أصل الربا.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص726–738.","url":""}]},{"id":"s3-462","number":462,"surah":3,"verses":[130],"verseLabel":"آل عمران: 130","question":"لماذا ختم النهي بـ﴿واتقوا الله لعلكم تفلحون﴾؟","answer":"ربطت الخاتمة ترك الربا بتقوى الله لأن الدافع إليه طمع خفي لا يضبطه إلا مراقبته، وجعلت الفلاح غايةً مرجوة لبيان أن الربح الحقيقي في الطاعة لا في الزيادة المحرمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص726–738.","url":""}]},{"id":"s3-463","number":463,"surah":3,"verses":[200],"verseLabel":"آل عمران: 130؛ آل عمران: 200","question":"لماذا خُتم النهي عن الربا وخُتمت السورة معًا بـ﴿واتقوا الله لعلكم تفلحون﴾؟","answer":"في آية الربا تربط الخاتمة الفلاح بتقوى الطمع المالي، وفي آخر السورة تجمع التقوى الصبر والمصابرة والرباط؛ فتكرارها يجعل التقوى أصل الفلاح في مجاهدة المال وفي مجاهدة العدو والنفس.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص726–738؛ ج6، ص543–564.","url":""}]},{"id":"s3-464","number":464,"surah":3,"verses":[131],"verseLabel":"آل عمران: 131","question":"ما سرّ التعبير في قوله تعالى: ﴿واتقوا النار التي أعدت للكافرين﴾ للمؤمنين؟","answer":"وُجه الخطاب إلى المؤمنين تحذيرًا من العمل الذي يقرب من سبيل الكافرين وعاقبتهم؛ ووصف النار بأنها ﴿أُعِدَّتْ لِلْكَافِرِينَ﴾ لا يمنع إنذار المؤمن من أسبابها، بل يزجره عن مشابهة أهلها.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص726–738.","url":""}]},{"id":"s3-465","number":465,"surah":3,"verses":[131],"verseLabel":"آل عمران: 131","question":"لماذا بُني ﴿أعدت﴾ للمجهول؟","answer":"بُني ﴿أُعِدَّتْ﴾ للمجهول لأن مُعِدَّها معلوم وهو الله، والعناية بحقيقة إعداد النار وتهيئتها للكافرين؛ فالصيغة تجعل حضور العاقبة هو موضع التخويف.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص726–738.","url":""}]},{"id":"s3-466","number":466,"surah":3,"verses":[132],"verseLabel":"آل عمران: 132","question":"لماذا جمع بين طاعة الله وطاعة الرسول بعد النهي عن الربا؟","answer":"طاعة الله امتثال أصل التحريم، وطاعة الرسول قبول بيانه وتطبيقه؛ فسد الطريق على من يدعي الإيمان ثم يرد الحكم العملي.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص738–747.","url":""}]},{"id":"s3-467","number":467,"surah":3,"verses":[132],"verseLabel":"آل عمران: 132","question":"ما سرّ التعبير في قوله تعالى: ﴿لعلكم ترحمون﴾ لا: لعلكم تفلحون كما في الآية السابقة؟","answer":"ختم النهي عن الربا بالتقوى والفلاح، ثم ختم الأمر بطاعة الله والرسول برجاء الرحمة؛ لأن دخول الجنة ليس بمجرد العمل بل برحمة الله، والطاعة سبب التعرض لها.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص738–747.","url":""}]},{"id":"s3-468","number":468,"surah":3,"verses":[133],"verseLabel":"آل عمران: 133","question":"ما سرّ التعبير في قوله تعالى: ﴿وسارعوا إلى مغفرة من ربكم وجنة﴾، وكيف يُسارَع إلى المغفرة؟","answer":"حُذف المضاف، أي سارعوا إلى الأعمال التي توجب المغفرة؛ فصُورت المغفرة والجنة غايةً يتجه إليها المتنافسون، ليبعث التعبير على المبادرة بالطاعات قبل الفوات.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص738–747.","url":""}]},{"id":"s3-469","number":469,"surah":3,"verses":[133],"verseLabel":"آل عمران: 133","question":"لماذا قدّم المغفرة على الجنة؟","answer":"المغفرة تزيل مانع الدخول أولًا، ثم تأتي الجنة غايةً بعد السلامة من الذنب؛ فرتب النظم التخلية قبل التحلية.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص738–747.","url":""}]},{"id":"s3-470","number":470,"surah":3,"verses":[133],"verseLabel":"آل عمران: 133","question":"لماذا وصف الجنة بأن عرضها السماوات والأرض ولم يذكر طولها؟","answer":"لأن العرض أقصر البعدين عادة؛ فإذا بلغ هذا الاتساع كان الطول أعظم، والمقصود تقريب سعة لا يحيط بها القياس البشري.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص738–747.","url":""}]},{"id":"s3-471","number":471,"surah":3,"verses":[133],"verseLabel":"آل عمران: 133","question":"ما سرّ التعبير في قوله تعالى: ﴿أعدت للمتقين﴾ في مقابل ﴿أعدت للكافرين﴾؟","answer":"جاء ﴿أُعِدَّتْ لِلْمُتَّقِينَ﴾ في مقابلة النار المعدة للكافرين؛ لتتقابل العاقبتان والطريقان: اجتناب المعصية بالتقوى يقود إلى الجنة، والإصرار على الكفر يقود إلى النار.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص738–747.","url":""}]},{"id":"s3-472","number":472,"surah":3,"verses":[21],"verseLabel":"آل عمران: 133؛ الحديد: 21","question":"ما سرّ اختلاف التعبير بين قوله تعالى في آل عمران ﴿وسارعوا﴾، وقوله تعالى في الحديد ﴿سابقوا﴾؟","answer":"المسارعة تركز على مبادرة الإنسان إلى أسباب المغفرة عقب أوامر التقوى والإنفاق، أما المسابقة فتضيف وجود متنافسين وطلب السبق، وهو أنسب بسياق الحديد الذي يعالج التفاوت في الإيمان والإنفاق.","sources":[{"label":"موسوعة التفسير البلاغي، ج60، ص178، الحديد: 21 في المقارنة بآل عمران: 133.","url":""}]},{"id":"s3-473","number":473,"surah":3,"verses":[21],"verseLabel":"آل عمران: 133؛ الحديد: 21","question":"ما سرّ اختلاف التعبير بين قوله تعالى في آل عمران ﴿جنة عرضها السماوات والأرض﴾، وفي الحديد ﴿جنة عرضها كعرض السماء والأرض﴾؟","answer":"آل عمران في مقام الحث المباشر فأثبتت السعة للجنة إبلاغًا في التعظيم، أما الحديد فجاءت بكاف التشبيه لتقريب ما لا يحيط به الحس إلى أوسع مشهود يعرفه المخاطب؛ والعبارتان تدلان على سعة خارجة عن القياس المعتاد.","sources":[{"label":"موسوعة التفسير البلاغي، ج60، ص195، الحديد: 21 في المقارنة بآل عمران: 133.","url":""}]},{"id":"s3-474","number":474,"surah":3,"verses":[134],"verseLabel":"آل عمران: 134","question":"لماذا قدّم الإنفاق في السراء والضراء على كظم الغيظ والعفو؟","answer":"بدأ ببذل المال في الحالين لأنه علامة عملية ظاهرة للتقوى، ثم ارتقى إلى ضبط النفس والعفو وهما أشق باطنًا؛ فجمع الإحسان بالمال والإحسان إلى المسيء.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص747–758.","url":""}]},{"id":"s3-475","number":475,"surah":3,"verses":[134],"verseLabel":"آل عمران: 134","question":"ما سرّ التعبير في قوله تعالى: ﴿الكاظمين الغيظ﴾، وما صورة كظم الغيظ؟","answer":"الكظم في الأصل حبس ما امتلأ به الوعاء وشد فمه؛ فصُور الغيظ شيئًا يملأ النفس ثم يحبسه صاحبه ولا يطلقه في أذى أو انتقام، مع قدرته على ذلك.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص747–758.","url":""}]},{"id":"s3-476","number":476,"surah":3,"verses":[134],"verseLabel":"آل عمران: 134","question":"لماذا عطف ﴿العافين عن الناس﴾ على كظم الغيظ؟","answer":"كظم الغيظ حبس أثره ومنع انفجاره، والعفو خطوة زائدة هي إسقاط المؤاخذة وترك الانتقام؛ فقد يكظم الإنسان غيظه ويبقي حقه، فجمع النص ضبط النفس والإحسان إلى المسيء.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص747–758.","url":""}]},{"id":"s3-477","number":477,"surah":3,"verses":[134],"verseLabel":"آل عمران: 134","question":"لماذا ختم الصفات بـ﴿والله يحب المحسنين﴾ مع أن أولها في المتقين؟","answer":"بدأت الآيات بصفات المتقين، فلما بلغت الإنفاق وكظم الغيظ والعفو سمت أصحابها محسنين؛ لأنهم تجاوزوا مجرد ترك الشر إلى بذل الخير. وخاتمة المحبة أعلى ترغيب في بلوغ هذه المرتبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص747–758.","url":""}]},{"id":"s3-478","number":478,"surah":3,"verses":[135],"verseLabel":"آل عمران: 135","question":"ما سرّ التعبير في قوله تعالى: ﴿فعلوا فاحشة أو ظلموا أنفسهم﴾، وما الفرق بينهما؟","answer":"الفاحشة هي الذنب البالغ في القبح أو الكبيرة، أما ظلم النفس فأعم فيشمل سائر الذنوب التي يجني بها المرء على نفسه؛ فعطف العام على الخاص ليستوعب ما عظم وما دونه.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص758–764.","url":""}]},{"id":"s3-479","number":479,"surah":3,"verses":[135],"verseLabel":"آل عمران: 135","question":"ما سرّ التعبير في قوله تعالى: ﴿ذكروا الله فاستغفروا لذنوبهم﴾، وما أثر الفاء؟","answer":"الفاء في ﴿فَاسْتَغْفَرُوا﴾ تفيد سرعة تعقب الاستغفار لذكر الله؛ فلا يستمرون في الغفلة بعد أن يستحضروا أمره ووعده ووعيده، بل يبادرون إلى التوبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص758–764.","url":""}]},{"id":"s3-480","number":480,"surah":3,"verses":[135],"verseLabel":"آل عمران: 135","question":"لماذا اعترض بقوله ﴿ومن يغفر الذنوب إلا الله﴾؟","answer":"الاستفهام إنكاري يفيد حصر مغفرة الذنوب في الله، وجاء اعتراضًا بين الاستغفار وعدم الإصرار ليقوي الرجاء ويحض على الإقبال عليه وحده؛ فلا ذنب يتعاظم على مغفرته لمن تاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص758–764.","url":""}]},{"id":"s3-481","number":481,"surah":3,"verses":[135],"verseLabel":"آل عمران: 135","question":"ما سرّ التعبير في قوله تعالى: ﴿ولم يصروا على ما فعلوا وهم يعلمون﴾؟","answer":"الإصرار ملازمة الذنب والعزم على البقاء عليه؛ فنفى عن المتقين دوام المعصية، لا أصل وقوع الزلل. و﴿وَهُمْ يَعْلَمُونَ﴾ تشدد قبح الاستمرار مع العلم بالتحريم، وتبين أن رجوعهم عن بصيرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص758–764.","url":""}]},{"id":"s3-482","number":482,"surah":3,"verses":[136],"verseLabel":"آل عمران: 136","question":"لماذا سميت المغفرة والجنات ﴿جزاءهم﴾؟","answer":"سميت المغفرة والجنات ﴿جَزَاءَهُمْ﴾ لربط الوعد بمبادرتهم إلى الاستغفار وترك الإصرار، ترغيبًا في العمل؛ وهو جزاء تفضل الله به ووعد، لا استحقاق مستقل عن رحمته.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص764–769.","url":""}]},{"id":"s3-483","number":483,"surah":3,"verses":[136],"verseLabel":"آل عمران: 136","question":"ما سرّ التعبير في قوله تعالى: ﴿تجري من تحتها الأنهار﴾، دون أن يقال: فيها؟","answer":"﴿مِنْ تَحْتِهَا﴾ تصور الأنهار جارية تحت أشجار الجنة وقصورها وفي أرضها، فتدل على إحاطتها بالعمران والخصب ودوام الماء، وهو أبلغ تصويرًا من ذكر وجود الأنهار «فيها» فقط.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص764–769.","url":""}]},{"id":"s3-484","number":484,"surah":3,"verses":[136],"verseLabel":"آل عمران: 136","question":"لماذا ختم بـ﴿ونعم أجر العاملين﴾؟","answer":"أسلوب المدح في ﴿نِعْمَ أَجْرُ الْعَامِلِينَ﴾ يعظم المغفرة والجنات، وتسميتها أجرًا تربط الرجاء بالعمل، مع بقاء الفضل لله؛ فختمت الصفات بحافز عملي لا بأمنية مجردة.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص764–769.","url":""}]},{"id":"s3-485","number":485,"surah":3,"verses":[137],"verseLabel":"آل عمران: 137","question":"ما سرّ التعبير في قوله تعالى: ﴿قد خلت من قبلكم سنن﴾، وكيف تخلو السنن؟","answer":"﴿خَلَتْ﴾ أي مضت وانقضت في الأمم السابقة وقائع وطرائق مطردة في نصر الحق وعاقبة التكذيب؛ فنسب المضي إلى السنن باعتبار ظهورها في أحداث وأمم مضت.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص769–775.","url":""}]},{"id":"s3-486","number":486,"surah":3,"verses":[137],"verseLabel":"آل عمران: 137","question":"لماذا أُمروا بالسير في الأرض والنظر في عاقبة المكذبين؟","answer":"لينتقل خبر السنن من السماع إلى الشاهد التاريخي، فيروا أن تداول الأيام لا يبطل عاقبة التكذيب وأن هزيمة عابرة لا تعني خذلان الحق.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص769–775.","url":""}]},{"id":"s3-487","number":487,"surah":3,"verses":[137],"verseLabel":"آل عمران: 137","question":"ما سرّ التعبير في قوله تعالى: ﴿كيف كان عاقبة المكذبين﴾ لا: ماذا كانت؟","answer":"﴿كيف﴾ تسأل عن هيئة المصير وفظاعته، فتدعو إلى تأمل آثار الهلاك وتفاصيله، لا إلى معرفة اسم العاقبة فقط.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص769–775.","url":""}]},{"id":"s3-488","number":488,"surah":3,"verses":[138],"verseLabel":"آل عمران: 138","question":"ما سرّ التعبير في قوله تعالى: ﴿هذا بيان للناس وهدى وموعظة للمتقين﴾، فجعل البيان للناس والهدى للمتقين؟","answer":"البيان مكشوف لجميع الناس، أما الاهتداء والاتعاظ فثمرة لا ينالها إلا من استعد بالتقوى؛ فوزعت الأوصاف بحسب التلقي.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص775–780.","url":""}]},{"id":"s3-489","number":489,"surah":3,"verses":[138],"verseLabel":"آل عمران: 138","question":"لماذا عطف الهدى والموعظة على البيان؟","answer":"البيان يكشف الحقيقة للعقول كلها، والهدى يدل المستجيب إلى الطريق، والموعظة تحرك القلب للعمل؛ فليست الألفاظ مترادفة بل مراحل أثر.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص775–780.","url":""}]},{"id":"s3-490","number":490,"surah":3,"verses":[139],"verseLabel":"آل عمران: 139","question":"لماذا جمع بين النهي عن الوهن والحزن؟","answer":"الوهن ضعف الإرادة عن المستقبل، والحزن ألم النفس على الماضي؛ فنهى عما يعطل الحركة من جهتي الزمن.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص780–786.","url":""}]},{"id":"s3-491","number":491,"surah":3,"verses":[139],"verseLabel":"آل عمران: 139","question":"ما سرّ التعبير في قوله تعالى: ﴿وأنتم الأعلون إن كنتم مؤمنين﴾؟","answer":"الجملة الحالية ﴿وَأَنْتُمُ الْأَعْلَوْنَ﴾ تثبت للمؤمنين علو الحجة والعاقبة بعد أُحد، والشرط ﴿إِنْ كُنْتُمْ مُؤْمِنِينَ﴾ يربط هذا العلو بحقيقة الإيمان والثبات، لا بمجرد الانتساب.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص780–786.","url":""}]},{"id":"s3-492","number":492,"surah":3,"verses":[140],"verseLabel":"آل عمران: 140","question":"ما سرّ التعبير في قوله تعالى: ﴿إن يمسسكم قرح فقد مس القوم قرح مثله﴾؟","answer":"استعملت ﴿إِنْ﴾ مع أن القرح وقع تنزيلًا للمحقق منزلة المحتمل تهوينًا لأثره، ثم سوّى التعبير بين الفريقين بتكرار ﴿مَسَّ﴾ و﴿قَرْحٌ﴾ وإضافة ﴿مِثْلُهُ﴾؛ فلا موجب لانهيار المؤمنين من ألم أصاب عدوهم مثله.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص786؛ ج6، ص10–17.","url":""}]},{"id":"s3-493","number":493,"surah":3,"verses":[140],"verseLabel":"آل عمران: 140","question":"ما سرّ التعبير في قوله تعالى: ﴿وتلك الأيام نداولها بين الناس﴾، وكيف تُداوَل الأيام؟","answer":"صوّر الأيام دولاً تنتقل بين الفرق؛ ليبين أن الغلبة لا تثبت لأحد، وأن تداولها ميدان لتمييز الإيمان واتخاذ الشهداء.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص786؛ ج6، ص10–17.","url":""}]},{"id":"s3-494","number":494,"surah":3,"verses":[140],"verseLabel":"آل عمران: 140","question":"ما سرّ التعبير في قوله تعالى: ﴿وليعلم الله الذين آمنوا﴾ مع أن الله يعلمهم قبل الامتحان؟","answer":"ليس المراد حدوث علم لم يكن؛ فعلم الله سابق محيط، وإنما المراد أن يظهر إيمان المؤمنين في الواقع متميزًا بالابتلاء، أو يتحقق المعلوم منهم فعلًا فيترتب عليه الجزاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص786؛ ج6، ص10–17.","url":""}]},{"id":"s3-495","number":495,"surah":3,"verses":[140],"verseLabel":"آل عمران: 140","question":"ما سرّ التعبير في قوله تعالى: ﴿ويتخذ منكم شهداء﴾، دون أن يقال: ويجعل بعضكم شهداء؟","answer":"﴿يَتَّخِذَ﴾ تتضمن الاختيار والاصطفاء والقرب، لا مجرد التصيير؛ فالشهادة منزلة يختار الله لها من المؤمنين، و﴿مِنْكُمْ﴾ تفيد أن المختارين بعض الجماعة.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص786؛ ج6، ص10–17.","url":""}]},{"id":"s3-496","number":496,"surah":3,"verses":[140],"verseLabel":"آل عمران: 140","question":"لماذا خُتمت الآية بـ﴿والله لا يحب الظالمين﴾؟","answer":"جاءت الخاتمة لتدفع توهم أن تداول النصر للكافرين محبة لهم؛ فالله لا يحب الظالمين، وإنما يجري التداول لحِكم الامتحان والتمييز واتخاذ الشهداء، ثم تكون العاقبة للحق.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص786؛ ج6، ص10–17.","url":""}]},{"id":"s3-497","number":497,"surah":3,"verses":[141],"verseLabel":"آل عمران: 141","question":"ما سرّ التعبير في قوله تعالى: ﴿وليمحص الله الذين آمنوا ويمحق الكافرين﴾؟","answer":"التمحيص تخليص الشيء مما يخالطه، فصُورت المحنة نارًا تنقي المؤمنين من الذنوب وتكشف صدقهم؛ والمحق إزالة الشيء ونقصه حتى يفنى، فكانت عاقبة الكافرين الاستئصال. وتقارب اللفظين يزيد المقابلة إحكامًا مع تضاد المصيرين.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص10–17.","url":""}]},{"id":"s3-498","number":498,"surah":3,"verses":[142],"verseLabel":"آل عمران: 142","question":"ما سرّ التعبير في قوله تعالى: ﴿أم حسبتم أن تدخلوا الجنة﴾ في صورة سؤال؟","answer":"الاستفهام ينكر حسبان دخول الجنة بلا جهاد وصبر يظهران في ميدان الابتلاء؛ فلا يكفي ادعاء الإيمان أو تمني منزلته، بل لا بد أن تتحقق آثاره.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص17–25.","url":""}]},{"id":"s3-499","number":499,"surah":3,"verses":[142],"verseLabel":"آل عمران: 142","question":"ما سرّ التعبير في قوله تعالى: ﴿ولما يعلم الله الذين جاهدوا منكم ويعلم الصابرين﴾؟","answer":"ليس المراد حدوث علم لله بعد خفائه؛ فعلمه سابق. وإنما ﴿لَمَّا يَعْلَمِ﴾ تنفي إلى ذلك الوقت ظهور الجهاد والصبر منهم في الواقع على الوجه الذي يترتب عليه التمييز والجزاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص17–25.","url":""}]},{"id":"s3-500","number":500,"surah":3,"verses":[142],"verseLabel":"آل عمران: 142","question":"لماذا غُيّرت الصياغة من ﴿الذين جاهدوا﴾ إلى ﴿الصابرين﴾؟","answer":"جاء ﴿الَّذِينَ جَاهَدُوا﴾ بالموصول والفعل لإبراز وقوع الجهاد منهم، وجاء ﴿الصَّابِرِينَ﴾ باسم الفاعل لإظهار الصبر صفةً راسخة ملازمة؛ لأن الثبات هو الذي يصون الجهاد عند الشدة.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص17–25.","url":""}]},{"id":"s3-501","number":501,"surah":3,"verses":[143],"verseLabel":"آل عمران: 143","question":"ما سرّ التعبير في قوله تعالى: ﴿ولقد كنتم تمنون الموت﴾ لا: الشهادة؟","answer":"عُبر بالموت لأنه حقيقة ما يواجهه المقاتل في طريق الشهادة، فتكشف العبارة جدية الأمنية وتمتحنها عند المعاينة؛ أما لفظ «الشهادة» فقد يستحضر شرف النتيجة دون شدة طريقها.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص25–33.","url":""}]},{"id":"s3-502","number":502,"surah":3,"verses":[143],"verseLabel":"آل عمران: 143","question":"ما سرّ التعبير في قوله تعالى: ﴿فقد رأيتموه وأنتم تنظرون﴾، وما الفرق بين الرؤية والنظر؟","answer":"الرؤية إدراك وقوع الموت الذي تمنوه، والنظر يفيد المعاينة المتعمدة المستمرة؛ فجمع حصول المشهد وشدة حضورهم له.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص30–31.","url":""}]},{"id":"s3-503","number":503,"surah":3,"verses":[144],"verseLabel":"آل عمران: 144","question":"ما سرّ التعبير في قوله تعالى: ﴿وما محمد إلا رسول﴾ بالقصر؟","answer":"القصر بـ﴿مَا... إِلَّا﴾ يقرر أن محمدًا ﷺ رسول تجري عليه سنن الرسل من الموت أو القتل، وأن بقاء الدين متعلق برسالة الله لا ببقاء شخص الرسول.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص33–48.","url":""}]},{"id":"s3-504","number":504,"surah":3,"verses":[144],"verseLabel":"آل عمران: 144","question":"ما سرّ التعبير في قوله تعالى: ﴿قد خلت من قبله الرسل﴾، دون أن يقال: الأنبياء؟","answer":"ذُكر ﴿الرُّسُلُ﴾ لأن وجه المقارنة هو الرسالة ومن يحملها: رسل سبقوه ومضوا وبقيت دعواتهم؛ وهذا أنسب من الوصف الأعم «الأنبياء».","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص33–48.","url":""}]},{"id":"s3-505","number":505,"surah":3,"verses":[144],"verseLabel":"آل عمران: 144","question":"لماذا قدّم ﴿مات﴾ على ﴿قتل﴾ في ﴿أفإن مات أو قتل﴾؟","answer":"قُدم الموت لأنه الطريق المعتاد الغالب لانقضاء الأجل، ثم عطف القتل بوصفه الاحتمال الآخر الذي أثير يوم أُحد؛ وفي الحالين لا يسوغ الانقلاب عن الدين.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص39.","url":""}]},{"id":"s3-506","number":506,"surah":3,"verses":[144],"verseLabel":"آل عمران: 144","question":"لماذا صوّر الارتداد بقوله ﴿انقلبتم على أعقابكم﴾؟","answer":"صوّر الردة رجوعًا جسديًا إلى الخلف بعد التقدم في الطريق؛ فتبدو خسارة من يربط الدين بحياة شخص.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص33–48.","url":""}]}]);
